def _warn_exception(context: str, exc: Exception | BaseException | None = None):

    try:

        msg = f"[{context}] {type(exc).__name__}: {exc}" if exc is not None else f"[{context}] swallowed exception"

        logging.getLogger(__name__).warning(msg)

    except (TypeError, ValueError, AttributeError, RuntimeError):

        return

