def _mojibake_token_count_in_file(path: Path) -> int:

    try:
        raw = path.read_bytes()
    except (OSError, ValueError, TypeError):
        return 0

    markers = (
        b"\xC3\x83",
        b"\xC3\xA2\xE2\x82\xAC",
        b"\xEF\xBF\xBD",
    )
    return int(sum(raw.count(m) for m in markers))


RUNTIME_EXPORT_DIR = RUNTIME_DB_DIR / "exports"



try:



    RUNTIME_EXPORT_DIR.mkdir(parents=True, exist_ok=True)



except OSError as _e:



    _warn_exception("silent_except", _e)

def _db_legacy_candidates(db_name: str):



    return [



        Path(ODDS_DIR) / db_name,



        SCRIPT_DIR / db_name,



    ]











def _resolve_runtime_db_path(db_name: str) -> Path:



    """



    Resolve runtime DB path and migrate legacy copy once if runtime file is absent.



    """



    target = RUNTIME_DB_DIR / db_name



    if target.exists():



        return target



    for src in _db_legacy_candidates(db_name):



        if src == target:



            continue



        try:



            if not src.exists():



                continue



            target.parent.mkdir(parents=True, exist_ok=True)



            target.write_bytes(src.read_bytes())



            return target



        except (TypeError, ValueError, AttributeError, KeyError):



            continue



    return target











def _resolve_runtime_data_file(file_name: str, legacy_dirs=None) -> Path:



    _cands = list(legacy_dirs or [])



    if not _cands:



        _cands = [Path(ODDS_DIR), SCRIPT_DIR]



    return _core_resolve_runtime_file(RUNTIME_DB_DIR, str(file_name), _cands)











def _runtime_export_path(prefix: str, ext: str) -> Path:



    """



    Build export path under runtime export folder; fall back to temp if needed.



    """



    ts = datetime.now().strftime("%Y%m%d_%H%M%S")



    _name = f"{prefix}_{ts}.{str(ext).lstrip('.')}"



    _target = RUNTIME_EXPORT_DIR / _name



    try:



        _target.parent.mkdir(parents=True, exist_ok=True)



        return _target



    except (RuntimeError, tk.TclError):



        _tmp = Path(tempfile.gettempdir()) / "SportsPhysicsEngine" / "exports"



        _tmp.mkdir(parents=True, exist_ok=True)



        return _tmp / _name











