_starters_df      = None



_arsenal_df       = None



_arsenal_fetching = False   # True while background fetch is running



_arsenal_progress = ""      # e.g. "[12/30] Max Fried (Yankees)"



_ARSENAL_STATE_LOCK = threading.Lock()







def log(msg, level="info"):



    global _LOG_QUEUE_DROPPED



    def _sanitize_ui_text(s):



        s = str(s)



        try:



            _clean_fn = globals().get("_clean_display_text")



            if callable(_clean_fn):



                s = str(_clean_fn(s))



        except (OSError, ValueError, TypeError) as _e:



            _warn_exception("silent_except", _e)

        # Keep UI logs ASCII-clean and deterministic; avoid brittle mojibake replacement maps.



        out = []



        for ch in s:



            o = ord(ch)



            if ch in "\t\r\n" or 32 <= o <= 126:



                out.append(ch)



            else:



                out.append("")



        return "".join(out)







    _clean_msg = _sanitize_ui_text(msg)



    try:



        getattr(logging, level)(_clean_msg)



    except GUI_ERRORS:



        logging.info(_clean_msg)



    if not _gui_ready:



        return



    ts = datetime.now().strftime("%H:%M:%S")



    try:



        _LOG_UI_QUEUE.put_nowait((ts, str(level), _clean_msg))



    except GUI_ERRORS:



        with _LOG_QUEUE_DROPPED_LOCK:



            _LOG_QUEUE_DROPPED += 1











def _arsenal_state_snapshot():



    """Thread-safe read snapshot for arsenal globals consumed by UI/render code."""



    with _ARSENAL_STATE_LOCK:



        return {



            "starters_df": _starters_df,



            "arsenal_df": _arsenal_df,



            "fetching": bool(_arsenal_fetching),



            "progress": str(_arsenal_progress or ""),



        }











def _arsenal_state_update(*, starters_df=None, arsenal_df=None, fetching=None, progress=None):



    """Thread-safe update for arsenal globals shared across worker/UI threads."""



    global _starters_df, _arsenal_df, _arsenal_fetching, _arsenal_progress



    with _ARSENAL_STATE_LOCK:



        if starters_df is not None:



            _starters_df = starters_df



        if arsenal_df is not None:



            _arsenal_df = arsenal_df



        if fetching is not None:



            _arsenal_fetching = bool(fetching)



        if progress is not None:



            _arsenal_progress = str(progress)











_PROXY_ENV_KEYS = (



    "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY",



    "http_proxy", "https_proxy", "all_proxy",



)











def _is_dead_loopback_proxy(value: str) -> bool:



    s = str(value or "").strip().lower()



    if not s:



        return False



    return (":9" in s) and any(tok in s for tok in ("127.0.0.1", "localhost", "::1"))











def _strip_dead_loopback_proxies(env_obj: dict) -> list:



    removed = []



    for k in _PROXY_ENV_KEYS:



        if k in env_obj and _is_dead_loopback_proxy(env_obj.get(k)):



            env_obj.pop(k, None)



            removed.append(k)



    if removed:



        # Preserve loopback bypass for local tooling.



        env_obj.setdefault("NO_PROXY", "localhost,127.0.0.1,::1")



        env_obj.setdefault("no_proxy", env_obj.get("NO_PROXY", "localhost,127.0.0.1,::1"))



    return removed











def _runtime_env_copy() -> dict:



    env = dict(os.environ)



    _strip_dead_loopback_proxies(env)



    env.setdefault("OVERLINE_RUNTIME_DB_DIR", str(RUNTIME_DB_DIR))



    return env











_removed_proxy_keys = _strip_dead_loopback_proxies(os.environ)



if _removed_proxy_keys:



    log(



        "Startup network hygiene: removed dead loopback proxy env vars "



        f"({', '.join(sorted(set(_removed_proxy_keys)))}) so live data fetches can run.",



        "warning",



    )











def _drain_log_queue():



    global _LOG_QUEUE_DROPPED



    if not _gui_ready:



        root.after(140, _drain_log_queue)



        return



    _processed = 0



    _touched_boxes = set()



    while _processed < 80:



        try:



            ts, level, msg = _LOG_UI_QUEUE.get_nowait()



        except ValueError:



            break



        if level == "error":



            _append_tab(err_box, ts, "ERROR", msg, _UI["danger"], autoscroll=False)



            _touched_boxes.add(err_box)



        elif level == "warning":



            _append_tab(data_box, ts, "WARN", msg, _UI["warning"], autoscroll=False)



            _touched_boxes.add(data_box)



        else:



            color = _UI["success"] if level == "info" else _UI["text_muted"]



            _append_tab(



                run_box,



                ts,



                "INFO" if level == "info" else "DEBUG",



                msg,



                color,



                autoscroll=False,



            )



            _touched_boxes.add(run_box)



        _processed += 1



    _dropped = 0



    with _LOG_QUEUE_DROPPED_LOCK:



        _dropped = int(_LOG_QUEUE_DROPPED)



        _LOG_QUEUE_DROPPED = 0



    if _dropped > 0:



        _append_tab(



            data_box,



            datetime.now().strftime("%H:%M:%S"),



            "WARN",



            f"Log overload: dropped {_dropped} UI lines (file log preserved).",



            _UI["warning"],



            autoscroll=False,



        )



        _touched_boxes.add(data_box)



        _processed += 1



    if _touched_boxes:



        for _box in _touched_boxes:



            try:



                _box.see(tk.END)



            except (OSError, ValueError, TypeError, requests.RequestException) as _e:



                _warn_exception("silent_except", _e)

    if _processed:



        _update_tab_badges()



    root.after(120, _drain_log_queue)











def _start_log_pump():



    global _LOG_PUMP_STARTED



    if _LOG_PUMP_STARTED:



        return



    _LOG_PUMP_STARTED = True



    root.after(80, _drain_log_queue)







def _append_tab(box, ts, tag, msg, color, autoscroll=True):



    box.config(state=tk.NORMAL)



    if color not in _LOG_TAG_COLORS_CONFIGURED:



        box.tag_config(color, foreground=color)



        _LOG_TAG_COLORS_CONFIGURED.add(color)



    box.insert(tk.END, f"{ts} [{tag}]  {msg}\n", color)



    try:



        _lines = max(int(box.index("end-1c").split(".")[0]) - 1, 0)



        if _lines > _LOG_MAX_LINES_PER_TAB:



            _drop = _lines - _LOG_MAX_LINES_PER_TAB



            box.delete("1.0", f"{_drop + 1}.0")



    except (OSError, ValueError, TypeError, RuntimeError):

        log("[grade] model weight tuning skipped due to recoverable error", "warning")



    if autoscroll:



        box.see(tk.END)



    box.config(state=tk.DISABLED)







def _update_tab_badges():



    try:



        e = max(int(err_box.index("end-1c").split(".")[0]) - 1, 0)



        w = max(int(data_box.index("end-1c").split(".")[0]) - 1, 0)



        diag_tabs.tab(1, text=f"  Errors ({e})  ")



        diag_tabs.tab(2, text=f"  Data Health ({w})  ")



    except (RuntimeError, tk.TclError) as _e:



        _warn_exception("silent_except", _e)

