def get_teams(league):



    return sorted(df[df["league"] == league]["team"].dropna().unique())







def _normalize_league_tag(league):



    lg = str(league or "").strip()



    if not lg:



        return ""



    up = lg.upper()



    for canonical, aliases in _VENUE_LEAGUE_ALIASES.items():



        if up == canonical or up in {a.upper() for a in aliases}:



            return canonical



    return up







def _same_league_tag(row_league, preferred_league):



    if not preferred_league:



        return True



    return _normalize_league_tag(row_league) == _normalize_league_tag(preferred_league)







def team_lookup_key(name: str, league: str | None = None) -> str:



    return _canonical_team_key(name, league=league)





def team_display_name(db_row, field: str = "team") -> str:



    try:



        return str((db_row or {}).get(field) or "").strip()



    except (TypeError, ValueError, AttributeError):



        return ""





def get_row(team, preferred_league=None):



    rows = df[df["team"] == team]



    if rows.empty:



        _target_key = team_lookup_key(team, league=preferred_league)



        try:



            rows = df[df["team"].apply(lambda _nm: team_lookup_key(_nm, league=preferred_league) == _target_key)]



        except (TypeError, ValueError, AttributeError, KeyError, IndexError, OSError):



            rows = df[df["team"] == team]



    if preferred_league:



        rows = rows[rows["league"].apply(lambda lg: _same_league_tag(lg, preferred_league))]



    if rows.empty:



        return None



    _tmp = rows.copy()



    if "is_primary_home" in _tmp.columns:



        _tmp["_is_primary_home"] = _tmp["is_primary_home"].astype(str).str.lower().isin({"1", "true", "yes", "y"})



    else:



        _tmp["_is_primary_home"] = False



    if "venue_priority" in _tmp.columns:



        _tmp["_venue_priority"] = pd.to_numeric(_tmp["venue_priority"], errors="coerce").fillna(9999)



    else:



        _tmp["_venue_priority"] = 9999



    _tmp = _tmp.sort_values(["_is_primary_home", "_venue_priority"], ascending=[False, True], kind="stable")



    return _tmp.iloc[0]







def safe(row, col):



    return row[col] if row is not None and col in row.index and pd.notna(row[col]) else ""











def _roof_is_indoor(roof_value) -> bool:



    roof = str(roof_value or "").strip().lower()



    return roof in {"closed", "dome", "dome_fixed", "retractable closed"}











def _orientation_float_or_none(value):



    try:



        if value is None:



            return None



        if isinstance(value, str):



            v = value.strip()



            if not v:



                return None



            if v.upper() in {"N/A", "NA", "NONE", "NULL"}:



                return None



            value = v



        f = float(value)



        if not math.isfinite(f):



            return None



        return f



    except (RuntimeError, tk.TclError):



        return None







_SAFE_FLOAT_WARN_CACHE = {}



_SAFE_FLOAT_WARN_LOCK = threading.Lock()







def _safe_float_warn(kind, label, val, default):



    """



    Rate-limit repetitive safe_float warnings so expected optional nulls do not



    drown out actionable errors. One warning per key per 120s.



    """



    try:



        key = (str(kind or ""), str(label or "value"), str(default))



        now = time.time()



        should_log = False



        with _SAFE_FLOAT_WARN_LOCK:



            last = float(_SAFE_FLOAT_WARN_CACHE.get(key, 0.0) or 0.0)



            if (now - last) >= 120.0:



                _SAFE_FLOAT_WARN_CACHE[key] = now



                should_log = True



        if not should_log:



            return



        if kind == "missing":



            log(f"Missing {label} -> using default {default}", "warning")



        else:



            log(f"Non-numeric {label} '{val}' -> using default {default}", "warning")



    except (AttributeError, KeyError, TypeError, ValueError):



        # Never let warning plumbing break core parsing path.



        pass







def safe_float(val, default=0.0, label="value", silent=False):



    _missing = False



    if val is None:



        _missing = True



    elif isinstance(val, str):



        _v = val.strip()



        _missing = (_v == "" or _v.upper() in {"N/A", "NA", "NONE", "NULL"})



    else:



        try:



            _missing = bool(pd.isna(val))



        except (OSError, ValueError, TypeError, json.JSONDecodeError):



            _missing = False



    if _missing:



        if default is None:



            return None



        if not silent:



            _safe_float_warn("missing", label, val, default)



        return default



    try:



        _f = float(val)



        if not math.isfinite(_f):



            raise ValueError("non-finite float")



        return _f



    except (ValueError, TypeError):



        if default is None:



            return None



        if not silent:



            _safe_float_warn("invalid", label, val, default)



        return default



