def _ctx_emoji(t):



    t=t.lower()



    for k,e in _CTX_EMOJI.items():



        if k in t: return e



    return "[CTX]"



def _espn_venue_cache_get(key):



    with _ESPN_VENUE_CACHE_LOCK:



        entry = _espn_venue_cache.get(key)



        if entry is not None:



            _espn_venue_cache.move_to_end(key, last=True)



    if entry is None:



        return False, None



    # Backward compatibility for legacy cache values.



    if not isinstance(entry, dict) or "ts" not in entry:



        return True, entry



    ts = entry.get("ts")



    if ts is None or (time.time() - float(ts)) > _ESPN_VENUE_CACHE_TTL_SEC:



        with _ESPN_VENUE_CACHE_LOCK:



            _espn_venue_cache.pop(key, None)



        return False, None



    return True, entry.get("value")







def _espn_venue_cache_put(key, value):



    with _ESPN_VENUE_CACHE_LOCK:



        _espn_venue_cache[key] = {"ts": time.time(), "value": value}



        _espn_venue_cache.move_to_end(key, last=True)



        if len(_espn_venue_cache) > _ESPN_VENUE_CACHE_MAX:



            _espn_venue_cache.popitem(last=False)







