_TEAM_ID_REGISTRY_LOCK = threading.Lock()



_TEAM_ID_REGISTRY_CACHE = {"sig": "", "data": {}}











def _team_alias_norm(name, league=None):



    s = _canonical_team_key(name, league=league)



    s = re.sub(r"[^a-z0-9 ]+", " ", str(s or "").lower())



    s = re.sub(r"\s+", " ", s).strip()



    return s











def _team_registry_signature(frame):



    try:



        if frame is None or getattr(frame, "empty", True):



            return "empty"



        _n = int(len(frame))



        _leagues = tuple(sorted(str(x).strip().upper() for x in frame["league"].dropna().astype(str).unique().tolist())) if "league" in frame.columns else ()



        _teams = tuple(sorted(str(x).strip().lower() for x in frame["team"].dropna().astype(str).unique().tolist())) if "team" in frame.columns else ()



        _head = _teams[:32]



        _tail = _teams[-32:] if len(_teams) > 32 else _teams



        return f"{_n}|{len(_leagues)}|{len(_teams)}|{hash((_head, _tail, _leagues))}"



    except GUI_ERRORS:



        return "unknown"











def _build_team_identity_registry(frame):



    reg = {



        "by_lg_canon": {},



        "alias_to_key": {},



        "ambiguous_keys": set(),



        "ambiguous_aliases": {},



    }



    if frame is None or getattr(frame, "empty", True):



        return reg



    if "league" not in frame.columns or "team" not in frame.columns:



        return reg







    buckets = {}



    for _, row in frame.iterrows():



        lg = _normalize_league_tag(row.get("league", ""))



        team = str(row.get("team", "") or "").strip()



        if not lg or not team:



            continue



        canon = _canonical_team_key(team, league=lg)



        if not canon:



            continue



        buckets.setdefault((lg, canon), set()).add(team)







    for (lg, canon), teams in buckets.items():



        team_list = sorted(str(t).strip() for t in teams if str(t).strip())



        if len(team_list) != 1:



            reg["ambiguous_keys"].add((lg, canon))



            continue



        team = team_list[0]



        team_id = f"{lg}:{re.sub(r'[^a-z0-9]+', '_', canon)}"



        rec = {



            "team_id": team_id,



            "league": lg,



            "team": team,



            "canon": canon,



            "aliases": set(),



        }



        alias_pool = {



            _team_alias_norm(team, league=lg),



            _team_alias_norm(canon, league=lg),



        }



        toks = [t for t in re.split(r"[^a-z0-9]+", _team_alias_norm(team, league=lg)) if t]



        if toks:



            alias_pool.add(toks[-1])



            alias_pool.add(toks[0])



            if len(toks) >= 2:



                alias_pool.add(" ".join(toks[-2:]))



                alias_pool.add(" ".join((toks[0], toks[-1])))



                alias_pool.add(" ".join(toks[:2]))



                alias_pool.add(" ".join(toks[:-1]))



        alias_pool.discard("")



        rec["aliases"] = set(alias_pool)



        reg["by_lg_canon"][(lg, canon)] = rec







    for key, rec in reg["by_lg_canon"].items():



        lg = rec["league"]



        for alias in set(rec.get("aliases", set())):



            akey = (lg, alias)



            prev = reg["alias_to_key"].get(akey)



            if prev is None:



                reg["alias_to_key"][akey] = key



            elif prev != key:



                reg["alias_to_key"][akey] = "__AMBIG__"



                reg["ambiguous_aliases"].setdefault(akey, set()).update({



                    reg["by_lg_canon"].get(prev, {}).get("team", ""),



                    rec.get("team", ""),



                })



    return reg











def _get_team_identity_registry(frame=None):



    if frame is None:



        frame = globals().get("df")



    sig = _team_registry_signature(frame)



    with _TEAM_ID_REGISTRY_LOCK:



        if _TEAM_ID_REGISTRY_CACHE.get("sig") == sig:



            return _TEAM_ID_REGISTRY_CACHE.get("data") or {}



        data = _build_team_identity_registry(frame)



        _TEAM_ID_REGISTRY_CACHE["sig"] = sig



        _TEAM_ID_REGISTRY_CACHE["data"] = data



        return data











def _registry_resolve_team_name(name, league=None, frame=None):



    """



    Resolve a raw team token to canonical team key + canonical team name using



    the identity registry. Returns None if unresolved/ambiguous.



    """



    lg = _normalize_league_tag(league or "")



    if not lg:



        return None



    reg = _get_team_identity_registry(frame=frame)



    if not isinstance(reg, dict):



        return None



    alias = _team_alias_norm(name, league=lg)



    if not alias:



        return None



    hit = (reg.get("alias_to_key") or {}).get((lg, alias))



    if hit == "__AMBIG__":



        return None



    if isinstance(hit, tuple):



        rec = (reg.get("by_lg_canon") or {}).get(hit)



        if isinstance(rec, dict):



            return {



                "league": lg,



                "canon": str(rec.get("canon") or ""),



                "team": str(rec.get("team") or ""),



                "team_id": str(rec.get("team_id") or ""),



                "method": "registry_alias",



            }



    ck = _canonical_team_key(name, league=lg)



    rec = (reg.get("by_lg_canon") or {}).get((lg, ck))



    if isinstance(rec, dict):



        return {



            "league": lg,



            "canon": str(rec.get("canon") or ""),



            "team": str(rec.get("team") or ""),



            "team_id": str(rec.get("team_id") or ""),



            "method": "registry_canon",



        }



    return None











def _canonical_team_key(name, league=None):



    raw = _strip_pitcher(str(name or "").strip())



    s = raw.lower().replace("&", " and ")



    s = re.sub(r"[^a-z0-9 ]+", " ", s)



    s = re.sub(r"\s+", " ", s).strip()



    if not s:



        return ""



    parts = s.split()



    if len(parts) >= 2 and parts[0] == "l" and parts[1] == "a":



        parts = ["los", "angeles"] + parts[2:]



    if len(parts) >= 2 and parts[0] == "n" and parts[1] == "y":



        parts = ["new", "york"] + parts[2:]



    if len(parts) >= 2 and parts[0] == "st":



        parts = ["saint"] + parts[1:]



    if parts and parts[0] == "ny":



        parts = ["new", "york"] + parts[1:]



    if parts and parts[0] == "la":



        parts = ["los", "angeles"] + parts[1:]



    s = " ".join(parts)



    if s.startswith("the "):



        s = s[4:].strip()



    canon = dict(_TEAM_CANON_OVERRIDES_BASE)



    _lg = _normalize_league_tag(league or "")



    _by_lg = _TEAM_CANON_OVERRIDES_BY_LEAGUE.get(_lg) if _lg else None



    if isinstance(_by_lg, dict):



        canon.update(_by_lg)



    _late_alias = globals().get("_TEAM_ALIAS_CANON")



    if isinstance(_late_alias, dict):



        for k, v in _late_alias.items():



            kk = re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", str(k or "").lower())).strip()



            vv = re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", str(v or "").lower())).strip()



            if kk and vv:



                canon[kk] = vv



    if _lg in {"NCAAB", "NCAAF"}:



        canon.update(_COLLEGE_TEAM_CANON_OVERRIDES)



    return canon.get(s, s)











def _team_match_score(left, right, league=None):



    a = _canonical_team_key(left, league=league)



    b = _canonical_team_key(right, league=league)



    if not a or not b:



        return 0.0



    if a == b:



        return 1.0



    ac = a.replace(" ", "")



    bc = b.replace(" ", "")



    if ac == bc:



        return 0.99



    at = set(a.split())



    bt = set(b.split())



    if not at or not bt:



        return 0.0



    overlap = len(at & bt)



    if overlap == 0:



        return 0.0



    contain = overlap / float(min(len(at), len(bt)))



    jacc = overlap / float(len(at | bt))



    tail_bonus = 0.12 if a.split()[-1] == b.split()[-1] else 0.0



    head_bonus = 0.08 if a.split()[0] == b.split()[0] else 0.0



    return min(0.99, (0.55 * contain) + (0.35 * jacc) + tail_bonus + head_bonus)











def _best_team_match(raw_name, candidates, league=None, min_score=TEAM_MATCH_MIN_SCORE, ambiguity_gap=0.03):

    rows = []



    target_canon = _canonical_team_key(raw_name, league=league)



    for cand in (candidates or []):



        sc = _team_match_score(raw_name, cand, league=league)



        if sc < min_score:



            continue



        ck = _canonical_team_key(cand, league=league)



        rows.append({



            "name": str(cand),



            "score": float(sc),



            "canon": ck,



            "len_delta": abs(len(ck) - len(target_canon)),



        })



    rows.sort(key=lambda r: (-r["score"], r["len_delta"], r["name"]))



    if not rows:



        return {"matched": None, "score": 0.0, "ambiguous": False, "candidates": []}



    best = rows[0]



    ambiguous = False



    if len(rows) > 1:



        nxt = rows[1]



        if nxt["canon"] != best["canon"] and nxt["score"] >= (best["score"] - ambiguity_gap):



            ambiguous = True



    return {



        "matched": best["name"],



        "score": round(best["score"], 4),



        "ambiguous": ambiguous,



        "candidates": rows[:5],



    }











def _safe_resolve_team_match(raw_name, frame, preferred_league=None, min_score=TEAM_MATCH_MIN_SCORE):

    normalized = _normalize_league_tag(preferred_league or "")

    result = _resolve_team_match_from_frame(raw_name, frame, preferred_league=normalized, min_score=min_score)

    if str(result.get("method", "")).lower() == "league_scope_empty":

        fallback = _resolve_team_match_from_frame(raw_name, frame, preferred_league=None, min_score=min_score)

        if fallback.get("team") and not fallback.get("ambiguous"):

            log(

                f"[team_match] league scope empty for '{raw_name}' in {normalized}; "

                f"fallback matched league={fallback.get('league','')}",

                "warning",

            )

            return fallback

    return result





def _resolve_team_match_from_frame(raw_name, frame, preferred_league=None, min_score=TEAM_MATCH_MIN_SCORE):

    out = {



        "team": None,



        "team_id": None,



        "league": None,



        "score": 0.0,



        "method": "none",



        "ambiguous": False,



        "candidates": [],



        "league_expected": _normalize_league_tag(preferred_league or ""),



        "league_found": "",



        "league_mismatch": False,



    }



    if not raw_name or frame is None or getattr(frame, "empty", True) or "team" not in frame.columns:



        return out



    scoped = frame



    if preferred_league and "league" in frame.columns:



        _sc = frame[frame["league"].apply(lambda lg: _same_league_tag(lg, preferred_league))]



        if _sc.empty:



            out["league"] = str(preferred_league or "")



            out["method"] = "league_scope_empty"



            return out



        scoped = _sc



    _reg = _get_team_identity_registry(scoped)



    _pref_lg = _normalize_league_tag(preferred_league or "")



    if _pref_lg:



        _target_alias = _team_alias_norm(raw_name, league=_pref_lg)



        _target_key = _canonical_team_key(raw_name, league=_pref_lg)



        _lg_key = (_pref_lg, _target_key)



        if _lg_key in set(_reg.get("ambiguous_keys", set()) or set()):



            out["ambiguous"] = True



            out["method"] = "registry_canonical_ambiguous"



            out["candidates"] = [{"name": _target_key, "score": 1.0, "canon": _target_key}]



            return out



        _rec = (_reg.get("by_lg_canon") or {}).get(_lg_key)



        if isinstance(_rec, dict) and _rec.get("team"):



            out["team"] = str(_rec.get("team"))



            out["team_id"] = str(_rec.get("team_id") or "")



            out["league"] = str(_rec.get("league") or _pref_lg)



            out["score"] = 1.0



            out["method"] = "registry_canonical_id"



            return out



        _a_key = (_pref_lg, _target_alias)



        _hit = (_reg.get("alias_to_key") or {}).get(_a_key)



        if _hit == "__AMBIG__":



            out["ambiguous"] = True



            out["method"] = "registry_alias_ambiguous"



            _teams = sorted(t for t in set((_reg.get("ambiguous_aliases") or {}).get(_a_key, set())) if t)



            out["candidates"] = [{"name": t, "score": 0.98, "canon": _canonical_team_key(t, league=_pref_lg)} for t in _teams[:5]]



            return out



        if isinstance(_hit, tuple):



            _rec = (_reg.get("by_lg_canon") or {}).get(_hit)



            if isinstance(_rec, dict) and _rec.get("team"):



                out["team"] = str(_rec.get("team"))



                out["team_id"] = str(_rec.get("team_id") or "")



                out["league"] = str(_rec.get("league") or _pref_lg)



                out["score"] = 0.98



                out["method"] = "registry_alias_id"



                return out



    teams = [str(t) for t in scoped["team"].dropna().astype(str).unique().tolist() if str(t).strip()]



    target_key = _canonical_team_key(raw_name, league=preferred_league)



    exact = [t for t in teams if _canonical_team_key(t, league=preferred_league) == target_key]



    if len(exact) == 1:



        team = exact[0]



        rows = scoped[scoped["team"].astype(str) == team]



        out["team"] = team



        out["league"] = str(rows["league"].iloc[0]) if (not rows.empty and "league" in rows.columns) else str(preferred_league or "")



        out["team_id"] = f"{_normalize_league_tag(out['league'])}:{re.sub(r'[^a-z0-9]+', '_', _canonical_team_key(team, league=out['league']))}"



        out["score"] = 1.0



        out["method"] = "canonical_exact"



        return out



    if len(exact) > 1:



        out["ambiguous"] = True



        out["method"] = "canonical_exact_ambiguous"



        out["candidates"] = [{"name": x, "score": 1.0, "canon": target_key} for x in exact[:5]]



        return out



    best = _best_team_match(raw_name, teams, league=preferred_league, min_score=min_score)



    out["candidates"] = best.get("candidates", [])



    out["ambiguous"] = bool(best.get("ambiguous"))



    if best.get("matched") and not out["ambiguous"]:



        team = str(best["matched"])



        rows = scoped[scoped["team"].astype(str) == team]



        out["team"] = team



        out["league"] = str(rows["league"].iloc[0]) if (not rows.empty and "league" in rows.columns) else str(preferred_league or "")



        out["team_id"] = f"{_normalize_league_tag(out['league'])}:{re.sub(r'[^a-z0-9]+', '_', _canonical_team_key(team, league=out['league']))}"



        out["score"] = float(best.get("score", 0.0))



        out["method"] = "token_weighted"



        return out



    if best.get("matched") and out["ambiguous"]:



        out["method"] = "token_weighted_ambiguous"



    _exp = _normalize_league_tag(preferred_league or "")



    _found = _normalize_league_tag(out.get("league", "") or "")



    if _exp and out.get("team") and _found and not _same_league_tag(_found, _exp):



        out["league_mismatch"] = True



        out["league_expected"] = _exp



        out["league_found"] = _found



        out["team"] = None



        out["team_id"] = None



        out["score"] = 0.0



        out["method"] = f"{out.get('method','none')}_league_mismatch_blocked"



    return out







def _resolve_game_venue(sport, away_team, home_team, game_date_str):



    key=(sport,away_team.lower(),home_team.lower(),game_date_str)



    _ok, _cached = _espn_venue_cache_get(key)



    if _ok:



        return _cached



    if sport not in ESPN_SPORT_MAP:



        _espn_venue_cache_put(key, None)



        return None



    try:



        import urllib.request as _ur, json as _j, time as _t



        sp,lg,params=ESPN_SPORT_MAP[sport]



        url=(f"https://site.api.espn.com/apis/site/v2/sports/{sp}/{lg}/scoreboard"



             f"dates={game_date_str.replace('-','')}&{params}")



        _t.sleep(0.25)



        with _ur.urlopen(url,timeout=9) as r:



            data=_j.loads(r.read())







        _event_matches = []



        for event in data.get("events", []):



            comp = (event.get("competitions") or [{}])[0]



            ea = ""



            eh = ""



            for c in comp.get("competitors", []):



                nm = c.get("team", {}).get("displayName", "")



                if c.get("homeAway") == "away":



                    ea = nm



                else:



                    eh = nm



            a_sc = _team_match_score(away_team, ea, league=sport)



            h_sc = _team_match_score(home_team, eh, league=sport)



            if min(a_sc, h_sc) < TEAM_MATCH_MIN_SCORE:

                continue



            _event_matches.append({



                "event": event,



                "comp": comp,



                "score": round((a_sc + h_sc) / 2.0, 4),



                "a_sc": round(a_sc, 4),



                "h_sc": round(h_sc, 4),



                "ea": ea,



                "eh": eh,



            })







        if not _event_matches:



            _espn_venue_cache_put(key, None)



            return None







        _event_matches.sort(key=lambda r: (-r["score"], -r["a_sc"], -r["h_sc"]))



        _best = _event_matches[0]



        if len(_event_matches) > 1 and _event_matches[1]["score"] >= (_best["score"] - 0.03):



            log(



                f"ESPN venue ambiguous for {sport} {away_team}@{home_team} ({game_date_str}): "



                f"{_best['ea']}@{_best['eh']} vs {_event_matches[1]['ea']}@{_event_matches[1]['eh']}",



                "warning",



            )



            _espn_venue_cache_put(key, None)



            return None







        event = _best["event"]



        comp = _best["comp"]



        v=comp.get("venue",{}); addr=v.get("address",{})



        vname=v.get("fullName",""); city=addr.get("city",""); state=addr.get("state","")



        indoor=bool(v.get("indoor",False)); neutral=bool(comp.get("neutralSite",False))



        lat=lon=elev=None



        loc=v.get("location",{})



        if loc:



            lat=loc.get("latitude") or loc.get("lat")



            lon=loc.get("longitude") or loc.get("lon") or loc.get("lng")



        if (lat is None or lon is None) and (vname or city):



            for _gq in ([f"{vname} {city} {state}"] if vname else []) + ([f"{city} {state} USA"] if city else []):



                try:



                    _gq2=_gq.strip().replace(" ","+")



                    _req=__import__("urllib.request",fromlist=["Request"]).Request(



                        f"https://nominatim.openstreetmap.org/searchq={_gq2}&format=json&limit=1",



                        headers={"User-Agent":"AirDensityApp/1.0"})



                    with _ur.urlopen(_req, timeout=7) as _gr:



                        _rs=(_j.loads(_gr.read()) or [{}])[0]



                    if _rs.get("lat") and _rs.get("lon"):



                        lat=float(_rs["lat"]); lon=float(_rs["lon"]); break



                except OSError as _e:



                    _warn_exception("silent_except", _e)

            if not (lat and lon) and city:



                try:



                    _gq3=f"{city} {state} USA".replace(" ","+")



                    with _ur.urlopen(f"https://geocoding-api.open-meteo.com/v1/searchname={_gq3}&count=1&format=json",timeout=6) as _gr2:



                        _rs2=(_j.loads(_gr2.read()).get("results") or [{}])[0]



                    lat=_rs2.get("latitude"); lon=_rs2.get("longitude")



                    if _rs2.get("elevation"): elev=_rs2["elevation"]*3.28084



                except (TypeError, ValueError, KeyError) as _e:



                    _warn_exception("silent_except", _e)

        if elev is None and lat and lon:



            try:



                with _ur.urlopen(f"https://api.open-elevation.com/api/v1/lookuplocations={lat},{lon}",timeout=6) as er:



                    em=(_j.loads(er.read()).get("results") or [{}])[0].get("elevation")



                if em is not None: elev=em*3.28084



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

        gctx=""; gemoji=""; series_sum=""



        for note in comp.get("notes",[]):



            nh=note.get("headline","").strip()



            if nh:



                gctx=nh



                gemoji=_ctx_emoji(nh)



                break



        stype=event.get("season",{}).get("type",2)



        if not gctx and stype==3:



            gctx = "POSTSEASON"



            gemoji = "[PLAYOFF]"



        sr=comp.get("series",{})



        if sr:



            series_sum=sr.get("summary","") or sr.get("title","")



        result={"venue_name":vname,"city":city,"state":state,



                "lat":float(lat) if lat is not None else None,



                "lon":float(lon) if lon is not None else None,



                "indoor":indoor,"elevation":float(elev) if elev is not None else None,



                "neutral_site":neutral,"game_context":gctx,"ctx_emoji":gemoji,



                "series_summary":series_sum,"season_type":stype,"source":"ESPN",



                "match_score": _best["score"]}



        _espn_venue_cache_put(key, result)



        log(f"ESPN venue: {vname}, {city} {state}{' [NEUTRAL]' if neutral else ''}{' | '+gctx if gctx else ''}","info")



        return result



    except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as ex:



        log(f"ESPN venue lookup failed ({away_team}@{home_team}): {ex}","warning")



    _espn_venue_cache_put(key, None)



    return None







_weather_fallback      = None   # No fallback: missing weather means no physics analysis.



_weather_used_fallback = False



_weather_source_label  = "[OK] Live (current)"



_weather_key_missing_logged = False



_weather_auth_block_until = 0.0



_weather_auth_error_logged = False



_weather_auth_block_seconds = 900



_weather_cache_lock = threading.Lock()



_weather_state_lock = threading.Lock()



_weather_current_cache = {}



_weather_forecast_cache = {}



_weather_current_ttl_sec = 180



_weather_forecast_ttl_sec = 900



_weather_key_refresh_interval_sec = 15



_weather_last_key_refresh_ts = 0.0











def _wx_cache_key(lat, lon):



    try:



        return (round(float(lat), 4), round(float(lon), 4))



    except GUI_ERRORS:



        return (str(lat), str(lon))











def _wx_cache_get(store: dict, key, ttl_sec: int):



    now_ts = time.time()



    with _weather_cache_lock:



        rec = store.get(key)



        if not rec:



            return False, None



        age = now_ts - float(rec.get("ts", 0.0))



        if age > max(1, int(ttl_sec)):



            store.pop(key, None)



            return False, None



        return True, rec.get("value")











def _wx_cache_put(store: dict, key, value):



    with _weather_cache_lock:



        store[key] = {"ts": time.time(), "value": value}











def _refresh_openweather_api_key_runtime(force: bool = False) -> str:



    """Allow live key rotation without app restart."""



    global OPENWEATHER_API_KEY, _weather_last_key_refresh_ts



    global _weather_auth_block_until, _weather_auth_error_logged, _weather_key_missing_logged



    now_ts = time.time()



    old_key = ""



    new_key = ""



    with _weather_state_lock:



        if (not force) and (now_ts - float(_weather_last_key_refresh_ts) < float(_weather_key_refresh_interval_sec)):



            return str(OPENWEATHER_API_KEY or "").strip()



        _weather_last_key_refresh_ts = now_ts



        old_key = str(OPENWEATHER_API_KEY or "").strip()



        new_key = str(_load_openweather_api_key() or "").strip()



        if new_key == old_key:



            return new_key



        OPENWEATHER_API_KEY = new_key



        _weather_auth_block_until = 0.0



        _weather_auth_error_logged = False



        _weather_key_missing_logged = False



    with _weather_cache_lock:



        _weather_current_cache.clear()



        _weather_forecast_cache.clear()



    if new_key:



        log("OpenWeather key refreshed at runtime; weather auth backoff reset.", "info")



    else:



        log("OpenWeather key removed at runtime.", "warning")



    return new_key











def _openweather_is_auth_blocked() -> bool:



    global _weather_auth_error_logged



    now_ts = time.time()



    with _weather_state_lock:



        blocked = bool(_weather_auth_block_until and now_ts < _weather_auth_block_until)



        if blocked and not _weather_auth_error_logged:



            wait_sec = max(1, int(_weather_auth_block_until - now_ts))



            log(



                "OpenWeather calls suppressed after 401 Unauthorized. "



                f"Retrying automatically in ~{wait_sec}s; key updates are picked up without restart.",



                "warning",



            )



            _weather_auth_error_logged = True



        return blocked











def _mark_openweather_401(context_label: str) -> None:



    global _weather_auth_block_until, _weather_auth_error_logged



    with _weather_state_lock:



        _weather_auth_block_until = time.time() + float(_weather_auth_block_seconds)



        _weather_auth_error_logged = True



    log(



        f"{context_label} API rejected OPENWEATHER_API_KEY/OWM_API_KEY (401 Unauthorized). "



        f"Set a valid key in env var or file: {OPENWEATHER_KEY_FILE}",



        "error",



    )











def _clear_openweather_auth_backoff() -> None:



    global _weather_auth_block_until, _weather_auth_error_logged



    with _weather_state_lock:



        _weather_auth_block_until = 0.0



        _weather_auth_error_logged = False







def get_weather(lat, lon):



    global _weather_used_fallback, _weather_source_label, _weather_key_missing_logged



    _weather_used_fallback = False



    _weather_source_label = "[OK] Live (current)"



    _refresh_openweather_api_key_runtime()



    if not OPENWEATHER_API_KEY:



        if not _weather_key_missing_logged:



            log(



                f"No OpenWeather API key configured. Set OPENWEATHER_API_KEY (or OWM_API_KEY) "



                f"or create this file with your key: {OPENWEATHER_KEY_FILE}",



                "warning",



            )



            _weather_key_missing_logged = True



        _weather_source_label = "[WARN] No API key"



        return None



    if _openweather_is_auth_blocked():



        _weather_source_label = "[WARN] Auth blocked"



        return None



    try:



        lat_f, lon_f = float(lat), float(lon)



    except (ValueError, TypeError):



        log(f"Invalid lat/lon - cannot fetch weather.", "error")



        _weather_source_label = "[WARN] Invalid coords"



        return None



    if not (math.isfinite(lat_f) and math.isfinite(lon_f)):



        log("Invalid lat/lon (non-finite) - cannot fetch weather.", "error")



        _weather_source_label = "[WARN] Invalid coords"



        return None



    _ckey = _wx_cache_key(lat_f, lon_f)



    _cached_ok, _cached_val = _wx_cache_get(_weather_current_cache, _ckey, _weather_current_ttl_sec)



    if _cached_ok and isinstance(_cached_val, dict):



        _weather_source_label = "[OK] Cache (current)"



        return dict(_cached_val)



    url = "https://api.openweathermap.org/data/2.5/weather"



    params = {



        "lat": lat_f,



        "lon": lon_f,



        "appid": OPENWEATHER_API_KEY,



        "units": "imperial",



    }



    try:



        t0  = datetime.now()



        r   = requests.get(url, params=params, timeout=5)



        r.raise_for_status()



        d   = r.json()



        ms  = int((datetime.now() - t0).total_seconds() * 1000)



        main = d.get("main", {})



        wind = d.get("wind", {})



        if not main:



            _weather_source_label = "[WARN] Missing weather payload"



            return None



        _t  = main.get("temp")



        _h  = main.get("humidity")



        _p  = main.get("pressure")



        _ws = wind.get("speed") if wind else None



        _wd = wind.get("deg")   if wind else None



        # If any critical field is missing, weather is unusable



        if _t is None or _h is None or _p is None:



            log("Weather API returned incomplete data (missing temp/humidity/pressure) - analysis suppressed.", "warning")



            return None



        result = {



            "temp":       float(_t),



            "humidity":   float(_h),



            "pressure":   float(_p) * 0.02953,



            "wind_speed": float(_ws) if _ws is not None else None,



            "wind_dir":   float(_wd) if _wd is not None else None,



        }



        _clear_openweather_auth_backoff()



        _wx_cache_put(_weather_current_cache, _ckey, result)



        _weather_source_label = "[OK] Live (current)"



        log(f"Weather OK ({ms}ms)", "debug")



        return result



    except requests.HTTPError as e:



        _code = None



        try:



            _code = e.response.status_code



        except (AttributeError, TypeError):



            _code = None



        if _code == 401:



            _weather_source_label = "[ERROR] 401 unauthorized"



            _mark_openweather_401("Weather")



            return None



        log(f"Weather API HTTP error: {e}", "error")



    except (requests.RequestException, OSError, ValueError, TypeError) as e:



        log(f"Weather API error: {e}", "error")



    _weather_source_label = "[WARN] Weather unavailable"



    return None











# =========================



# GAME-TIME WEATHER FORECAST



# =========================



def _parse_game_time(game_time_str):



    """Parse strings like '4/5 1:35PM', '04/05 13:35', 'Apr 5 1:35PM' into datetime.



    Always injects the current year into the format string to avoid the Python 3.14+



    DeprecationWarning about year-less date parsing."""



    if not game_time_str or str(game_time_str).strip() in ["", "nan", "None"]:



        return None



    s = str(game_time_str).strip()



    # Strip trailing timezone labels commonly present in odds feeds ("ET", "EDT", etc.).



    s = re.sub(r"\b(:ET|EST|EDT|CT|CST|CDT|MT|MST|MDT|PT|PST|PDT)\b", "", s, flags=re.IGNORECASE)



    s = re.sub(r"\s+", " ", s).strip()



    if not s:



        return None



    _now_local = datetime.now()



    yr  = _now_local.year



    ys  = str(yr)                  # e.g. "2026"



    _has_year_token = bool(re.search(r"\b\d{4}\b", s))







    # Each entry: (format_string, string_to_parse)



    # Year-less formats: prepend the year so strptime never guesses



    candidates = [



        ("%Y-%m-%d %H:%M",    s),                  # already has year



        ("%m/%d/%Y %I:%M%p",  s),



        ("%m/%d/%Y %I:%M %p", s),



        ("%m/%d/%Y %H:%M",    s),



        ("%Y %m/%d %I:%M%p",  ys + " " + s),



        ("%Y %m/%d %I:%M %p", ys + " " + s),



        ("%Y %m/%d %H:%M",    ys + " " + s),



        ("%Y %b %d %I:%M%p",  ys + " " + s),



        ("%Y %b %d %I:%M %p", ys + " " + s),



        ("%Y %B %d %I:%M%p",  ys + " " + s),



        ("%Y %B %d %I:%M %p", ys + " " + s),



    ]



    for fmt, target in candidates:



        try:



            _dt = datetime.strptime(target, fmt)



            # If input had no year token, avoid mis-assigning cross-year rows



            # deep into the future (common in historical grading replays).



            if not _has_year_token:



                try:



                    _diff_days = (_dt - _now_local).days

                    if _diff_days > 180:

                        _dt = _dt.replace(year=_dt.year - 1)

                    elif _diff_days < -180:

                        _dt = _dt.replace(year=_dt.year + 1)



                except (TypeError, ValueError) as _e:



                    _warn_exception("silent_except", _e)

            return _dt



        except ValueError:



            continue



    return None







def _explicit_game_date_str(game_time_str):



    """



    Return YYYY-MM-DD parsed from the matchup record's game_time field.



    Returns None when unparseable. No silent fallback to "today".



    """



    _dt = _parse_game_time(game_time_str)



    if _dt is None:



        return None



    return _dt.strftime("%Y-%m-%d")











_TZ_TOKEN_TO_ZONE = {



    "ET": "America/New_York",



    "EST": "America/New_York",



    "EDT": "America/New_York",



    "CT": "America/Chicago",



    "CST": "America/Chicago",



    "CDT": "America/Chicago",



    "MT": "America/Denver",



    "MST": "America/Denver",



    "MDT": "America/Denver",



    "PT": "America/Los_Angeles",



    "PST": "America/Los_Angeles",



    "PDT": "America/Los_Angeles",



}











def _extract_time_zone_token(raw_time):



    _m = re.search(



        r"\b(ET|EST|EDT|CT|CST|CDT|MT|MST|MDT|PT|PST|PDT)\b",



        str(raw_time or ""),



        flags=re.IGNORECASE,



    )



    return str(_m.group(1)).upper() if _m else "ET"











def _game_start_et(game_time_str):



    """Best-effort parsed game start, normalized to America/New_York."""



    _raw = str(game_time_str or "").strip()



    if not _raw:



        return None



    _dt = _parse_game_time(_raw)



    if _dt is None:



        return None



    _tz_name = _TZ_TOKEN_TO_ZONE.get(_extract_time_zone_token(_raw), "America/New_York")



    try:



        _src_tz = ZoneInfo(_tz_name)



    except GUI_ERRORS:



        _src_tz = ZoneInfo("America/New_York")



    if _dt.tzinfo is None:



        _aware = _dt.replace(tzinfo=_src_tz)



    else:



        _aware = _dt.astimezone(_src_tz)



    return _aware.astimezone(ZoneInfo("America/New_York"))











def _game_has_started(game_time_str, grace_minutes=3, now_et=None):



    _start_et = _game_start_et(game_time_str)



    if _start_et is None:



        return False, None



    if now_et is None:



        _now_et = datetime.now(ZoneInfo("America/New_York"))



    else:



        _now_et = now_et.astimezone(ZoneInfo("America/New_York")) if now_et.tzinfo else now_et.replace(tzinfo=ZoneInfo("America/New_York"))



    try:



        _grace = max(0, int(grace_minutes))



    except GUI_ERRORS:



        _grace = 0



    return _now_et >= (_start_et + timedelta(minutes=_grace)), _start_et











def _parse_explicit_game_date_tokens(game_date_str: str):



    _raw = str(game_date_str or "").strip()



    if not _raw:



        return None



    for _fmt in ("%Y-%m-%d", "%Y%m%d"):



        try:



            _dt = datetime.strptime(_raw, _fmt)



            return (_dt.strftime("%Y-%m-%d"), _dt.strftime("%Y%m%d"))



        except ValueError:



            continue



    return None











def _explicit_game_date_obj(game_date_str: str):



    _tok = _parse_explicit_game_date_tokens(game_date_str)



    if not _tok:



        return None



    try:



        return datetime.strptime(_tok[0], "%Y-%m-%d").date()



    except GUI_ERRORS:



        return None











def _officials_policy_for_league(league: str) -> dict:



    lg = str(league or "").upper().strip()



    if lg in ("NCAAB", "NCAAF"):



        return {



            "enabled": False,



            "missing_neutral": True,



            "reason": "Officials excluded by policy for NCAA basketball/football.",



        }



    if lg in ("MLB", "NBA", "NHL", "NFL"):



        return {



            "enabled": True,



            "missing_neutral": True,



            "reason": "Officials optional-neutral for this league.",



        }



    return {



        "enabled": False,



        "missing_neutral": True,



        "reason": "Officials not configured for this league.",



    }











def _venue_zoneinfo_from_lon(lon):



    """Best-effort venue timezone from longitude for US sports venues."""



    try:



        tz_label, _ = _lon_to_tz(lon)



    except GUI_ERRORS:



        tz_label = "ET"



    tz_name = {



        "ET": "America/New_York",



        "CT": "America/Chicago",



        "MT": "America/Denver",



        "PT": "America/Los_Angeles",



    }.get(tz_label, "America/New_York")



    try:



        return ZoneInfo(tz_name)



    except GUI_ERRORS:



        return ZoneInfo("America/New_York")











def get_weather_at_gametime(lat, lon, game_time_str):



    """Fetch the OWM 3-hour forecast closest to game time.



    Falls back to current-conditions get_weather() if game time cannot be parsed



    or if the game is already in progress / past.



    Sets globals _weather_used_fallback and _weather_source_label."""



    global _weather_used_fallback, _weather_source_label, _weather_key_missing_logged



    _weather_used_fallback = False



    _refresh_openweather_api_key_runtime()



    if not OPENWEATHER_API_KEY:



        if not _weather_key_missing_logged:



            log(



                f"No OpenWeather API key configured. Set OPENWEATHER_API_KEY (or OWM_API_KEY) "



                f"or create this file with your key: {OPENWEATHER_KEY_FILE}",



                "warning",



            )



            _weather_key_missing_logged = True



        _weather_source_label = "[WARN] No API key"



        return None



    if _openweather_is_auth_blocked():



        _weather_source_label = "[WARN] Auth blocked"



        return None







    try:



        lat_f, lon_f = float(lat), float(lon)



    except (ValueError, TypeError):



        log("Invalid lat/lon for forecast fetch.", "error")



        _weather_source_label = "[WARN] Invalid coords"



        return None



    if not (math.isfinite(lat_f) and math.isfinite(lon_f)):



        log("Invalid lat/lon (non-finite) for forecast fetch.", "error")



        _weather_source_label = "[WARN] Invalid coords"



        return None







    game_dt = _parse_game_time(game_time_str)



    if game_dt is None:



        _weather_source_label = "[WARN] Invalid game time"



        return None







    venue_tz = _venue_zoneinfo_from_lon(lon_f)



    if game_dt.tzinfo is None:



        game_dt_local = game_dt.replace(tzinfo=venue_tz)



    else:



        game_dt_local = game_dt.astimezone(venue_tz)



    game_dt_utc = game_dt_local.astimezone(timezone.utc)







    _fkey = (_wx_cache_key(lat_f, lon_f), str(game_time_str or "").strip().lower())



    _cached_ok, _cached_val = _wx_cache_get(_weather_forecast_cache, _fkey, _weather_forecast_ttl_sec)



    if _cached_ok and isinstance(_cached_val, dict):



        _weather_source_label = "[OK] Forecast cache"



        return dict(_cached_val)







    url = "https://api.openweathermap.org/data/2.5/forecast"



    params = {



        "lat": lat_f,



        "lon": lon_f,



        "appid": OPENWEATHER_API_KEY,



        "units": "imperial",



        "cnt": 40,



    }



    try:



        r = requests.get(url, params=params, timeout=8)



        r.raise_for_status()



        forecasts = r.json().get("list", [])



        if not forecasts:



            raise ValueError("Empty forecast list")







        best = min(forecasts, key=lambda f: abs(f["dt"] - game_dt_utc.timestamp()))



        forecast_dt_utc = datetime.fromtimestamp(best["dt"], tz=timezone.utc)



        forecast_dt_local = forecast_dt_utc.astimezone(venue_tz)



        delta_hrs = abs((forecast_dt_utc - game_dt_utc).total_seconds()) / 3600



        main = best.get("main", {})



        wind = best.get("wind", {})







        _t = main.get("temp")



        _h = main.get("humidity")



        _p = main.get("pressure")



        _ws = wind.get("speed") if wind else None



        _wd = wind.get("deg") if wind else None



        if _t is None or _h is None or _p is None:



            log("Forecast API returned incomplete data - analysis suppressed.", "warning")



            _weather_source_label = "[WARN] Incomplete forecast"



            return None



        result = {



            "temp": float(_t),



            "humidity": float(_h),



            "pressure": float(_p) * 0.02953,



            "wind_speed": float(_ws) if _ws is not None else None,



            "wind_dir": float(_wd) if _wd is not None else None,



        }



        _clear_openweather_auth_backoff()



        _wx_cache_put(_weather_forecast_cache, _fkey, result)



        _weather_source_label = (



            f"[OK] Forecast  {forecast_dt_local.strftime('%m/%d %I:%M %p %Z')}  "



            f"(+/-{delta_hrs:.0f}h of gametime)"



        )



        log(f"Gametime forecast fetched - {_weather_source_label}", "info")



        return result







    except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as e:



        _code = None



        try:



            _code = e.response.status_code if hasattr(e, "response") and e.response is not None else None



        except (TypeError, ValueError, AttributeError):



            _code = None



        if _code == 401:



            _weather_source_label = "[ERROR] 401 unauthorized"



            _mark_openweather_401("Forecast")



            return None



        log(f"Forecast API error: {e} - no weather fallback applied.", "warning")



        _weather_source_label = "[WARN] Forecast unavailable"



        return None











# =========================



# PHYSICS



# =========================



def air_density(temp_f, pressure_inhg, humidity):



    temp_c      = (temp_f - 32) * 5.0 / 9.0



    temp_k      = temp_c + 273.15



    pressure_pa = pressure_inhg * 3386.39



    es  = 6.1078 * 10 ** ((7.5 * temp_c) / (237.3 + temp_c))



    e   = (humidity / 100.0) * es * 100.0



    Rd, Rv = 287.05, 461.5



    rho = ((pressure_pa - e) / (Rd * temp_k)) + (e / (Rv * temp_k))



    return rho * 0.062428







def density_altitude(temp_f, elevation_ft, pressure_inhg=None, humidity=None):



    """



    Compute density altitude from actual air density when pressure/humidity exist.



    Falls back to a temperature-elevation approximation only when full weather



    inputs are unavailable.



    """



    elevation_ft = safe_float(elevation_ft, 0.0, "elevation_ft")



    temp_f = safe_float(temp_f, 59.0, "temp_f")



    p = safe_float(pressure_inhg, None, "pressure_inhg")



    h = safe_float(humidity, None, "humidity")



    if p is not None and h is not None:



        try:



            # Convert measured density to equivalent standard-atmosphere altitude.



            rho_meas = air_density(temp_f, p, h) / 0.0624279606  # lb/ft^3 -> kg/m^3



            if rho_meas > 0:



                T0 = 288.15



                L = 0.0065



                g = 9.80665



                M = 0.0289644



                R = 8.3144598



                rho0 = 1.225



                expn = 1.0 / ((g * M) / (R * L) - 1.0)



                ratio = max(1e-6, min(2.0, rho_meas / rho0))



                h_m = (T0 / L) * (1.0 - (ratio ** expn))



                return h_m * 3.280839895



        except (TypeError, ValueError, AttributeError) as _e:



            _warn_exception("silent_except", _e)

    standard_temp = 59.0 - 0.00356 * elevation_ft



    return elevation_ft + (120.0 * (temp_f - standard_temp))







def wind_components(speed, direction, orientation_deg):



    speed_val = safe_float(speed, None, "wind_speed")

    direction_val = safe_float(direction, None, "wind_dir")

    orientation_val = safe_float(orientation_deg, None, "orientation_deg")



    if speed_val is None or direction_val is None or orientation_val is None:

        return None, None



    # OWM direction is where wind comes FROM; convert to the travel vector.



    theta = math.radians((direction_val - orientation_val + 180.0) % 360.0)



    return round(speed_val * math.cos(theta), 2), round(speed_val * math.sin(theta), 2)







