# 4-TIER FUZZY TEAM MATCHER



# =========================



def _find_team_fuzzy(raw_name: str, preferred_league=None):



    if not raw_name or not raw_name.strip():



        return None, None



    _name = _strip_pitcher(raw_name.strip())



    primary = _safe_resolve_team_match(_name, df, preferred_league=preferred_league)



    if primary.get("team") and not primary.get("ambiguous"):



        if preferred_league and not _same_league_tag(primary.get("league", ""), preferred_league):



            return None, None



        return str(primary.get("team")), str(primary.get("league") or "")



    if preferred_league:



        # Never cross over to other leagues when a league is explicitly requested.



        # Missing should stay missing (and be surfaced) instead of silently mis-mapping.



        return None, None



    fallback = _safe_resolve_team_match(_name, df, preferred_league=None)



    if fallback.get("team") and not fallback.get("ambiguous"):



        return str(fallback.get("team")), str(fallback.get("league") or "")



    return None, None











def _detail_heavy_cache_key(sport, away_clean, home_clean, game_time):



    return (



        datetime.now().strftime("%Y%m%d"),



        str(sport or "").upper().strip(),



        str(away_clean or "").strip().lower(),



        str(home_clean or "").strip().lower(),



        str(game_time or "").strip(),



    )











def _detail_heavy_cache_get(cache_key):



    with _DETAIL_HEAVY_CACHE_LOCK:



        entry = _DETAIL_HEAVY_CACHE.get(cache_key)



        if not isinstance(entry, dict):



            return None



        return dict(entry)











def _detail_heavy_cache_put(cache_key, payload):



    if not isinstance(payload, dict):



        return



    with _DETAIL_HEAVY_CACHE_LOCK:



        _DETAIL_HEAVY_CACHE[cache_key] = dict(payload)



        if len(_DETAIL_HEAVY_CACHE) > _DETAIL_HEAVY_CACHE_MAX:



            _oldest = next(iter(_DETAIL_HEAVY_CACHE.keys()))



            if _oldest != cache_key:



                _DETAIL_HEAVY_CACHE.pop(_oldest, None)











def _build_heavy_detail_context(



    sport,



    game_time,



    game_date_str,



    away_clean,



    home_clean,



    away_row,



    home_row,



):



    _ctx = {}



    _sport_up = str(sport or "").upper().strip()







    if _sport_up == "MLB" and (_ENABLE_MLB_PREGAME_SECTION or _ENABLE_MLB_PREGAME_SCORING):



        try:



            _ctx["mlb_db"] = _mlb_db_lookup(home_clean, away_clean, game_date=game_date_str)



        except GUI_ERRORS as _e_mlb:



            log(f"[detail] mlb_db preload failed: {_e_mlb}", "warning")



            _ctx["mlb_db"] = None







    try:



        _ctx["inj_data"] = _inj_news_lookup(_sport_up, away_clean, home_clean)

        if isinstance(_ctx["inj_data"], dict):

            _probe = _contract_probe(

                _ctx["inj_data"],

                required_fields=["away_validity", "home_validity"],

                numeric_fields=[],

            )

            if list(_probe.get("missing", []) or []):

                log(f"[detail] injury/news contract missing: {_probe.get('missing')}", "warning")



    except DATA_ERRORS as _e_inj:



        log(f"[detail] injury/news preload failed: {_e_inj}", "warning")



        _ctx["inj_data"] = None







    _ctx["game_date"] = str(game_date_str or "").strip()



    if _ctx["game_date"]:



        try:



            _ctx["circ"] = _circ_analysis(



                game_time,



                home_row,



                away_row,



                _sport_up,



                away_team=away_clean,



                home_team=home_clean,



                game_date=_ctx["game_date"],



            )



        except DATA_ERRORS as _e_circ:



            log(f"[detail] circadian preload failed: {_e_circ}", "warning")



            _ctx["circ"] = {"available": False, "reason": f"circadian preload failed: {_e_circ}"}



    else:



        _ctx["circ"] = {"available": False, "reason": "Game date missing/unparseable in matchup record"}



        log("[DATA] Circadian preload blocked: game date missing/unparseable.", "warning")







    _ctx["rr"] = None



    _off_pol = _officials_policy_for_league(_sport_up)



    if not _off_pol.get("enabled", False):



        _ctx["rr"] = {



            "ou_signal": "NEUTRAL",



            "side_signal": "NEUTRAL",



            "confidence": 0.0,



            "detail": _off_pol.get("reason", "Officials excluded by policy."),



            "ref_names": [],



            "policy_excluded": True,



        }



    elif _REF_ENGINE_OK and _rse_mod:



        try:



            _ref_dt = _explicit_game_date_obj(_ctx.get("game_date"))



            if _ref_dt is not None:



                _ctx["rr"] = _rse_mod.get_ref_signal(_sport_up, away_clean, home_clean, _ref_dt)



                if not (_ctx["rr"] or {}).get("detail"):



                    _ctx["rr"]["detail"] = "Officials assignment missing; treated as neutral."



            elif str(_ctx.get("game_date") or "").strip():



                log(f"[detail] officials preload skipped: invalid game date '{_ctx.get('game_date')}'", "warning")



                _ctx["rr"] = {



                    "ou_signal": "NEUTRAL",



                    "side_signal": "NEUTRAL",



                    "confidence": 0.0,



                    "detail": "Officials lookup skipped: invalid game date.",



                    "ref_names": [],



                }



        except DATA_ERRORS as _e_ref:



            log(f"[detail] officials preload failed: {_e_ref}", "warning")



            _ctx["rr"] = {



                "ou_signal": "NEUTRAL",



                "side_signal": "NEUTRAL",



                "confidence": 0.0,



                "detail": f"Officials lookup failed: {_e_ref}",



                "ref_names": [],



            }







    _ctx["loaded_at"] = datetime.now().astimezone().isoformat()



