def _tk_exc_handler(exc_type, exc_val, exc_tb):



    import traceback as _tb



    msg = "".join(_tb.format_exception(exc_type, exc_val, exc_tb))



    log(f"TKINTER EXCEPTION:\n{msg}", "error")



