_UI_PREFS_FILE = Path(__file__).resolve().with_name("ui_prefs.json")







def _load_ui_prefs_data():



    if not _UI_PREFS_FILE.exists():



        return {}



    for _enc in ("utf-8", "utf-8-sig"):



        try:



            _raw = json.loads(_UI_PREFS_FILE.read_text(encoding=_enc))



            if isinstance(_raw, dict):



                return dict(_raw)



        except _sqlite3.Error:



            continue



    return {}







def _save_ui_prefs_data(payload: dict):



    try:



        _data = dict(payload or {})



        _UI_PREFS_FILE.write_text(



            json.dumps(_data, ensure_ascii=False, indent=2),



            encoding="utf-8",



        )



    except (OSError, ValueError, TypeError) as _pref_e:



        log(f"[ui] could not persist ui prefs: {_pref_e}", "warning")







def _load_visual_pref(default_name="Executive"):



    _raw = _load_ui_prefs_data()



    _name = str((_raw or {}).get("visual_profile", "")).strip()



    # Migrate away from the previous aggressive default.



    if _name == "Edge Noir":



        return "Executive"



    if _name in _VISUAL_PROFILES:



        return _name



    return default_name if default_name in _VISUAL_PROFILES else "Executive"







def _save_visual_pref(name):



    _raw = _load_ui_prefs_data()



    _raw["visual_profile"] = str(name)



    _save_ui_prefs_data(_raw)







