def _refresh_shell_clock():



    try:



        _shell_clock_var.set(datetime.now(ET).strftime("ET %a %b %d | %I:%M %p"))



    except GUI_ERRORS as _e:



        _warn_exception("silent_except", _e)

    root.after(30000, _refresh_shell_clock)







