def _update_odds_startup_warning_banner():

    today_token = datetime.now(ZoneInfo("America/New_York")).strftime("%Y%m%d")

    stale = []

    for _lg in ("MLB", "NBA", "NHL", "NFL", "NCAAF", "NCAAB"):

        try:

            _today_path = Path(str(_core_today_odds_file(Path(ODDS_DIR), _lg, today_token)))

            _latest = _core_latest_odds_file(Path(ODDS_DIR), _lg)

            if not _today_path.exists():

                _latest_name = Path(str(_latest)).name if _latest else "none"

                stale.append(f"{_lg} (latest={_latest_name})")

        except (TypeError, ValueError, AttributeError, OSError) as _odds_warn_err:

            stale.append(f"{_lg} (check_error={type(_odds_warn_err).__name__})")

    _alerts = []

    if stale:

        _alerts.append(

            f"CRITICAL: Missing today's odds file ({today_token}) for: {', '.join(stale[:4])}"

            + (" ..." if len(stale) > 4 else "")

        )

    _moji_count = _mojibake_token_count_in_file(Path(__file__).resolve())

    if _moji_count > 0:

        _alerts.append(f"WARNING: Source text encoding artifacts detected ({_moji_count} tokens).")

    _odds_warning_var.set(" | ".join(_alerts))







