try:



    import importlib.util as _ilu_rse



    _rse_path = os.path.join(ODDS_DIR, "referee_signal_engine.py")



    _rse_spec = _ilu_rse.spec_from_file_location("referee_signal_engine", _rse_path)



    _rse_mod  = _ilu_rse.module_from_spec(_rse_spec)



    _rse_spec.loader.exec_module(_rse_mod)



    _REF_ENGINE_OK = True



    log("Referee signal engine loaded.", "info")



except GUI_ERRORS as _rse_e:



    _rse_mod = None



    _REF_ENGINE_OK = False



    log(f"Referee signal engine unavailable: {_rse_e}", "warning")







try:



    from travel_rest_scraper import load_travel_rest_for_game as _load_travel_rest_for_game



    _TRAVEL_REST_OK = True



    log("Travel/rest scraper loaded.", "info")



except GUI_ERRORS as _tr_e:



    _load_travel_rest_for_game = None



    _TRAVEL_REST_OK = False



    log(f"Travel/rest scraper unavailable: {_tr_e}", "warning")


_missing_modules = []
if not BOYDSOK:           _missing_modules.append("boydsbeats_injury_scraper")
if not NEALINEUPOK:       _missing_modules.append("nea_lineup_assessor")
if not NEASTATSOK:        _missing_modules.append("nea_player_stats_scraper")
if not REFENGINEOK:       _missing_modules.append("referee_signal_engine")
if not TRAVELRESTOK:      _missing_modules.append("travel_rest_scraper")
if not STATSSOSAVAILABLE: _missing_modules.append("stats_sos_integration")
if not CREAVAILABLE:      _missing_modules.append("cre_integration")

if _missing_modules:
    _banner = tk.Label(
        root,
        text=f"?  MISSING MODULES ({len(_missing_modules)}): "
             + ", ".join(_missing_modules)
             + "  ?  Model at REDUCED CAPACITY. Affected sections show BLOCKED.",
        bg="#8f2d2d", fg="#ffffff",
        font=("Consolas", 9, "bold"),
        anchor="w", padx=10, pady=4, wraplength=900, justify="left",
    )
