# Auto-load cache on startup; auto-fetch if no usable cache found



def _try_autoload():



    if not ARSENAL_AVAILABLE:



        root.after(0, lambda: _ars_set_status(



            "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â  arsenal_engine.py not found ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â place it in the same folder as this script."))



        log("ARSENAL_AVAILABLE=False at startup ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â arsenal_engine.py missing or import error.", "error")



        return



    try:



        s, a = load_cached_arsenal(ODDS_DIR)



    except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as exc:



        log(f"load_cached_arsenal raised: {exc}", "error")



        s, a = None, None



    n_starters = len(s) if s is not None and not (hasattr(s,"empty") and s.empty) else 0



    n_ars      = len(a) if a is not None and not (hasattr(a,"empty") and a.empty) else 0



    log(f"Startup cache check: starters={n_starters}  arsenal_rows={n_ars}", "info")



    has_data = n_starters > 0 and n_ars > 0



    if has_data:



        root.after(0, lambda: _populate_arsenal_tree(s, a))



        log(f"Arsenal auto-loaded: {n_starters} starters, {n_ars} arsenal rows.", "info")



    else:



        if not PYBASEBALL_AVAILABLE:



            log("pybaseball not installed ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â arsenal auto-fetch skipped. "



                "Run: pip install pybaseball", "error")



            root.after(0, lambda: _ars_set_status(



                "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ pybaseball not installed ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â run: pip install pybaseball  then restart"))



        else:



            log(f"No usable cache (starters={n_starters}, arsenal={n_ars}) ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â auto-fetching...", "info")



            root.after(0, lambda: _ars_set_status(



                "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³ No cache found ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â auto-fetching today's arsenal..."))



            _fetch_arsenal_thread()



_start_daemon_after(100, _try_autoload)







# ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ Injury cache warm-up ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â runs at startup, all sports, background thread ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬



def _warm_injury_cache_all_sports():



    """



    Cache warm-up at startup. Three strict filters keep it fast:



      1. TODAY'S GAME TEAMS ONLY ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â reads odds XLSXs to get active teams.



         No fetching all 30 MLB teams when only 15 play tonight.



      2. INJURED PLAYERS ONLY ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â status must match a real injury designation.



         Eliminates the full-roster rows that bloated the XLSX to 1870.



      3. FLAT PARALLEL BATCH ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â all players fetched in one ThreadPoolExecutor



         per sport, not a sequential team-by-team loop.



    Net result: ~30-120 players total vs 2407 previously. Runtime < 60s.



    """



    if not _NEA_STATS_OK or not _nea_mod:



        log("Injury cache warm skipped ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â NEA stats scraper not loaded.", "warning")



        return



    from pathlib import Path as _P



    import time as _time



    from concurrent.futures import (



        ThreadPoolExecutor as _TPE,



        as_completed as _ac,



        TimeoutError as _FTimeout,



    )



    _today_ts  = datetime.now().strftime("%Y%m%d")



    _inj_dir   = _injury_news_output_dir()



    if not _inj_dir.exists(): return



    # Statuses that represent actual injuries/absences worth fetching



    _INJ_ST = {"out","60-day-il","60-day il","15-day-il","15-day il",



               "10-day-il","10-day il","day-to-day","day to day",



               "questionable","doubtful","injured reserve","ir"}



    # Map sport ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ odds XLSX name pattern to find today's active teams



    _SP_ODDS = {"MLB":"MLB","NBA":"NBA","NHL":"NHL","NFL":"NFL",



               "NCAAB":"NCAAB","NCAAF":"NCAAF"}



    _SPORTS = ["MLB","NBA","NHL","NFL","NCAAB","NCAAF"]



    _total_fetched = 0; _total_players = 0



    for _sp in _SPORTS:



        _xl = _inj_dir / f"INJURY_NEWS_{_sp}_{_today_ts}.xlsx"



        if not _xl.exists(): continue



        try:



            _sheets = {str(_s).strip().upper() for _s in (pd.ExcelFile(str(_xl)).sheet_names or [])}



        except GUI_ERRORS:



            _sheets = set()



        if "INJURIES" not in _sheets:



            log(f"Injury warm [{_sp}]: INJURIES sheet missing; waiting for rebuilt workbook.", "info")



            continue



        try:



            _df = pd.read_excel(str(_xl), sheet_name="INJURIES", dtype=str)



        except (OSError, json.JSONDecodeError, ValueError, TypeError) as _e:



            log(f"Injury warm [{_sp}]: XLSX read error - {_e}", "warning"); continue



        if _df.empty: continue



