def _rpt_set_status(msg, colour="#555555"):



    root.after(0, lambda: rpt_status_var.set(_clean_display_text(str(msg))))







def _rpt_write(txt_widget, text, tag="value"):



    """Thread-safe write to rpt_text."""



    def _do():



        txt_widget.config(state=tk.NORMAL)



        txt_widget.insert(tk.END, _clean_display_text(text), tag)



        txt_widget.config(state=tk.DISABLED)



        txt_widget.see(tk.END)



    root.after(0, _do)







def _rpt_clear():



    root.after(0, lambda: (rpt_text.config(state=tk.NORMAL),



                            rpt_text.delete("1.0", tk.END),



                            rpt_text.config(state=tk.DISABLED)))







def _rpt_debrief_refresh():



    path = SCRIPT_DIR / "diagnostics" / "todays_picks_missing_data_latest.txt"



    if not path.exists():



        msg = "No latest missing-data report found yet. Run Model Picks or load a slate to generate it."



    else:



        try:



            msg = path.read_text(encoding="utf-8", errors="replace")



        except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as exc:



            msg = f"Failed to read {path}: {exc}"



    try:



        _ovr = _context_load_param_overrides(force=True)



        _state = {}



        try:



            _sp = Path(_CONTEXT_CALIBRATION_STATE_FILE)



            if _sp.exists():



                _tmp = json.loads(_sp.read_text(encoding="utf-8"))



                if isinstance(_tmp, dict):



                    _state = _tmp



        except GUI_ERRORS:



            _state = {}



        _lines = []



        _lines.append("\n" + "=" * 100)



        _lines.append("CONTEXT CALIBRATION SNAPSHOT")



        _lines.append("=" * 100)



        _lines.append(f"State last run: {_state.get('last_run', 'n/a')}")



        _lines.append(f"State status: {_state.get('status', 'n/a')} | reason: {_state.get('reason', 'n/a')} | updated_sports: {_state.get('updated_sports', 'n/a')}")



        _lines.append("calibration_sample_size = number of graded model picks used for that league's latest calibration pass.")



        for _sport in sorted(_CONTEXT_BASELINE_TOTALS.keys()):



            _rec = dict((_ovr or {}).get(_sport) or {})



            _lines.append(



                f"{_sport}: step={_rec.get('step_multiplier', 'n/a')} "



                f"edge={_rec.get('edge_threshold', 'n/a')} "



                f"rho_off={_rec.get('weather_rho_off_divisor', 'n/a')} "



                f"rho_def={_rec.get('weather_rho_def_divisor', 'n/a')} "



                f"headwind={_rec.get('weather_headwind_divisor', 'n/a')} "



                f"circ_off={_rec.get('circadian_off_divisor', 'n/a')} "



                f"circ_def={_rec.get('circadian_def_divisor', 'n/a')} "



                f"calibration_sample_size={_rec.get('calibration_samples', 'n/a')} "



                f"wr={_rec.get('calibration_win_rate', 'n/a')} "



                f"mae={_rec.get('calibration_mae', 'n/a')}"



            )



        msg = _clean_display_text(msg) + "\n" + _clean_display_text("\n".join(_lines))



    except GUI_ERRORS:



        msg = _clean_display_text(msg)



    def _do():



        rpt_debrief_text.config(state=tk.NORMAL)



        rpt_debrief_text.delete("1.0", tk.END)



        rpt_debrief_text.insert(tk.END, msg)



        rpt_debrief_text.config(state=tk.DISABLED)



        rpt_debrief_text.see("1.0")



    root.after(0, _do)







