def _clamp(v, lo, hi):



    return max(lo, min(hi, v))











def _to_float_or_none(v):



    if v is None:



        return None



    try:



        if isinstance(v, str):



            s = v.strip()



            if not s or s.lower() in {"nan", "none", "null", "n/a", "na", "--", "->"}:



                return None



            v = s



        return float(v)



    except GUI_ERRORS:



        return None











def _parse_market_total(raw):



    if raw is None:



        return None



    if isinstance(raw, (int, float)):



        return float(raw)



    s = str(raw).strip()



    if not s:



        return None



    s = s.replace("o", "").replace("u", "").replace("O", "").replace("U", "")



    s = s.replace("(", " ").replace(")", " ").replace("/", " ")



    m = re.search(r"(-\d+(:\.\d+))", s)



    if not m:



        return None



    try:



        return float(m.group(1))



    except GUI_ERRORS:



        return None











def _parse_american_odds(raw):



    """Parse American odds from mixed text/int inputs; returns int or None."""



    if raw is None:



        return None



    if isinstance(raw, (int, float)):



        try:



            _iv = int(round(float(raw)))



            return _iv if abs(_iv) >= 100 else None



        except GUI_ERRORS:



            return None



    s = str(raw).strip()



    if not s:



        return None



    s_low = s.lower()



    if s_low in {"even", "ev", "evens", "pk", "pick", "pickem", "pick'em"}:



        return 100



    m = re.search(r"([+-]\d{2,4})", s.replace("−", "-"))



    if not m:



        return None



    try:



        _iv = int(m.group(1))



    except GUI_ERRORS:



        return None



    if abs(_iv) < 100:



        return None



    return _iv











def _implied_prob_from_american(odds):



    _od = _parse_american_odds(odds)



    if _od is None:



        return None



    if _od > 0:



        return 100.0 / (float(_od) + 100.0)



    _a = abs(float(_od))



    return _a / (_a + 100.0)











def _fair_american_from_prob(prob):



    p = _to_float_or_none(prob)



    if p is None:



        return None



    p = _clamp(float(p), 1e-6, 1.0 - 1e-6)



    if p >= 0.5:



        return int(round(-(100.0 * p / max(1e-6, 1.0 - p))))



    return int(round((100.0 * (1.0 - p)) / max(1e-6, p)))











def _expected_value_from_prob(prob, american_odds):



    """



    $EV per $1 risk using projected win probability and market American odds.



    Positive value indicates theoretical edge.



    """



    p = _to_float_or_none(prob)



    od = _parse_american_odds(american_odds)



    if p is None or od is None:



        return None



    p = _clamp(float(p), 0.0, 1.0)



    payout = (float(od) / 100.0) if od > 0 else (100.0 / abs(float(od)))



    return (p * payout) - ((1.0 - p) * 1.0)











def _context_load_param_overrides(force=False):



    """Load optional per-sport context projection overrides from disk."""



    try:



        p = Path(_CONTEXT_PARAMS_FILE)



    except GUI_ERRORS:



        return {}



    if not p.exists():



        return {}



    try:



        mt = p.stat().st_mtime



    except GUI_ERRORS:



        mt = None



    with _CONTEXT_PARAMS_LOCK:



        if (not force) and (_CONTEXT_PARAMS_CACHE.get("mtime") == mt):



            return dict(_CONTEXT_PARAMS_CACHE.get("data") or {})



        try:



            raw = json.loads(p.read_text(encoding="utf-8"))



            if not isinstance(raw, dict):



                raw = {}



        except GUI_ERRORS:



            raw = {}



        data = {}



        for k, v in raw.items():



            sk = str(k or "").upper().strip()



            if not sk or not isinstance(v, dict):



                continue



            data[sk] = dict(v)



        _CONTEXT_PARAMS_CACHE["mtime"] = mt



        _CONTEXT_PARAMS_CACHE["data"] = data



        return dict(data)











def _context_get_sport_params(sport):



    s = str(sport or "").upper().strip()



    ov = _context_load_param_overrides().get(s, {})



    return dict(ov if isinstance(ov, dict) else {})











def _context_recent_team_profile(sport, team_name, game_date_iso=None, max_games=6):



    """Recent per-team offense/defense profile from real final scores."""



    sport = str(sport or "").upper().strip()



    team_key = _canonical_team_key(team_name, league=sport)



    if (not sport) or (not team_key):



        return {"available": False, "games": 0}







    as_of = None



    try:



        if game_date_iso:



            as_of = datetime.strptime(str(game_date_iso), "%Y-%m-%d").date()



    except GUI_ERRORS:



        as_of = None







    rows = []



    try:



        con = _pk_connect(timeout=6)



        try:



            rows = con.execute(



                "SELECT game_date, away_canon, home_canon, away_score, home_score "



                "FROM score_events "



                "WHERE league= AND (away_canon= OR home_canon=) "



                "ORDER BY game_date DESC, id DESC LIMIT 36",



                (sport, team_key, team_key),



            ).fetchall()



        finally:



            con.close()



    except GUI_ERRORS:



        rows = []







    prof_rows = []



    for gd, a_can, h_can, a_sc, h_sc in rows:



        try:



            gdi = datetime.strptime(str(gd or ""), "%Y-%m-%d").date()



        except _sqlite3.Error:



            continue



        if as_of and gdi >= as_of:



            continue



        away_sc = _to_float_or_none(a_sc)



        home_sc = _to_float_or_none(h_sc)



        if (away_sc is None) or (home_sc is None):



            continue



        if str(a_can or "") == team_key:



            team_for, team_against = away_sc, home_sc



        elif str(h_can or "") == team_key:



            team_for, team_against = home_sc, away_sc



        else:



            continue



        prof_rows.append((gdi, float(team_for), float(team_against)))



        if len(prof_rows) >= max(1, int(max_games)):



            break







    if not prof_rows:



        return {"available": False, "games": 0}







    # Recency-weighted averages (half-life ~3 games; no hard directionality).



    weights = []



    for idx, _ in enumerate(prof_rows):



        weights.append(math.exp(-0.23 * idx))



    wsum = sum(weights) or 1.0



    off = sum(w * r[1] for w, r in zip(weights, prof_rows)) / wsum



    dff = sum(w * r[2] for w, r in zip(weights, prof_rows)) / wsum



    return {



        "available": True,



        "games": len(prof_rows),



        "offense_avg": float(off),



        "defense_avg": float(dff),



        "last_game_date": str(prof_rows[0][0]),



    }











def _context_league_total_std(sport, lookback_games=240):



    sport = str(sport or "").upper().strip()



    vals = []



    # Prefer rolling totals from audit log once we have enough local history.

    try:

        _rows = []

        _ap = Path(str(AUDIT_LOG_FILE or "")).expanduser()

        if _ap.exists():

            _raw = json.loads(_ap.read_text(encoding="utf-8"))

            if isinstance(_raw, list):

                _rows = list(_raw)

        for _r in reversed(_rows):

            if str((_r or {}).get("sport", "") or "").upper().strip() != sport:

                continue

            _v = _to_float_or_none((_r or {}).get("actual_total"))

            if _v is None:

                _v = _to_float_or_none((_r or {}).get("market_total"))

            if _v is None:

                _v = _to_float_or_none((_r or {}).get("total"))

            if _v is not None:

                vals.append(_v)

            if len(vals) >= int(max(30, lookback_games)):

                break

    except (OSError, ValueError, TypeError, json.JSONDecodeError):

        vals = []



    if len(vals) < 30:

        vals = []

        try:

            con = _pk_connect(timeout=6)

            try:

                vals = [

                    _to_float_or_none(r[0])

                    for r in con.execute(

                        "SELECT total FROM score_events WHERE league= "

                        "ORDER BY game_date DESC, id DESC LIMIT ",

                        (sport, int(max(20, lookback_games))),

                    ).fetchall()

                ]

            finally:

                con.close()

        except GUI_ERRORS:

            vals = []



    vals = [v for v in vals if v is not None]



    if len(vals) < 12:

        return None



    m = sum(vals) / float(len(vals))

    var = sum((v - m) ** 2 for v in vals) / float(max(1, len(vals) - 1))

    return math.sqrt(max(0.0, var))











def _context_dynamic_projection_params(sport, away_team, home_team, game_date_iso, stats_sos_signal):



    sport = str(sport or "").upper().strip()



    ovr = _context_get_sport_params(sport)



    fallback_base = float(_CONTEXT_BASELINE_TOTALS.get(sport, 10.0))



    fallback_step = float(_CONTEXT_TOTAL_STEP.get(sport, 1.0))



    fallback_edge = float(_CONTEXT_EDGE_THRESH.get(sport, 1.0))







    ss = dict(stats_sos_signal or {})



    stats_exp = _to_float_or_none(ss.get("expected_total"))



    stats_cov = _clamp(_to_float_or_none(ss.get("coverage")) or 0.0, 0.0, 1.0)







    recent_games = int(_clamp(_to_float_or_none(ovr.get("recent_games_window")) or 6, 2, 8))



    away_prof = _context_recent_team_profile(sport, away_team, game_date_iso, max_games=recent_games)



    home_prof = _context_recent_team_profile(sport, home_team, game_date_iso, max_games=recent_games)







    team_expected = None



    team_cov = 0.0



    if away_prof.get("available") and home_prof.get("available"):



        try:



            team_expected = (



                ((away_prof["offense_avg"] + home_prof["defense_avg"]) / 2.0) +



                ((home_prof["offense_avg"] + away_prof["defense_avg"]) / 2.0)



            )



            team_cov = _clamp(



                ((away_prof.get("games", 0) + home_prof.get("games", 0)) / 12.0),



                0.0,



                1.0,



            )



        except GUI_ERRORS:



            team_expected = None



            team_cov = 0.0







    base_total = fallback_base



    baseline_source = "fallback"



    if stats_exp is not None and team_expected is not None:



        # Prefer team-specific recent form when both are present, but keep SOS anchoring.



        w_stats = _clamp(0.35 + (0.45 * stats_cov), 0.25, 0.80)



        w_team = _clamp(0.25 + (0.55 * team_cov), 0.20, 0.85)



        denom = max(1e-6, w_stats + w_team)



        base_total = ((w_stats * stats_exp) + (w_team * team_expected)) / denom



        baseline_source = "blend(team_form,stats_sos)"



    elif team_expected is not None:



        base_total = float(team_expected)



        baseline_source = "team_form"



    elif stats_exp is not None:



        base_total = float(stats_exp)



        baseline_source = "stats_sos"







    league_std = _context_league_total_std(sport)



    std_ref = {



        "MLB": 2.20,



        "NBA": 24.0,



        "NHL": 1.60,



        "NFL": 13.0,



        "NCAAB": 18.0,



        "NCAAF": 16.0,



    }.get(sport, 8.0)



    std_scale = _clamp((league_std / std_ref), 0.70, 1.35) if league_std else 1.0







    step_mult = _clamp(_to_float_or_none(ovr.get("step_multiplier")) or 1.0, 0.55, 1.75)



    edge_mult = _clamp(_to_float_or_none(ovr.get("edge_multiplier")) or 1.0, 0.55, 1.85)



    baseline_bias = _to_float_or_none(ovr.get("baseline_bias")) or 0.0



    tuned_edge = _to_float_or_none(ovr.get("edge_threshold"))







    total_step = fallback_step * std_scale * step_mult



    edge_thr = (tuned_edge if tuned_edge is not None else (fallback_edge * std_scale * edge_mult))



    edge_thr *= (1.08 if stats_cov < 0.45 else 1.0)



    base_total = float(base_total) + baseline_bias







    return {



        "baseline_total": float(base_total),



        "total_step": float(max(0.05, total_step)),



        "edge_threshold": float(max(0.05, edge_thr)),



        "meta": {



            "source": baseline_source,



            "stats_expected_total": stats_exp,



            "stats_coverage": round(stats_cov, 3),



            "team_expected_total": round(team_expected, 3) if team_expected is not None else None,



            "team_form_coverage": round(team_cov, 3),



            "away_form_games": int(away_prof.get("games", 0)),



            "home_form_games": int(home_prof.get("games", 0)),



            "league_total_std": round(float(league_std), 3) if league_std else None,



            "std_scale": round(float(std_scale), 3),



            "step_multiplier": round(float(step_mult), 3),



            "edge_multiplier": round(float(edge_mult), 3),



            "baseline_bias": round(float(baseline_bias), 3),



            "recent_games_window": int(recent_games),



        },



    }











def _recalibrate_context_projection_params(min_samples_per_sport=12):



    """



    Calibrate context projection parameters from graded model picks.



    Writes merged per-sport overrides to context_projection_params.json.



    """



    out = {



        "status": "NO_DATA",



        "updated_sports": 0,



        "sports": {},



        "params_file": str(_CONTEXT_PARAMS_FILE),



    }



    try:



        con = _pk_connect(timeout=8)



        try:



            try:



                rows = con.execute(



                    """



                    SELECT league, projected_total, baseline_total, ou_line, actual_total,



                           edge_vs_market, pick_result, projection_meta_json



                    FROM model_picks



                    WHERE projected_total IS NOT NULL



                      AND actual_total IS NOT NULL



                      AND UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')



                    ORDER BY id DESC



                    LIMIT 8000



                    """



                ).fetchall()



                has_meta = True



            except GUI_ERRORS:



                rows = con.execute(



                    """



                    SELECT league, projected_total, baseline_total, ou_line, actual_total,



                           edge_vs_market, pick_result



                    FROM model_picks



                    WHERE projected_total IS NOT NULL



                      AND actual_total IS NOT NULL



                      AND UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')



                    ORDER BY id DESC



                    LIMIT 8000



                    """



                ).fetchall()



                has_meta = False



        finally:



            con.close()



    except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as exc:



        out["status"] = f"DB_READ_FAILED:{exc}"



        return out







    if not rows:



        out["status"] = "NO_GRADED_MODEL_PICKS"



        return out







    by_sport = {}



    for row in rows:



        if has_meta:



            (lg, proj, base, line, actual, edge_mkt, result, meta_json) = row



        else:



            (lg, proj, base, line, actual, edge_mkt, result) = row



            meta_json = ""



        sport = str(lg or "").upper().strip()



        if not sport:



            continue



        meta = {}



        if meta_json:



            try:



                _tmp = json.loads(meta_json)



                if isinstance(_tmp, dict):



                    meta = _tmp



            except GUI_ERRORS:



                meta = {}



        coeffs = dict(meta.get("coefficients") or {})



        comps = dict(meta.get("component_effects") or {})



        fam = dict(meta.get("family_impacts") or {})



        rec = {



            "proj": _to_float_or_none(proj),



            "base": _to_float_or_none(base),



            "line": _to_float_or_none(line),



            "actual": _to_float_or_none(actual),



            "edge": _to_float_or_none(edge_mkt),



            "result": str(result or "").upper().strip(),



            "weather_rho_off_effect": _to_float_or_none(comps.get("weather_rho_off_effect")),



            "weather_rho_def_effect": _to_float_or_none(comps.get("weather_rho_def_effect")),



            "weather_headwind_effect": _to_float_or_none(comps.get("weather_headwind_effect")),



            "circadian_effect": _to_float_or_none(comps.get("circadian_effect")),



            "injuries_effect": _to_float_or_none(fam.get("injuries")),



            "coeff_weather_rho_off_divisor": _to_float_or_none(coeffs.get("weather_rho_off_divisor")),



            "coeff_weather_rho_def_divisor": _to_float_or_none(coeffs.get("weather_rho_def_divisor")),



            "coeff_weather_headwind_divisor": _to_float_or_none(coeffs.get("weather_headwind_divisor")),



            "coeff_circadian_off_divisor": _to_float_or_none(coeffs.get("circadian_off_divisor")),



            "coeff_circadian_def_divisor": _to_float_or_none(coeffs.get("circadian_def_divisor")),



        }



        if rec["proj"] is None or rec["actual"] is None:



            continue



        by_sport.setdefault(sport, []).append(rec)







    if not by_sport:



        out["status"] = "NO_VALID_ROWS"



        return out







    raw_current = _context_load_param_overrides(force=True)



    merged = dict(raw_current)







    def _quantile(vals, q):



        vv = sorted(float(v) for v in vals if v is not None)



        if not vv:



            return None



        if len(vv) == 1:



            return vv[0]



        q = _clamp(float(q), 0.0, 1.0)



        pos = q * (len(vv) - 1)



        lo = int(math.floor(pos))



        hi = int(math.ceil(pos))



        if lo == hi:



            return vv[lo]



        frac = pos - lo



        return vv[lo] * (1.0 - frac) + vv[hi] * frac







    def _fit_effect_multiplier(effect_vals, residual_vals, min_n=18, min_abs_effect=0.03):



        pairs = []



        for e, r in zip(effect_vals, residual_vals):



            ev = _to_float_or_none(e)



            rv = _to_float_or_none(r)



            if ev is None or rv is None:



                continue



            if abs(ev) < min_abs_effect:



                continue



            pairs.append((float(ev), float(rv)))



        if len(pairs) < max(8, int(min_n)):



            return {"ok": False, "n": len(pairs)}







        xs = [p[0] for p in pairs]



        ys = [p[1] for p in pairs]



        x_mean = sum(xs) / len(xs)



        y_mean = sum(ys) / len(ys)



        var_x = sum((x - x_mean) ** 2 for x in xs) / max(1, len(xs) - 1)



        var_y = sum((y - y_mean) ** 2 for y in ys) / max(1, len(ys) - 1)



        if var_x <= 1e-10:



            return {"ok": False, "n": len(pairs)}



        cov_xy = sum((x - x_mean) * (y - y_mean) for x, y in pairs) / max(1, len(pairs) - 1)



        slope_raw = cov_xy / var_x



        corr = 0.0



        if var_y > 1e-10:



            corr = cov_xy / math.sqrt(max(1e-12, var_x * var_y))



        # Shrink by correlation strength to avoid overfitting on noisy segments.



        slope = slope_raw * abs(corr)



        mult = _clamp(1.0 + slope, 0.40, 2.20)



        return {



            "ok": True,



            "n": len(pairs),



            "slope_raw": float(slope_raw),



            "slope": float(slope),



            "corr": float(corr),



            "multiplier": float(mult),



        }







    updates = 0



    for sport, srows in by_sport.items():



        if sport not in _CONTEXT_BASELINE_TOTALS:



            continue



        if len(srows) < max(8, int(min_samples_per_sport)):



            out["sports"][sport] = {



                "status": "INSUFFICIENT_SAMPLES",



                "samples": len(srows),



            }



            continue







        proj_vals = [r["proj"] for r in srows if r["proj"] is not None]



        act_vals = [r["actual"] for r in srows if r["actual"] is not None]



        if len(proj_vals) < max(8, int(min_samples_per_sport)) or len(act_vals) < max(8, int(min_samples_per_sport)):



            out["sports"][sport] = {



                "status": "INSUFFICIENT_VALID_VALUES",



                "samples": len(srows),



            }



            continue







        residuals = [r["actual"] - r["proj"] for r in srows]



        mae = sum(abs(x) for x in residuals) / max(1, len(residuals))



        bias = sum(residuals) / max(1, len(residuals))







        # Estimate context amplitude slope around baseline.



        xs = []



        ys = []



        for r in srows:



            b = r["base"]



            if b is None:



                b = _CONTEXT_BASELINE_TOTALS.get(sport, r["proj"])



            if b is None:



                continue



            xs.append(r["proj"] - b)



            ys.append(r["actual"] - b)



        slope = 1.0



        if len(xs) >= 8:



            x_mean = sum(xs) / len(xs)



            y_mean = sum(ys) / len(ys)



            var_x = sum((x - x_mean) ** 2 for x in xs) / max(1, len(xs) - 1)



            if var_x > 1e-8:



                cov_xy = sum((x - x_mean) * (y - y_mean) for x, y in zip(xs, ys)) / max(1, len(xs) - 1)



                slope = cov_xy / var_x



        slope = _clamp(slope, 0.55, 1.75)







        # Learn practical edge threshold from observed win rates at stronger edges.



        non_push = [r for r in srows if r["result"] in {"WIN", "LOSS"}]



        win_rate = (



            sum(1 for r in non_push if r["result"] == "WIN") / float(len(non_push))



            if non_push else 0.0



        )



        edge_abs = []



        for r in srows:



            if r["edge"] is not None:



                edge_abs.append(abs(r["edge"]))



            elif r["line"] is not None:



                edge_abs.append(abs(r["proj"] - r["line"]))



        tuned_edge = None



        if edge_abs:



            candidates = []



            for q in (0.35, 0.45, 0.55, 0.65, 0.75):



                val = _quantile(edge_abs, q)



                if val is not None:



                    candidates.append(float(val))



            candidates = sorted(set(round(v, 4) for v in candidates if v is not None))



            target_wr = 0.54



            min_bin = 12



            best = None



            for c in candidates:



                subset = []



                for r in non_push:



                    ev = r["edge"] if r["edge"] is not None else ((r["proj"] - r["line"]) if r["line"] is not None else None)



                    if ev is None:



                        continue



                    if abs(ev) >= c:



                        subset.append(r)



                if len(subset) < min_bin:



                    continue



                wr = sum(1 for r in subset if r["result"] == "WIN") / float(len(subset))



                if wr >= target_wr:



                    best = c



                    break



            if best is None:



                best = _quantile(edge_abs, 0.55) or _quantile(edge_abs, 0.50) or _CONTEXT_EDGE_THRESH.get(sport, 1.0)



            tuned_edge = float(best)







        sport_cur = dict(merged.get(sport) or {})



        old_step = _to_float_or_none(sport_cur.get("step_multiplier"))



        old_bias = _to_float_or_none(sport_cur.get("baseline_bias"))



        old_edge = _to_float_or_none(sport_cur.get("edge_threshold"))



        alpha = 0.35







        step_mult_new = slope if old_step is None else ((1.0 - alpha) * old_step + alpha * slope)



        step_mult_new = _clamp(step_mult_new, 0.55, 1.75)







        bias_cap = {



            "MLB": 1.20,



            "NBA": 14.0,



            "NHL": 1.10,



            "NFL": 7.50,



            "NCAAB": 9.0,



            "NCAAF": 9.0,



        }.get(sport, 4.0)



        bias_target = _clamp(bias * 0.30, -bias_cap, bias_cap)



        bias_new = bias_target if old_bias is None else ((1.0 - alpha) * old_bias + alpha * bias_target)



        bias_new = _clamp(bias_new, -bias_cap, bias_cap)







        if tuned_edge is None:



            tuned_edge = float(_CONTEXT_EDGE_THRESH.get(sport, 1.0))



        edge_new = tuned_edge if old_edge is None else ((1.0 - alpha) * old_edge + alpha * tuned_edge)



        edge_new = _clamp(edge_new, 0.05, 80.0)







        sport_cur["step_multiplier"] = round(float(step_mult_new), 4)



        sport_cur["baseline_bias"] = round(float(bias_new), 4)



        sport_cur["edge_threshold"] = round(float(edge_new), 4)







        # Calibrate weather/circadian coefficient divisors from effect residuals.



        weather_defaults = {



            "weather_rho_off_divisor": 4.0,



            "weather_rho_def_divisor": 4.6,



            "weather_headwind_divisor": 5.0,



            "circadian_off_divisor": 6.0,



            "circadian_def_divisor": 7.0,



        }



        # Seed from observed row-level coefficients if available.



        for k in list(weather_defaults.keys()):



            _obs = [r.get(f"coeff_{k}") for r in srows if _to_float_or_none(r.get(f"coeff_{k}")) is not None]



            if _obs:



                weather_defaults[k] = float(_quantile(_obs, 0.50) or weather_defaults[k])







        calib_details = {}



        coeff_fit = {



            "weather_rho_off_divisor": _fit_effect_multiplier(



                [r.get("weather_rho_off_effect") for r in srows], residuals, min_n=16, min_abs_effect=0.02



            ),



            "weather_rho_def_divisor": _fit_effect_multiplier(



                [r.get("weather_rho_def_effect") for r in srows], residuals, min_n=16, min_abs_effect=0.02



            ),



            "weather_headwind_divisor": _fit_effect_multiplier(



                [r.get("weather_headwind_effect") for r in srows], residuals, min_n=16, min_abs_effect=0.02



            ),



            "circadian_scale": _fit_effect_multiplier(



                [r.get("circadian_effect") for r in srows], residuals, min_n=20, min_abs_effect=0.02



            ),



            "injuries_scale": _fit_effect_multiplier(



                [r.get("injuries_effect") for r in srows], residuals, min_n=20, min_abs_effect=0.03



            ),



        }







        div_alpha = 0.28



        for key in ("weather_rho_off_divisor", "weather_rho_def_divisor", "weather_headwind_divisor"):



            fit = coeff_fit.get(key) or {}



            old_val = _to_float_or_none(sport_cur.get(key))



            if old_val is None:



                old_val = _to_float_or_none(weather_defaults.get(key))



            if old_val is None:



                old_val = 4.0



            old_val = max(0.25, float(old_val))



            if fit.get("ok"):



                mult = float(fit.get("multiplier", 1.0))



                target = old_val / max(0.10, mult)



                new_val = ((1.0 - div_alpha) * old_val) + (div_alpha * target)



                new_val = _clamp(new_val, 0.35, 24.0)



                sport_cur[key] = round(float(new_val), 4)



                calib_details[key] = {



                    "status": "UPDATED",



                    "old": round(old_val, 4),



                    "new": round(float(new_val), 4),



                    "fit_n": int(fit.get("n", 0) or 0),



                    "fit_corr": round(float(fit.get("corr", 0.0) or 0.0), 4),



                    "fit_slope": round(float(fit.get("slope", 0.0) or 0.0), 4),



                    "fit_multiplier": round(float(mult), 4),



                }



            else:



                sport_cur.setdefault(key, round(float(old_val), 4))



                calib_details[key] = {



                    "status": "UNCHANGED",



                    "reason": "insufficient_effect_samples",



                    "fit_n": int(fit.get("n", 0) or 0),



                }







        # Circadian divisors share a single fitted multiplier.



        circ_fit = coeff_fit.get("circadian_scale") or {}



        if circ_fit.get("ok"):



            circ_mult = float(circ_fit.get("multiplier", 1.0))



            for key in ("circadian_off_divisor", "circadian_def_divisor"):



                old_val = _to_float_or_none(sport_cur.get(key))



                if old_val is None:



                    old_val = _to_float_or_none(weather_defaults.get(key)) or (6.0 if "off" in key else 7.0)



                old_val = max(0.25, float(old_val))



                target = old_val / max(0.10, circ_mult)



                new_val = ((1.0 - div_alpha) * old_val) + (div_alpha * target)



                new_val = _clamp(new_val, 0.35, 30.0)



                sport_cur[key] = round(float(new_val), 4)



                calib_details[key] = {



                    "status": "UPDATED",



                    "old": round(old_val, 4),



                    "new": round(float(new_val), 4),



                    "fit_n": int(circ_fit.get("n", 0) or 0),



                    "fit_corr": round(float(circ_fit.get("corr", 0.0) or 0.0), 4),



                    "fit_slope": round(float(circ_fit.get("slope", 0.0) or 0.0), 4),



                    "fit_multiplier": round(float(circ_mult), 4),



                }



        else:



            calib_details["circadian_divisors"] = {



                "status": "UNCHANGED",



                "reason": "insufficient_effect_samples",



                "fit_n": int(circ_fit.get("n", 0) or 0),



            }







        # Injury scale tuning (denominator parameter, inverse response).



        inj_fit = coeff_fit.get("injuries_scale") or {}



        old_inj_scale = _to_float_or_none(sport_cur.get("injury_scale"))



        if old_inj_scale is None:



            old_inj_scale = float(_SPORT_INJURY_SCALE.get(sport, 1.0))



        old_inj_scale = max(0.05, float(old_inj_scale))



        if inj_fit.get("ok"):



            inj_mult = float(inj_fit.get("multiplier", 1.0))



            inj_target = old_inj_scale / max(0.10, inj_mult)



            inj_new = ((1.0 - div_alpha) * old_inj_scale) + (div_alpha * inj_target)



            inj_new = _clamp(inj_new, 0.05, 50.0)



            sport_cur["injury_scale"] = round(float(inj_new), 4)



            calib_details["injury_scale"] = {



                "status": "UPDATED",



                "old": round(old_inj_scale, 4),



                "new": round(float(inj_new), 4),



                "fit_n": int(inj_fit.get("n", 0) or 0),



                "fit_corr": round(float(inj_fit.get("corr", 0.0) or 0.0), 4),



                "fit_slope": round(float(inj_fit.get("slope", 0.0) or 0.0), 4),



                "fit_multiplier": round(float(inj_mult), 4),



            }



        else:



            sport_cur.setdefault("injury_scale", round(float(old_inj_scale), 4))



            calib_details["injury_scale"] = {



                "status": "UNCHANGED",



                "reason": "insufficient_effect_samples",



                "fit_n": int(inj_fit.get("n", 0) or 0),



            }







        sport_cur["calibration_samples"] = int(len(srows))



        sport_cur["calibration_win_rate"] = round(float(win_rate), 4)



        sport_cur["calibration_mae"] = round(float(mae), 4)



        sport_cur["calibration_weather_mae"] = round(



            float(sum(abs(r.get("weather_rho_off_effect") or 0.0) + abs(r.get("weather_headwind_effect") or 0.0) for r in srows) / max(1, len(srows))),



            4,



        )



        sport_cur["calibration_last_run"] = datetime.now().astimezone().isoformat()



        merged[sport] = sport_cur



        updates += 1







        out["sports"][sport] = {



            "status": "UPDATED",



            "samples": len(srows),



            "win_rate": round(float(win_rate), 4),



            "mae": round(float(mae), 4),



            "step_multiplier": sport_cur["step_multiplier"],



            "baseline_bias": sport_cur["baseline_bias"],



            "edge_threshold": sport_cur["edge_threshold"],



            "coefficient_calibration": calib_details,



        }







    if updates <= 0:



        out["status"] = "NO_SPORT_UPDATED"



        return out







    p = Path(_CONTEXT_PARAMS_FILE)



    p.parent.mkdir(parents=True, exist_ok=True)



    tmp = p.with_suffix(".json.tmp")



    with _CONTEXT_PARAMS_FILE_LOCK:



        with open(tmp, "w", encoding="utf-8") as f:



            json.dump(merged, f, indent=2, sort_keys=True)



        os.replace(str(tmp), str(p))



    out["status"] = "UPDATED"



    out["updated_sports"] = int(updates)



    try:



        _context_load_param_overrides(force=True)



    except GUI_ERRORS as _e:



        _warn_exception("silent_except", _e)

    return out











def _context_calibration_runner(reason="manual", force=False, min_interval_minutes=240):



    """



    Thread-safe calibration entrypoint so coefficients can refresh on schedule,



    not only when grading activity happens to run.



    """



    now = datetime.now().astimezone()



    state = {}



    try:



        if _CONTEXT_CALIBRATION_STATE_FILE.exists():



            _tmp = json.loads(_CONTEXT_CALIBRATION_STATE_FILE.read_text(encoding="utf-8"))



            if isinstance(_tmp, dict):



                state = _tmp



    except GUI_ERRORS:



        state = {}







    if not force:



        try:



            last_iso = str(state.get("last_run") or "").strip()



            if last_iso:



                last_dt = datetime.fromisoformat(last_iso)



                age_min = (now - last_dt).total_seconds() / 60.0



                if age_min < max(5.0, float(min_interval_minutes)):



                    return {



                        "status": "SKIPPED_FRESH",



                        "reason": reason,



                        "age_minutes": round(float(age_min), 2),



                        "last_run": last_iso,



                    }



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

    if not _CONTEXT_CALIBRATION_LOCK.acquire(blocking=False):



        return {"status": "SKIPPED_BUSY", "reason": reason}



    try:



        out = _recalibrate_context_projection_params()



        status = str((out or {}).get("status", "") or "").strip() if isinstance(out, dict) else "UNKNOWN"



        _sports_summary = {}

        try:

            _sports_raw = (out or {}).get("sports", {}) if isinstance(out, dict) else {}

            if isinstance(_sports_raw, dict):

                for _sport_key, _sport_val in _sports_raw.items():

                    if isinstance(_sport_val, dict):

                        _sports_summary[str(_sport_key)] = {

                            "status": str(_sport_val.get("status", "UNKNOWN") or "UNKNOWN"),

                            "samples": int(_sport_val.get("samples", 0) or 0),

                        }

        except (OSError, ValueError, TypeError):

            _sports_summary = {}

        payload = {



            "last_run": now.isoformat(),



            "reason": str(reason or "").strip() or "manual",



            "status": status,



            "updated_sports": int((out or {}).get("updated_sports", 0) or 0) if isinstance(out, dict) else 0,

            "sports_summary": _sports_summary,



        }



        try:



            _CONTEXT_CALIBRATION_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)



            _tmp_state = _CONTEXT_CALIBRATION_STATE_FILE.with_suffix(".json.tmp")



            with open(_tmp_state, "w", encoding="utf-8") as f:



                json.dump(payload, f, indent=2, sort_keys=True)



            os.replace(str(_tmp_state), str(_CONTEXT_CALIBRATION_STATE_FILE))



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

        if isinstance(out, dict):



            out["runner_reason"] = str(reason or "").strip() or "manual"



            out["runner_state_file"] = str(_CONTEXT_CALIBRATION_STATE_FILE)



        return out



    finally:



        _CONTEXT_CALIBRATION_LOCK.release()











def _normalize_feature_weights(feature_map, sport=None, family_kind="context"):



    mags = {}



    for name, pair in (feature_map or {}).items():



        away_v = _to_float_or_none(pair[0]) if isinstance(pair, (list, tuple)) and len(pair) >= 1 else None



        home_v = _to_float_or_none(pair[1]) if isinstance(pair, (list, tuple)) and len(pair) >= 2 else None



        mag = abs(away_v or 0.0) + abs(home_v or 0.0)



        if mag > 1e-9:



            mags[name] = mag



    total = sum(mags.values())



    if total <= 0:



        return {k: 0.0 for k in feature_map.keys()}



    raw = {k: (mags.get(k, 0.0) / total) for k in feature_map.keys()}



    vals = sorted(v for v in raw.values() if v > 0)



    if not vals:



        return {k: 0.0 for k in feature_map.keys()}







    # Soft anomaly dampening instead of a hard cap.



    med = vals[len(vals) // 2]



    abs_dev = sorted(abs(v - med) for v in vals)



    mad = abs_dev[len(abs_dev) // 2] if abs_dev else 0.0



    scale = max(1e-6, 1.4826 * mad)



    z_soft = 3.25



    try:



        ovr = _context_get_sport_params(sport or "")



        z_soft = _clamp(_to_float_or_none(ovr.get("weight_z_soft_cap")) or z_soft, 1.8, 8.0)



    except GUI_ERRORS as _e:



        _warn_exception("silent_except", _e)

    adjusted = {}



    for k, v in raw.items():



        z = (v - med) / scale



        if z > z_soft:



            damp = z_soft / max(z, 1e-6)



            adjusted[k] = v * damp



        else:



            adjusted[k] = v



    s = sum(adjusted.values()) or 1.0



    return {k: (adjusted.get(k, 0.0) / s) for k in feature_map.keys()}











_SPORT_INJURY_SCALE = {



    "MLB": 0.30,



    "NBA": 6.00,



    "NHL": 0.35,



    "NFL": 5.00,



    "NCAAB": 5.00,



    "NCAAF": 4.00,



}



_SPORT_CONTEXT_CAP = {



    "MLB": 0.85,



    "NBA": 1.35,



    "NHL": 0.75,



    "NFL": 1.05,



    "NCAAB": 1.10,



    "NCAAF": 1.10,



}



_SPORT_MIN_CONTEXT_QUALITY = {



    "MLB": 0.70,



    "NBA": 0.55,



    "NHL": 0.55,



    "NFL": 0.55,



    "NCAAB": 0.50,



    "NCAAF": 0.50,



}



_SPORT_MIN_STATS_SOS_COVERAGE = {



    "MLB": 0.20,



    "NBA": 0.25,



    "NHL": 0.25,



    "NFL": 0.25,



    "NCAAB": 0.20,



    "NCAAF": 0.20,



}











def _build_sport_specific_context(



    sport,



    rho_pct_home=None,



    rho_pct_away=None,



    headwind=None,



    away_env_score=0.0,



    home_env_score=0.0,



    away_env_exec=0.0,



    home_env_exec=0.0,



    away_inj_off=0.0,



    away_inj_def=0.0,



    home_inj_off=0.0,



    home_inj_def=0.0,



    away_lineup_power=0.0,



    home_lineup_power=0.0,



    lineup_signal_weight=0.0,



    ref_result=None,



    circ_result=None,



    stats_sos_signal=None,



):



    sport = str(sport or "").upper().strip()



    ref_result = ref_result or {}



    circ_result = circ_result or {}



    stats_sos_signal = stats_sos_signal or {}







    _ovr = _context_get_sport_params(sport)



    inj_scale = _to_float_or_none(_ovr.get("injury_scale"))



    if inj_scale is None:



        inj_scale = float(_SPORT_INJURY_SCALE.get(sport, 1.0))



    inj_scale = max(0.05, float(inj_scale))



    ctx_cap = _to_float_or_none(_ovr.get("context_cap"))



    if ctx_cap is None:



        ctx_cap = float(_SPORT_CONTEXT_CAP.get(sport, 1.0))



    ctx_cap = _clamp(float(ctx_cap), 0.25, 5.0)



    def _ctx_coeff(_key, _default, _lo=-10.0, _hi=10.0):



        _v = _to_float_or_none(_ovr.get(_key))



        if _v is None:



            _v = _default



        return _clamp(float(_v), float(_lo), float(_hi))







    away_env_score = _to_float_or_none(away_env_score) or 0.0



    home_env_score = _to_float_or_none(home_env_score) or 0.0



    away_env_exec = _to_float_or_none(away_env_exec) or 0.0



    home_env_exec = _to_float_or_none(home_env_exec) or 0.0



    away_inj_off = _to_float_or_none(away_inj_off) or 0.0



    away_inj_def = _to_float_or_none(away_inj_def) or 0.0



    home_inj_off = _to_float_or_none(home_inj_off) or 0.0



    home_inj_def = _to_float_or_none(home_inj_def) or 0.0



    away_lineup_power = _to_float_or_none(away_lineup_power) or 0.0



    home_lineup_power = _to_float_or_none(home_lineup_power) or 0.0



    lineup_signal_weight = _clamp(_to_float_or_none(lineup_signal_weight) or 0.0, 0.0, 1.0)



    away_risk = _to_float_or_none(circ_result.get("away_score")) or 0.0



    home_risk = _to_float_or_none(circ_result.get("home_score")) or 0.0



    stats_score = _to_float_or_none(stats_sos_signal.get("score")) or 0.0



    stats_cov = _clamp(_to_float_or_none(stats_sos_signal.get("coverage")) or 0.0, 0.0, 1.0)



    rho_pct_home = _to_float_or_none(rho_pct_home) or 0.0



    rho_pct_away = _to_float_or_none(rho_pct_away) or 0.0



    headwind = _to_float_or_none(headwind) or 0.0







    lineup_balance = (away_lineup_power - home_lineup_power) / (abs(away_lineup_power) + abs(home_lineup_power) + 1e-6)



    lineup_balance *= (0.55 + 0.45 * lineup_signal_weight)



    off_loss_gap = (away_inj_off - home_inj_off) / max(inj_scale, 1e-6)



    def_loss_gap = (away_inj_def - home_inj_def) / max(inj_scale, 1e-6)



    _env_load_div = _ctx_coeff("env_load_divisor", 3.5, 0.10, 50.0)



    _env_exec_div = _ctx_coeff("env_exec_divisor", 0.55, 0.05, 20.0)



    _circ_gap_div = _ctx_coeff(



        "sport_context_circadian_divisor",



        (_to_float_or_none(_ovr.get("circadian_divisor")) or 5.0),



        0.25,



        30.0,



    )



    _weather_rho_div = _ctx_coeff(



        "sport_context_weather_rho_divisor",



        (_to_float_or_none(_ovr.get("weather_rho_off_divisor")) or 3.5),



        0.25,



        40.0,



    )



    _weather_headwind_div = _ctx_coeff(



        "sport_context_weather_headwind_divisor",



        (_to_float_or_none(_ovr.get("weather_headwind_divisor")) or 8.0),



        0.25,



        80.0,



    )



    env_load_gap = (away_env_score - home_env_score) / _env_load_div



    env_exec_gap = (away_env_exec - home_env_exec) / _env_exec_div



    circ_gap = (away_risk - home_risk) / _circ_gap_div



    stats_shared = math.tanh(stats_score * max(0.20, stats_cov))



    weather_gap = 0.0



    if sport in _WEATHER_REQUIRED_CONTEXT_SPORTS:

        weather_gap = ((rho_pct_away - rho_pct_home) / _weather_rho_div) + (headwind / _weather_headwind_div)





    ref_signal = str(ref_result.get("ou_signal", "NEUTRAL") or "NEUTRAL").upper().strip()



    ref_conf = _clamp(_to_float_or_none(ref_result.get("confidence")) or 0.0, 0.0, 1.0)



    ref_bias = 0.0



    if ref_signal == "OVER":



        ref_bias = 0.16 * ref_conf



    elif ref_signal == "UNDER":



        ref_bias = -0.16 * ref_conf







    _off_w_lineup = _ctx_coeff("sport_context_off_w_lineup", 0.30, -2.0, 2.0)



    _off_w_inj = _ctx_coeff("sport_context_off_w_injury", -0.24, -2.0, 2.0)



    _off_w_env_load = _ctx_coeff("sport_context_off_w_env_load", -0.17, -2.0, 2.0)



    _off_w_env_exec = _ctx_coeff("sport_context_off_w_env_exec", -0.14, -2.0, 2.0)



    _off_w_circ = _ctx_coeff("sport_context_off_w_circadian", -0.10, -2.0, 2.0)



    _off_w_weather = _ctx_coeff("sport_context_off_w_weather", -0.08, -2.0, 2.0)



    _def_w_inj = _ctx_coeff("sport_context_def_w_injury", 0.27, -2.0, 2.0)



    _def_w_env_load = _ctx_coeff("sport_context_def_w_env_load", 0.19, -2.0, 2.0)



    _def_w_env_exec = _ctx_coeff("sport_context_def_w_env_exec", 0.12, -2.0, 2.0)



    _def_w_circ = _ctx_coeff("sport_context_def_w_circadian", 0.10, -2.0, 2.0)



    _def_w_weather = _ctx_coeff("sport_context_def_w_weather", 0.07, -2.0, 2.0)



    _shared_w_stats_off = _ctx_coeff("sport_context_shared_w_stats_off", 0.08, -2.0, 2.0)



    _shared_w_stats_def = _ctx_coeff("sport_context_shared_w_stats_def", -0.07, -2.0, 2.0)







    side_off_diff = (



        (_off_w_lineup * lineup_balance) +



        (_off_w_inj * off_loss_gap) +



        (_off_w_env_load * env_load_gap) +



        (_off_w_env_exec * env_exec_gap) +



        (_off_w_circ * circ_gap) +



        (_off_w_weather * weather_gap)



    )



    side_def_diff = (



        (_def_w_inj * def_loss_gap) +



        (_def_w_env_load * env_load_gap) +



        (_def_w_env_exec * env_exec_gap) +



        (_def_w_circ * circ_gap) +



        (_def_w_weather * weather_gap)



    )







    shared_off = (_shared_w_stats_off * stats_shared) + ref_bias



    shared_def = (_shared_w_stats_def * stats_shared) - ref_bias







    away_off_adj = _clamp(side_off_diff + shared_off, -ctx_cap, ctx_cap)



    home_off_adj = _clamp((-side_off_diff) + shared_off, -ctx_cap, ctx_cap)



    away_def_adj = _clamp((-side_def_diff) + shared_def, -ctx_cap, ctx_cap)



    home_def_adj = _clamp((side_def_diff) + shared_def, -ctx_cap, ctx_cap)







    impact_map = {



        "lineup_vs_injury": (_off_w_lineup * lineup_balance) + (_off_w_inj * off_loss_gap),



        "fatigue_load": (_off_w_env_load * env_load_gap) + (_off_w_env_exec * env_exec_gap),



        "circadian_gap": _off_w_circ * circ_gap,



        "weather_profile": _off_w_weather * weather_gap,



        "stats_sos_alignment": _shared_w_stats_off * stats_shared,



        "officials_tilt": ref_bias,



        "defense_resilience": -side_def_diff,



    }



    top = sorted(impact_map.items(), key=lambda kv: abs(kv[1]), reverse=True)



    drivers = []



    for k, v in top:



        if abs(v) < 0.02:



            continue



        drivers.append(f"{k}:{'OVER' if v > 0 else 'UNDER'} ({v:+.2f})")



        if len(drivers) >= 4:



            break



    if not drivers:



        drivers = ["sport-context near neutral"]







    return {



        "away_off_adj": round(away_off_adj, 4),



        "home_off_adj": round(home_off_adj, 4),



        "away_def_adj": round(away_def_adj, 4),



        "home_def_adj": round(home_def_adj, 4),



        "drivers": drivers,



        "components": {k: round(v, 4) for k, v in impact_map.items()},



    }











def _build_context_projection(



    sport,



    market_total_raw,



    market_over_odds_raw=None,



    market_under_odds_raw=None,



    away_team=None,



    home_team=None,



    game_date=None,



    rho_pct_home=None,



    rho_pct_away=None,



    headwind=None,



    away_env_exec=None,



    home_env_exec=None,



    away_env_score=None,



    home_env_score=None,



    away_inj_off=0.0,



    away_inj_def=0.0,



    home_inj_off=0.0,



    home_inj_def=0.0,



    away_lineup_power=0.0,



    home_lineup_power=0.0,



    lineup_signal_weight=0.0,



    ref_result=None,



    circ_result=None,



    mlb_context_total=0.0,



    stats_sos_signal=None,



    sport_specific_context=None,



):



    sport = str(sport or "").upper().strip()



    market_total = _parse_market_total(market_total_raw)



    market_over_odds = _parse_american_odds(market_over_odds_raw)



    market_under_odds = _parse_american_odds(market_under_odds_raw)







    away_env_exec = _to_float_or_none(away_env_exec) or 0.0



    home_env_exec = _to_float_or_none(home_env_exec) or 0.0



    away_env_score = _to_float_or_none(away_env_score) or 0.0



    home_env_score = _to_float_or_none(home_env_score) or 0.0



    away_inj_off = _to_float_or_none(away_inj_off) or 0.0



    away_inj_def = _to_float_or_none(away_inj_def) or 0.0



    home_inj_off = _to_float_or_none(home_inj_off) or 0.0



    home_inj_def = _to_float_or_none(home_inj_def) or 0.0



    away_lineup_power = _to_float_or_none(away_lineup_power) or 0.0



    home_lineup_power = _to_float_or_none(home_lineup_power) or 0.0



    lineup_signal_weight = _clamp(_to_float_or_none(lineup_signal_weight) or 0.0, 0.0, 1.0)



    rho_pct_home = _to_float_or_none(rho_pct_home)



    rho_pct_away = _to_float_or_none(rho_pct_away)



    headwind = _to_float_or_none(headwind)



    mlb_context_total = _to_float_or_none(mlb_context_total) or 0.0







    ref_result = ref_result or {}



    circ_result = circ_result or {}



    stats_sos_signal = stats_sos_signal or {}



    sport_specific_context = sport_specific_context or {}







    dyn = _context_dynamic_projection_params(



        sport,



        away_team=away_team,



        home_team=home_team,



        game_date_iso=game_date,



        stats_sos_signal=stats_sos_signal,



    )



    _ovr = _context_get_sport_params(sport)



    base_total = float(dyn.get("baseline_total", _CONTEXT_BASELINE_TOTALS.get(sport, 10.0)))



    total_step = float(dyn.get("total_step", _CONTEXT_TOTAL_STEP.get(sport, 1.0)))



    edge_thr = float(dyn.get("edge_threshold", _CONTEXT_EDGE_THRESH.get(sport, 1.0)))







    sp_off_away = _to_float_or_none(sport_specific_context.get("away_off_adj")) or 0.0



    sp_off_home = _to_float_or_none(sport_specific_context.get("home_off_adj")) or 0.0



    sp_def_away = _to_float_or_none(sport_specific_context.get("away_def_adj")) or 0.0



    sp_def_home = _to_float_or_none(sport_specific_context.get("home_def_adj")) or 0.0







    stats_score = _to_float_or_none(stats_sos_signal.get("score")) or 0.0



    stats_cov = _clamp(_to_float_or_none(stats_sos_signal.get("coverage")) or 0.0, 0.0, 1.0)



    stats_bias = stats_score * max(0.10, stats_cov)







    ref_signal = str(ref_result.get("ou_signal", "NEUTRAL") or "NEUTRAL").upper().strip()



    ref_conf = _clamp(_to_float_or_none(ref_result.get("confidence")) or 0.0, 0.0, 1.0)



    ref_bias = 0.0



    if ref_signal == "OVER":



        ref_bias = 0.32 * ref_conf



    elif ref_signal == "UNDER":



        ref_bias = -0.32 * ref_conf







    away_risk = _to_float_or_none(circ_result.get("away_score")) or 0.0



    home_risk = _to_float_or_none(circ_result.get("home_score")) or 0.0







    lineup_delta = away_lineup_power - home_lineup_power



    lineup_boost_base = _clamp(_to_float_or_none(_ovr.get("lineup_boost_base")) or 0.40, 0.0, 2.5)



    lineup_boost_span = _clamp(_to_float_or_none(_ovr.get("lineup_boost_span")) or 0.60, 0.0, 3.0)



    lineup_boost = (lineup_boost_base + lineup_boost_span * lineup_signal_weight)



    lineup_off_away = lineup_delta * lineup_boost



    lineup_off_home = -lineup_off_away



    lineup_def_away = (-home_lineup_power) * lineup_boost



    lineup_def_home = (-away_lineup_power) * lineup_boost







    inj_off_away = home_inj_def - away_inj_off



    inj_off_home = away_inj_def - home_inj_off



    inj_def_away = home_inj_off - away_inj_def



    inj_def_home = away_inj_off - home_inj_def







    env_off_away = (home_env_exec - away_env_exec) + 0.05 * (home_env_score - away_env_score)



    env_off_home = (away_env_exec - home_env_exec) + 0.05 * (away_env_score - home_env_score)



    env_def_away = 0.85 * (home_env_exec - away_env_exec)



    env_def_home = 0.85 * (away_env_exec - home_env_exec)







    _dyn_meta = dict(dyn.get("meta") or {}) if isinstance(dyn, dict) else {}



    _std_scale = _clamp(_to_float_or_none(_dyn_meta.get("std_scale")) or 1.0, 0.70, 1.35)



    _calib_samples = int(_to_float_or_none(_ovr.get("calibration_samples")) or 0)



    _sparse_mult = 1.15 if _calib_samples < 12 else 1.0



    _weather_divisor_source = {}







    def _resolve_weather_divisor(param_key, base_default):



        _raw = _to_float_or_none(_ovr.get(param_key))



        if _raw is not None and _raw > 0:



            _weather_divisor_source[param_key] = "calibrated"



            return max(0.25, float(_raw))



        _weather_divisor_source[param_key] = "adaptive_fallback"



        return max(0.25, float(base_default) * float(_std_scale) * float(_sparse_mult))







    rho_off_div = _resolve_weather_divisor("weather_rho_off_divisor", 4.0)



    rho_def_div = _resolve_weather_divisor("weather_rho_def_divisor", 4.6)



    headwind_div = _resolve_weather_divisor("weather_headwind_divisor", 5.0)



    rho_off_sum = 0.0



    rho_def_sum = 0.0



    hw_off_sum = 0.0



    hw_def_sum = 0.0



    weather_off_away = 0.0



    weather_off_home = 0.0



    weather_def_away = 0.0



    weather_def_home = 0.0



    if sport in _WEATHER_REQUIRED_CONTEXT_SPORTS:

        if rho_pct_away is not None:

            weather_off_away += (-rho_pct_away / rho_off_div)

            weather_def_away += (rho_pct_away / rho_def_div)

            rho_off_sum += (-rho_pct_away / rho_off_div)



            rho_def_sum += (rho_pct_away / rho_def_div)



        if rho_pct_home is not None:



            weather_off_home += (-rho_pct_home / rho_off_div)



            weather_def_home += (rho_pct_home / rho_def_div)



            rho_off_sum += (-rho_pct_home / rho_off_div)



            rho_def_sum += (rho_pct_home / rho_def_div)



        if headwind is not None:



            hw_comp = headwind / headwind_div



            weather_off_away += hw_comp



            weather_off_home += hw_comp



            weather_def_away -= hw_comp * 0.8



            weather_def_home -= hw_comp * 0.8



            hw_off_sum += (2.0 * hw_comp)



            hw_def_sum += (-1.6 * hw_comp)







    circ_off_div = max(0.25, _to_float_or_none(_ovr.get("circadian_off_divisor")) or 6.0)



    circ_def_div = max(0.25, _to_float_or_none(_ovr.get("circadian_def_divisor")) or 7.0)



    circ_off_away = (home_risk - away_risk) / circ_off_div



    circ_off_home = (away_risk - home_risk) / circ_off_div



    circ_def_away = (home_risk - away_risk) / circ_def_div



    circ_def_home = (away_risk - home_risk) / circ_def_div







    shared_stats = stats_bias * 0.5



    shared_ref = ref_bias * 0.5



    mlb_shared_mult = _clamp(_to_float_or_none(_ovr.get("mlb_shared_multiplier")) or 0.45, -2.0, 2.0)



    shared_mlb = (mlb_context_total * mlb_shared_mult) if sport == "MLB" else 0.0



    if sport == "MLB" and bool(sport_specific_context.get("mlb_side_specific")):



        shared_mlb = 0.0







    off_families = {



        "injuries": (inj_off_away, inj_off_home),



        "environment": (env_off_away, env_off_home),



        "lineup": (lineup_off_away, lineup_off_home),



        "weather": (weather_off_away, weather_off_home),



        "circadian": (circ_off_away, circ_off_home),



        "stats_sos": (shared_stats, shared_stats),



        "officials": (shared_ref, shared_ref),



        "mlb_pregame": (shared_mlb, shared_mlb),



        "sport_context": (sp_off_away, sp_off_home),



    }



    def_families = {



        "injuries": (inj_def_away, inj_def_home),



        "environment": (env_def_away, env_def_home),



        "lineup": (lineup_def_away, lineup_def_home),



        "weather": (weather_def_away, weather_def_home),



        "circadian": (circ_def_away, circ_def_home),



        "stats_sos": (-shared_stats, -shared_stats),



        "officials": (-shared_ref, -shared_ref),



        "mlb_pregame": (-shared_mlb, -shared_mlb),



        "sport_context": (sp_def_away, sp_def_home),



    }







    off_weights = _normalize_feature_weights(off_families, sport=sport, family_kind="offense")



    def_weights = _normalize_feature_weights(def_families, sport=sport, family_kind="defense")







    away_off_ctx = sum(off_weights[k] * off_families[k][0] for k in off_families)



    home_off_ctx = sum(off_weights[k] * off_families[k][1] for k in off_families)



    away_def_ctx = sum(def_weights[k] * def_families[k][0] for k in def_families)



    home_def_ctx = sum(def_weights[k] * def_families[k][1] for k in def_families)







    away_points = (base_total / 2.0) + total_step * (away_off_ctx - home_def_ctx)



    home_points = (base_total / 2.0) + total_step * (home_off_ctx - away_def_ctx)







    _sport_floor_default = {



        "MLB": 0.8,



        "NBA": 70.0,



        "NHL": 0.5,



        "NFL": 6.0,



        "NCAAB": 45.0,



        "NCAAF": 7.0,



    }.get(sport, 0.0)



    _sport_cap_default = {



        "MLB": 12.5,



        "NBA": 155.0,



        "NHL": 9.5,



        "NFL": 42.0,



        "NCAAB": 105.0,



        "NCAAF": 60.0,



    }.get(sport, 200.0)



    _sport_floor = _to_float_or_none(_ovr.get("points_floor"))



    _sport_cap = _to_float_or_none(_ovr.get("points_cap"))



    if _sport_floor is None:



        _sport_floor = _sport_floor_default



    if _sport_cap is None:



        _sport_cap = _sport_cap_default



    if _sport_cap < _sport_floor:



        _sport_cap = _sport_floor



    away_points = _clamp(away_points, _sport_floor, _sport_cap)



    home_points = _clamp(home_points, _sport_floor, _sport_cap)



    projected_total = away_points + home_points







    reference_total = market_total if market_total is not None else base_total



    edge_vs_reference = projected_total - reference_total



    over_prob = None



    under_prob = None



    fair_over_american = None



    fair_under_american = None



    over_ev = None



    under_ev = None



    vig_free_over_prob = None



    vig_free_under_prob = None



    break_even_over = _implied_prob_from_american(market_over_odds) if market_over_odds is not None else None



    break_even_under = _implied_prob_from_american(market_under_odds) if market_under_odds is not None else None



    if (break_even_over is None) or (break_even_under is None):



        _default_be = _clamp(_to_float_or_none(_ovr.get("default_break_even_prob")) or (110.0 / 210.0), 0.50, 0.70)



        if break_even_over is None:



            break_even_over = _default_be



        if break_even_under is None:



            break_even_under = _default_be



    if (market_over_odds is not None) and (market_under_odds is not None):



        _raw_over = _implied_prob_from_american(market_over_odds)



        _raw_under = _implied_prob_from_american(market_under_odds)



        _sum_raw = (_raw_over or 0.0) + (_raw_under or 0.0)



        if _sum_raw > 1e-6:



            vig_free_over_prob = (_raw_over or 0.0) / _sum_raw



            vig_free_under_prob = (_raw_under or 0.0) / _sum_raw







    prob_thr = _clamp(_to_float_or_none(_ovr.get("probability_threshold")) or 0.525, 0.50, 0.70)



    if market_total is None:



        if abs(edge_vs_reference) < edge_thr:



            lean = "NEUTRAL"



        else:



            lean = "OVER" if edge_vs_reference > 0 else "UNDER"



    else:



        sigma = _to_float_or_none(_ovr.get("total_sigma"))



        if sigma is None:



            sigma = _to_float_or_none((dyn.get("meta") or {}).get("league_total_std"))



        if sigma is None:



            sigma = {



                "MLB": 2.15,



                "NBA": 23.0,



                "NHL": 1.55,



                "NFL": 12.5,



                "NCAAB": 17.5,



                "NCAAF": 16.0,



            }.get(sport, 8.0)



        sigma = max(0.35, float(sigma))



        z = (projected_total - market_total) / sigma



        over_prob = 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))



        under_prob = 1.0 - over_prob



        fair_over_american = _fair_american_from_prob(over_prob)



        fair_under_american = _fair_american_from_prob(under_prob)



        if market_over_odds is not None:



            over_ev = _expected_value_from_prob(over_prob, market_over_odds)



        if market_under_odds is not None:



            under_ev = _expected_value_from_prob(under_prob, market_under_odds)







        # EV-first selection when market odds are available; fallback to probability/edge logic.



        min_ev = _to_float_or_none(_ovr.get("min_expected_value"))



        if min_ev is None:



            min_ev = 0.0125



        min_ev = _clamp(float(min_ev), -0.05, 0.20)



        be_edge = _to_float_or_none(_ovr.get("break_even_prob_edge"))



        if be_edge is None:



            be_edge = 0.005



        be_edge = _clamp(float(be_edge), 0.0, 0.08)







        over_ok = (



            (over_prob is not None) and



            (break_even_over is not None) and



            (over_prob >= (break_even_over + be_edge)) and



            ((over_ev is None) or (over_ev >= min_ev)) and



            (edge_vs_reference >= 0)



        )



        under_ok = (



            (under_prob is not None) and



            (break_even_under is not None) and



            (under_prob >= (break_even_under + be_edge)) and



            ((under_ev is None) or (under_ev >= min_ev)) and



            (edge_vs_reference <= 0)



        )







        if over_ok and under_ok:



            _ov_metric = (over_ev if over_ev is not None else (over_prob - break_even_over))



            _un_metric = (under_ev if under_ev is not None else (under_prob - break_even_under))



            lean = "OVER" if _ov_metric >= _un_metric else "UNDER"



        elif over_ok:



            lean = "OVER"



        elif under_ok:



            lean = "UNDER"



        elif (over_prob >= prob_thr) and (edge_vs_reference >= 0):



            lean = "OVER"



        elif (under_prob >= prob_thr) and (edge_vs_reference <= 0):



            lean = "UNDER"



        elif abs(edge_vs_reference) >= (edge_thr * 1.25):



            lean = "OVER" if edge_vs_reference > 0 else "UNDER"



        else:



            lean = "NEUTRAL"







    ctx_sep = abs(away_off_ctx - home_off_ctx) + abs(away_def_ctx - home_def_ctx)



    prob_conf = 0.0



    if (over_prob is not None) and (under_prob is not None):



        prob_conf = abs(max(over_prob, under_prob) - 0.50) * 3.0



    confidence_strength = (abs(edge_vs_reference) / max(edge_thr, 0.01)) + (ctx_sep * 0.35) + prob_conf



    if confidence_strength < 1.0:



        confidence = "Low"



    elif confidence_strength < 2.0:



        confidence = "Moderate"



    elif confidence_strength < 3.0:



        confidence = "High"



    else:



        confidence = "Strong"







    family_impacts = {}



    for fam in off_families.keys():



        off_imp = off_weights.get(fam, 0.0) * (off_families[fam][0] + off_families[fam][1])



        def_imp = def_weights.get(fam, 0.0) * (def_families[fam][0] + def_families[fam][1])



        family_impacts[fam] = round(off_imp - def_imp, 4)



    weather_off_w = off_weights.get("weather", 0.0)



    weather_def_w = def_weights.get("weather", 0.0)



    circ_off_w = off_weights.get("circadian", 0.0)



    circ_def_w = def_weights.get("circadian", 0.0)



    component_effects = {



        "weather_rho_off_effect": round(weather_off_w * rho_off_sum, 4),



        "weather_rho_def_effect": round((-weather_def_w) * rho_def_sum, 4),



        "weather_headwind_effect": round((weather_off_w * hw_off_sum) - (weather_def_w * hw_def_sum), 4),



        "circadian_effect": round(



            (circ_off_w * (circ_off_away + circ_off_home)) -



            (circ_def_w * (circ_def_away + circ_def_home)),



            4,



        ),



    }



    top_drivers = sorted(



        family_impacts.items(),



        key=lambda kv: abs(kv[1]),



        reverse=True,



    )



    drivers = []



    for fam, imp in top_drivers:



        if abs(imp) < 0.015:



            continue



        dir_txt = "OVER" if imp > 0 else "UNDER"



        drivers.append(f"{fam}:{dir_txt} ({imp:+.2f})")



        if len(drivers) >= 6:



            break



    if not drivers:



        drivers = ["Context near neutral"]



    for _sdrv in list(sport_specific_context.get("drivers", []) or []):



        _d = str(_sdrv).strip()



        if not _d:



            continue



        _fmt = f"sport:{_d}"



        if _fmt in drivers:



            continue



        drivers.append(_fmt)



        if len(drivers) >= 8:



            break







    coverage_terms = [



        1.0 if (rho_pct_home is not None or rho_pct_away is not None) else 0.0,

        1.0 if (abs(away_inj_off) + abs(away_inj_def) + abs(home_inj_off) + abs(home_inj_def)) > 0 else 0.35,



        1.0 if (lineup_signal_weight > 0.0 or abs(away_lineup_power) > 0 or abs(home_lineup_power) > 0) else 0.3,



        _clamp(stats_cov, 0.0, 1.0),



        1.0 if (away_risk > 0 or home_risk > 0) else 0.45,



    ]



    if sport == "MLB":



        coverage_terms.append(1.0 if abs(mlb_context_total) > 0 else 0.25)



    if any(abs(x) > 1e-9 for x in (sp_off_away, sp_off_home, sp_def_away, sp_def_home)):



        coverage_terms.append(1.0)



    quality_score = round(sum(coverage_terms) / max(len(coverage_terms), 1), 3)







    return {



        "baseline_total": round(base_total, 3),



        "market_total": round(market_total, 3) if market_total is not None else None,



        "projected_total": round(projected_total, 3),



        "projected_away": round(away_points, 3),



        "projected_home": round(home_points, 3),



        "edge_vs_market": round(projected_total - market_total, 3) if market_total is not None else None,



        "edge_vs_baseline": round(projected_total - base_total, 3),



        "over_probability": round(float(over_prob), 4) if over_prob is not None else None,



        "under_probability": round(float(under_prob), 4) if under_prob is not None else None,



        "vig_free_over_probability": round(float(vig_free_over_prob), 4) if vig_free_over_prob is not None else None,



        "vig_free_under_probability": round(float(vig_free_under_prob), 4) if vig_free_under_prob is not None else None,



        "probability_threshold": round(float(prob_thr), 4) if market_total is not None else None,



        "market_over_odds": market_over_odds,



        "market_under_odds": market_under_odds,



        "fair_over_american": fair_over_american,



        "fair_under_american": fair_under_american,



        "break_even_over": round(float(break_even_over), 4) if break_even_over is not None else None,



        "break_even_under": round(float(break_even_under), 4) if break_even_under is not None else None,



        "over_ev_per_1": round(float(over_ev), 4) if over_ev is not None else None,



        "under_ev_per_1": round(float(under_ev), 4) if under_ev is not None else None,



        "lean": lean,



        "confidence": confidence,



        "away_off_context": round(away_off_ctx, 4),



        "home_off_context": round(home_off_ctx, 4),



        "away_def_context": round(away_def_ctx, 4),



        "home_def_context": round(home_def_ctx, 4),



        "quality_score": quality_score,



        "drivers": drivers,



        "weights_off": {k: round(v, 4) for k, v in off_weights.items()},



        "weights_def": {k: round(v, 4) for k, v in def_weights.items()},



        "family_impacts": family_impacts,



        "component_effects": component_effects,



        "coefficients": {



            "weather_rho_off_divisor": round(float(rho_off_div), 6),



            "weather_rho_def_divisor": round(float(rho_def_div), 6),



            "weather_headwind_divisor": round(float(headwind_div), 6),



            "weather_divisor_source": dict(_weather_divisor_source),



            "weather_divisor_std_scale": round(float(_std_scale), 6),



            "weather_divisor_calibration_samples": int(_calib_samples),



            "circadian_off_divisor": round(float(circ_off_div), 6),



            "circadian_def_divisor": round(float(circ_def_div), 6),



            "lineup_boost_base": round(float(lineup_boost_base), 6),



            "lineup_boost_span": round(float(lineup_boost_span), 6),



            "mlb_shared_multiplier": round(float(mlb_shared_mult), 6),



        },



        "sport_specific_context": sport_specific_context,



        "dynamic_params": dyn.get("meta", {}),



    }











def _evaluate_game_data_quality(



    sport,



    game_date,



    weather_required,



    weather,



    home_elev_ft,



    injury_has_data,



    stats_sos_signal,



    mlb_ctx_available,



    projection,



    matching_issues=None,



    injury_validity=None,



    child_source_map=None,



):



    sport = str(sport or "").upper().strip()



    issues = []



    warnings = []







    if not str(game_date or "").strip():



        issues.append("missing_game_date")







    _wx_contract = _core_eval_weather_elevation_contract(

        weather_required=bool(weather_required),

        weather=(weather if isinstance(weather, dict) else {}),

        home_elev_ft=home_elev_ft,

    )

    wx_ok = bool(_wx_contract.get("wx_ok", False))

    issues.extend([str(x) for x in list(_wx_contract.get("issues") or []) if str(x).strip()])

    warnings.extend([str(x) for x in list(_wx_contract.get("warnings") or []) if str(x).strip()])





    if sport == "MLB" and not mlb_ctx_available:



        issues.append("mlb_pregame_context_unavailable")







    injury_validity = dict(injury_validity or {})



    invalid_inj_states = {"SOURCE_NO_DATA", "SOURCE_FAILED", "SOURCE_BLOCKED", "UNMATCHED_TEAM", "AMBIGUOUS_TEAM", "RESOLVER_MISS"}



    for side in ("away", "home"):



        state = str(injury_validity.get(f"{side}_validity", "") or "").upper().strip()



        if state in invalid_inj_states:



            issues.append(f"injury_news_{side}_{state.lower()}")



    if not injury_has_data:



        states = {



            str(injury_validity.get("away_validity", "") or "").upper().strip(),



            str(injury_validity.get("home_validity", "") or "").upper().strip(),



        }



        if states and states.issubset({



            "CONFIRMED_NO_INJURIES",



            "CONFIRMED_NO_INJURIES_PARTIAL_SOURCE",



            "HAS_NEWS",



        }):



            warnings.append("injury_impact_cache_not_needed_confirmed_clean")



        else:



            warnings.append("injury_impact_cache_not_ready")



    try:



        _inj_path = _injury_news_file_path(sport)



        if not _inj_path.exists():



            issues.append("injury_news_file_missing")



        else:



            _inj_day = datetime.fromtimestamp(_inj_path.stat().st_mtime).date()



            if _inj_day != datetime.now().date():



                issues.append("injury_news_file_stale")



    except GUI_ERRORS:



        warnings.append("injury_news_file_check_failed")







    stats_cov = _clamp(_to_float_or_none((stats_sos_signal or {}).get("coverage")) or 0.0, 0.0, 1.0)



    _ovr = _context_get_sport_params(sport)



    _min_stats_cov = _to_float_or_none(_ovr.get("min_stats_sos_coverage"))



    if _min_stats_cov is None:



        _min_stats_cov = float(_SPORT_MIN_STATS_SOS_COVERAGE.get(sport, 0.20))



    _min_stats_cov = _clamp(float(_min_stats_cov), 0.0, 1.0)



    if stats_cov < _min_stats_cov:



        issues.append(f"stats_sos_coverage_below_min:{stats_cov:.2f}<min_{_min_stats_cov:.2f}")



    elif stats_cov < 0.35:



        warnings.append("low_stats_sos_coverage")







    if _to_float_or_none((projection or {}).get("market_total")) is None:



        warnings.append("missing_market_total")







    quality_score = _to_float_or_none((projection or {}).get("quality_score")) or 0.0



    _min_quality = _to_float_or_none(_ovr.get("min_context_quality"))



    if _min_quality is None:



        _min_quality = float(_SPORT_MIN_CONTEXT_QUALITY.get(sport, 0.50))



    _min_quality = _clamp(float(_min_quality), 0.0, 1.0)



    if quality_score < _min_quality:



        issues.append(f"projection_quality_too_low:{quality_score:.2f}<min_{_min_quality:.2f}")



    _dyn_meta = dict((projection or {}).get("dynamic_params") or {}) if isinstance(projection, dict) else {}



    _dyn_src = str(_dyn_meta.get("source", "") or "").strip().lower()



    if _dyn_src == "fallback":



        _afg = int(_to_float_or_none(_dyn_meta.get("away_form_games")) or 0)



        _hfg = int(_to_float_or_none(_dyn_meta.get("home_form_games")) or 0)



        _scov = _clamp(_to_float_or_none(_dyn_meta.get("stats_coverage")) or 0.0, 0.0, 1.0)



        if (_afg + _hfg <= 1) and (_scov < 0.15):



            issues.append("dynamic_baseline_unavailable")



        else:



            warnings.append("dynamic_baseline_fallback")



    elif _dyn_src in {"team_form", "stats_sos"}:



        warnings.append(f"dynamic_baseline_partial:{_dyn_src}")



    try:



        _wsets = []



        if isinstance(projection, dict):



            _wsets.extend([projection.get("weights_off") or {}, projection.get("weights_def") or {}])



        _max_w = max([abs(float(v)) for ws in _wsets for v in dict(ws).values()] or [0.0])



        _dominance_limit = _clamp(



            _to_float_or_none(_context_get_sport_params(sport).get("dominance_block_threshold")) or 0.82,



            0.55,



            0.98,



        )



        if _max_w > _dominance_limit:



            issues.append(f"single_feature_dominance:{_max_w:.2f}>lim_{_dominance_limit:.2f}")



        elif _max_w > (_dominance_limit * 0.90):



            warnings.append(f"single_feature_dominance_watch:{_max_w:.2f}")



    except DATA_ERRORS:



        warnings.append("feature_dominance_check_failed")







    for _mi in (matching_issues or []):



        _tag = str(_mi or "").strip().lower()



        if not _tag:



            continue



        _full = f"entity_match_{_tag}"



        if _full in issues or _full in warnings:



            continue



        if ("ambiguous" in _tag) or ("unmatched" in _tag) or ("collision" in _tag):



            issues.append(_full)



        else:



            warnings.append(_full)







    source_map = [m for m in list(child_source_map or []) if isinstance(m, dict)]



    required_children = {



        "odds_scraper",



        "venue_registry",



        "travel_rest_scraper",



        "injury_news_gameday_builder",



        "stats_sos_integration",



    }

    optional_children = {

        "cre_integration", "nea_lineup_assessor", "referees_daily_unified",

        "espn_scoreboard", "weather_feed", "mlb_stats_daily",

    }



    if weather_required:



        required_children.add("weather_feed")



    if sport == "MLB":



        required_children.add("mlb_stats_daily")

        optional_children.discard("mlb_stats_daily")



    blocking_source_statuses = {



        "MISSING", "FAILED", "SOURCE_NO_DATA", "SOURCE_FAILED", "SOURCE_BLOCKED",



        "UNMATCHED", "UNMATCHED_TEAM", "AMBIGUOUS", "AMBIGUOUS_TEAM",



        "LOW_COVERAGE", "CHECK_FAILED", "STALE", "BLOCKED", "RESOLVER_MISS",



    }



    warning_source_statuses = {



        "PARTIAL", "NOT_POSTED_OR_UNAVAILABLE", "NOT_FOUND",



        "CONFIRMED_NO_INJURIES_PARTIAL_SOURCE",



    }



    partial_blocking_children = {



        # Keep strict blocking only where PARTIAL means unresolved integrity risk.



        "injury_news_gameday_builder",



    }



    non_blocking_ok_statuses = {



        "READY", "CONFIRMED_NO_INJURIES", "HAS_INJURIES", "HAS_NEWS",



        # Backward-compat legacy state from injury builder validity sheet.



        "SOURCE_OK_WITH_ROWS",



    }



    seen_required = set()



    for sm in source_map:



        child = str(sm.get("child", "") or "").strip()



        status = str(sm.get("status", "") or "UNKNOWN").upper().strip()



        c_missing = [str(x).strip() for x in list(sm.get("contract_missing", []) or []) if str(x).strip()]



        c_invalid = [str(x).strip() for x in list(sm.get("contract_invalid", []) or []) if str(x).strip()]



        if status.startswith("READ_ERROR"):



            status = "FAILED"



        elif status in {"NO_FILE", "NO_STRUCTURED_SHEETS", "UNKNOWN"}:



            status = "MISSING"



        side = str(sm.get("team_side", "") or "").strip()



        if child in required_children:



            seen_required.add(child)



            if c_missing:



                issues.append(f"child_source_contract_missing_{child}_{side or 'game'}:{','.join(c_missing)}")



            if c_invalid:



                issues.append(f"child_source_contract_invalid_{child}_{side or 'game'}:{','.join(c_invalid)}")



            if status in blocking_source_statuses:



                issues.append(f"child_source_required_{child}_{side or 'game'}_{status.lower()}")



            elif status in warning_source_statuses:



                if status == "PARTIAL" and child in partial_blocking_children:



                    issues.append(f"child_source_required_{child}_{side or 'game'}_{status.lower()}")



                else:



                    warnings.append(f"child_source_partial_{child}_{side or 'game'}_{status.lower()}")



            elif status not in non_blocking_ok_statuses:



                issues.append(f"child_source_required_{child}_{side or 'game'}_unclassified:{status.lower()}")



    for child in sorted(required_children - seen_required):



        issues.append(f"child_source_missing_map_{child}")







    can_emit_pick = len(issues) == 0



    return {



        "can_emit_pick": can_emit_pick,



        "issues": issues,



        "warnings": warnings,



        "quality_score": round(quality_score, 3),



    }











def _write_anomaly_report(records, report_name="todays_picks"):



    records = list(records or [])



    out_dir = SCRIPT_DIR / "diagnostics"



    out_dir.mkdir(parents=True, exist_ok=True)



    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")



    out_path = out_dir / f"{report_name}_anomaly_report_{stamp}.json"



    tmp_path = out_path.with_suffix(".json.tmp")



    payload = {



        "generated_at": datetime.now().astimezone().isoformat(),



        "report_name": report_name,



        "records": records,



        "summary": {



            "records": len(records),



            "blocking": sum(



                1



                for r in records



                if str(r.get("status", "")).upper().startswith("BLOCKED")



                or str(r.get("status", "")).upper() in {"SKIPPED", "SKIPPED_STARTED", "ERROR"}



            ),



            "match_issue_records": sum(



                1



                for r in records



                if len(list(r.get("match_issues", []) or [])) > 0



            ),



        },



    }



    with _ANOMALY_FILE_LOCK:



        try:



            with open(tmp_path, "w", encoding="utf-8") as f:



                json.dump(payload, f, indent=2)



            os.replace(str(tmp_path), str(out_path))



        finally:



            try:



                if tmp_path.exists():



                    tmp_path.unlink()



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

    return str(out_path)











def _write_source_contract_report(records, report_name="todays_picks"):



    """Write row-level source contract/quarantine report (JSON + CSV)."""



    rows = list(records or [])



    out_dir = SCRIPT_DIR / "diagnostics"



    out_dir.mkdir(parents=True, exist_ok=True)



    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")



    base = f"{report_name}_source_contract_{stamp}"



    json_path = out_dir / f"{base}.json"



    csv_path = out_dir / f"{base}.csv"



    tmp_json = json_path.with_suffix(".json.tmp")



    tmp_csv = csv_path.with_suffix(".csv.tmp")



    payload = {



        "generated_at": datetime.now().astimezone().isoformat(),



        "report_name": report_name,



        "records": rows,



        "summary": {



            "records": len(rows),



            "by_sport": {},



            "by_issue_code": {},



        },



    }



    for r in rows:



        _sp = str(r.get("sport", "") or "").upper().strip() or "UNK"



        _ic = str(r.get("issue_code", "") or "").strip() or "unknown"



        payload["summary"]["by_sport"][_sp] = int(payload["summary"]["by_sport"].get(_sp, 0) or 0) + 1



        payload["summary"]["by_issue_code"][_ic] = int(payload["summary"]["by_issue_code"].get(_ic, 0) or 0) + 1



    with _ANOMALY_FILE_LOCK:



        try:



            with open(tmp_json, "w", encoding="utf-8") as f:



                json.dump(payload, f, indent=2)



            os.replace(str(tmp_json), str(json_path))



            _csv_fields = [



                "run_timestamp", "sport", "source", "source_kind", "row_index", "issue_code", "detail",



                "away_raw", "home_raw", "time_raw", "total_raw", "game_date",



            ]



            with open(tmp_csv, "w", newline="", encoding="utf-8") as f:



                _wr = csv.DictWriter(f, fieldnames=_csv_fields, extrasaction="ignore")



                _wr.writeheader()



                for r in rows:



                    _wr.writerow({k: r.get(k, "") for k in _csv_fields})



            os.replace(str(tmp_csv), str(csv_path))



        finally:



            for _tmp in (tmp_json, tmp_csv):



                try:



                    if _tmp.exists():



                        _tmp.unlink()



                except GUI_ERRORS as _e:



                    _warn_exception("silent_except", _e)

    return {"json": str(json_path), "csv": str(csv_path)}











def _issue_where_why(issue_code: str):



    _code = str(issue_code or "").strip()



    _lc = _code.lower()



    if _lc.startswith("ready_sports="):



        return ("pipeline_gate.ready_sports", "READY leagues at run time; no eligible validated rows were produced from them.")



    if "league_not_ready_for_pick_emission" in _lc:



        return ("pipeline_gate.readiness", "League was not READY for pick emission at run time; game was scanned for data integrity only.")



    if _lc.startswith("scan_file_read_failed:"):



        return ("odds_source_file", "Could not read the source odds file during fallback missing-data scan.")



    if "scan_file_empty" in _lc:



        return ("odds_source_file", "Fallback scan file existed but contained zero rows.")



    if "missing_away_team" in _lc:



        return ("odds_source.Away_Team", "Away team was missing in source odds row.")



    if "missing_home_team" in _lc:



        return ("odds_source.Home_Team", "Home team was missing in source odds row.")



    if "rows_missing_core_fields" in _lc:



        return ("odds_source.row_contract", "Source row was missing one or more core fields (away/home/time).")



    if "rows_home_away_collision" in _lc:



        return ("odds_source.team_keys", "Away/home in source row resolved to the same canonical team key.")



    if "duplicate_game_keys" in _lc:



        return ("odds_source.dedup", "Duplicate canonical matchup/date keys were detected in source rows.")



    if _lc.startswith("child_source_contract_missing_"):



        return ("child_source_contract.required_fields", "Child source row was present but required fields were missing for this game mapping.")



    if _lc.startswith("child_source_contract_invalid_"):



        return ("child_source_contract.field_types", "Child source row included non-numeric/invalid typed fields required by the game mapping contract.")



    if "missing_game_date" in _lc:



        return ("odds_source.Time", "Game date token was missing after time parsing.")



    if "missing_time" in _lc or "no_parseable_game_dates" in _lc:



        return ("odds_source.Time", "Game time/date token was missing or unparseable.")



    if "missing_weather_fields" in _lc or "weather_incomplete" in _lc:



        return ("weather_feed", "Required weather fields were incomplete for this game context.")



    if "missing_home_elevation" in _lc:



        return ("venue_db.elevation", "Home venue elevation missing or non-numeric.")



    if "missing_market_total" in _lc:



        return ("odds_source.Total", "Market total/O-U line missing for this game.")



    if _lc.startswith("source_contract:"):



        return ("odds_source.contract", "Source row failed schema/parse contract checks and was quarantined for review.")



    if "injury_news_file_missing" in _lc:



        return ("injury_news_output", "Expected injury/news file did not exist at run time.")



    if "injury_news_file_stale" in _lc:



        return ("injury_news_output", "Injury/news file exists but was stale for today's run.")



    if "injury_news_file_check_failed" in _lc:



        return ("injury_news_output", "Injury/news workbook metadata check failed at run time.")



    if "injury_news_away_source_no_data" in _lc or "injury_news_away_source_no_data" in _lc:



        return ("injury_news_output.INJURIES.away", "Away injury/news source was unavailable or placeholder-only; not confirmed clean.")



    if "injury_news_home_source_no_data" in _lc:



        return ("injury_news_output.INJURIES.home", "Home injury/news source was unavailable or placeholder-only; not confirmed clean.")



    if "injury_news_away_source_failed" in _lc or "injury_news_away_source_blocked" in _lc:



        return ("injury_news_output.INJURIES.away", "Away injury/news source failed or was blocked.")



    if "injury_news_home_source_failed" in _lc or "injury_news_home_source_blocked" in _lc:



        return ("injury_news_output.INJURIES.home", "Home injury/news source failed or was blocked.")



    if "injury_news_away_unmatched_team" in _lc or "injury_news_away_unmatched_team" in _lc:



        return ("injury_news_output.team_name.away", "Away team could not be matched in injury/news workbook.")



    if "injury_news_home_unmatched_team" in _lc:



        return ("injury_news_output.team_name.home", "Home team could not be matched in injury/news workbook.")



    if "injury_news_away_ambiguous_team" in _lc or "ambiguous_away_injury_news_team" in _lc:



        return ("injury_news_output.team_name.away", "Multiple away-team candidates matched in injury/news data.")



    if "injury_news_home_ambiguous_team" in _lc or "ambiguous_home_injury_news_team" in _lc:



        return ("injury_news_output.team_name.home", "Multiple home-team candidates matched in injury/news data.")



    if "injury_news_away_side_filter_fallback" in _lc or "injury_news_home_side_filter_fallback" in _lc:



        return ("injury_news_output.team_side", "Side-specific matching failed and fallback matching was used.")



    if "injury_impact_cache_not_ready" in _lc:



        return ("nea_stats_cache/injury impact", "Injury source may be present, but player impact cache was not ready for scoring.")



    if "injury_impact_cache_not_needed_confirmed_clean" in _lc:



        return ("nea_stats_cache/injury impact", "Both teams were source-confirmed clean; impact cache was not required.")



    if "mlb_pregame_context_unavailable" in _lc:



        return ("mlb_pregame_db", "MLB pregame context was unavailable for this game.")



    if "unmatched_home_team_venue_db" in _lc:



        return ("venue_db.team_match.home", "Home team could not be matched in venue DB for this league.")



    if "unmatched_away_team_venue_db" in _lc:



        return ("venue_db.team_match.away", "Away team could not be matched in venue DB for this league.")



    if "league_mismatch_home_team_venue_db" in _lc:



        return ("venue_db.team_match.home", "Home team token resolved to a different league than requested and was blocked.")



    if "league_mismatch_away_team_venue_db" in _lc:



        return ("venue_db.team_match.away", "Away team token resolved to a different league than requested and was blocked.")



    if "ambiguous_home_team_venue_db" in _lc:



        return ("venue_db.team_match.home", "Home team match was ambiguous and blocked.")



    if "ambiguous_away_team_venue_db" in _lc:



        return ("venue_db.team_match.away", "Away team match was ambiguous and blocked.")



    if "fuzzy_home_team_match" in _lc:



        return ("venue_db.team_match.home", "Home team required fuzzy fallback matching instead of canonical-ID resolution.")



    if "fuzzy_away_team_match" in _lc:



        return ("venue_db.team_match.away", "Away team required fuzzy fallback matching instead of canonical-ID resolution.")



    if "collision" in _lc:



        return ("venue_db.team_match", "Home and away canonical team keys collided.")



    if "stale_source_dates" in _lc:



        return ("odds_source.Time", "Odds source appears stale (max game date behind current run date).")



    if "future_only_source_dates" in _lc:



        return ("odds_source.Time", "Source only contained future dates for this run window.")



    if "projection_quality_too_low" in _lc:



        return ("context_engine.projection", "Projected context quality score was below minimum threshold.")



    if "dynamic_baseline_unavailable" in _lc:



        return ("context_engine.baseline", "Team-form and stats/SOS baseline inputs were insufficient, so dynamic baseline was unavailable.")



    if "dynamic_baseline_fallback" in _lc:



        return ("context_engine.baseline", "Projection baseline fell back to sport defaults because some dynamic inputs were missing.")



    if "dynamic_baseline_partial" in _lc:



        return ("context_engine.baseline", "Projection baseline used a partial dynamic source (team_form-only or stats_sos-only).")



    if "stats_sos_coverage_below_min" in _lc:



        return ("stats_sos_integration.coverage", "Stats/SOS coverage was below the minimum required for pick emission.")



    if "low_stats_sos_coverage" in _lc:



        return ("stats_sos_integration.coverage", "Stats/SOS coverage is below the warning threshold.")



    if "single_feature_dominance" in _lc:



        return ("context_engine.weights", "One feature family dominated the context engine, so the pick was blocked.")



    if "single_feature_dominance_watch" in _lc:



        return ("context_engine.weights", "One feature family is near the dominance limit.")



    if "feature_dominance_check_failed" in _lc:



        return ("context_engine.weights", "Feature-dominance safety check failed to execute.")



    if _lc.startswith("child_source_required_"):



        return ("child_output_mapping", "A required child output for this game was missing, failed, stale, unmatched, ambiguous, or below required coverage.")



    if _lc.startswith("child_source_missing_map_"):



        return ("child_output_mapping", "A required child source was not represented in the per-game source map.")



    if _lc.startswith("child_source_partial_"):



        return ("child_output_mapping", "A child output was present but partial/not posted; it is recorded for review.")



    if "game_already_started_at_run_time" in _lc:



        return ("run_time_gate", "Game start time was before/at run time, so pick emission was skipped.")



    if "unparseable_game_start" in _lc:



        return ("odds_source.Time", "Game start time could not be parsed, so pick emission was blocked.")



    if "non_today_game_date" in _lc:



        return ("odds_source.Time", "Game date was not today's run date, so pick emission was blocked.")



    if "slate_source_row_date_not_today" in _lc:



        return ("today_slate_loader", "Slate row was loaded for display/reporting but its parsed game date was not today.")



    if "slate_source_time_unparseable" in _lc:



        return ("today_slate_loader", "Slate row has a time value that could not be parsed.")



    if "no_ready_frames_loaded" in _lc:



        return ("odds_source_loader", "No eligible source frame was loaded for READY leagues.")



    if "no_eligible_ready_league_data" in _lc:



        return ("pipeline_gate", "No READY league data made it through validation to pick generation.")



    if "duplicate_source_row_skipped" in _lc:



        return ("odds_source_loader.dedup", "Duplicate source row (same sport/date/matchup/market key) was skipped to preserve idempotent ingestion.")



    return ("pipeline", "See issue code for exact missing-data/integrity condition.")











def _child_source_entry(



    child,



    artifact="",



    location="",



    status="UNKNOWN",



    team_side="",



    detail="",



    rows=None,



    contract_required=None,



    contract_missing=None,



    contract_invalid=None,



):



    return {



        "child": str(child or "").strip(),



        "artifact": str(artifact or "").strip(),



        "location": str(location or "").strip(),



        "status": str(status or "UNKNOWN").upper().strip(),



        "team_side": str(team_side or "").strip(),



        "detail": str(detail or "").strip(),



        "rows": rows,



        "contract_required": list(contract_required or []),



        "contract_missing": list(contract_missing or []),



        "contract_invalid": list(contract_invalid or []),



    }











def _path_status_for_report(path, *, today_only=False, required=False):



    try:



        p = Path(str(path or ""))



    except GUI_ERRORS:



        return "MISSING" if required else "NOT_CONFIGURED", "path unavailable"



    if not str(path or "").strip():



        return "MISSING" if required else "NOT_CONFIGURED", "path unavailable"



    if not p.exists():



        return "MISSING" if required else "NOT_FOUND", str(p)



    if today_only:



        try:



            if datetime.fromtimestamp(p.stat().st_mtime).date() != datetime.now().date():



                return "STALE", str(p)



        except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as exc:



            return "CHECK_FAILED", f"{p}: {exc}"



    return "READY", str(p)











CHILD_STATUS_BLOCKING = frozenset({

    "MISSING", "FAILED", "SOURCE_NO_DATA", "SOURCE_FAILED", "SOURCE_BLOCKED",

    "UNMATCHED", "UNMATCHED_TEAM", "AMBIGUOUS", "AMBIGUOUS_TEAM",

    "LOW_COVERAGE", "CHECK_FAILED", "STALE", "BLOCKED", "RESOLVER_MISS",

})

CHILD_STATUS_WARNING = frozenset({

    "PARTIAL", "NOT_POSTED_OR_UNAVAILABLE", "NOT_FOUND",

    "CONFIRMED_NO_INJURIES_PARTIAL_SOURCE",

})

CHILD_STATUS_OK = frozenset({

    "READY", "CONFIRMED_NO_INJURIES", "HAS_INJURIES", "HAS_NEWS",

    "SOURCE_OK_WITH_ROWS", "SOURCE_OK", "NEUTRAL", "CONFIRMED",

    "NOT_POSTED_OR_UNAVAILABLE", "NOT_FOUND", "CONFIRMED_NO_INJURIES_PARTIAL_SOURCE",

})





def _child_get(d: dict, *keys, default=""):

    for k in keys:

        try:

            v = (d or {}).get(k)

        except (AttributeError, TypeError, ValueError):

            v = None

        if v is not None and str(v).strip() != "":

            return v

    return default





def _contract_probe(values: dict, required_fields=None, numeric_fields=None):



    """



    Presence/type probe only.



    Does not enforce plausibility ranges so weird-but-real source data remains valid.



    """



    vals = dict(values or {})



    required_fields = list(required_fields or [])



    numeric_fields = list(numeric_fields or [])



    missing = []



    invalid = []



    for key in required_fields:



        v = vals.get(key, None)



        if v is None:



            missing.append(str(key))



            continue



        if isinstance(v, str) and not v.strip():



            missing.append(str(key))



    for key in numeric_fields:



        if key in missing:



            continue



        v = vals.get(key, None)



        if _to_float_or_none(v) is None:



            invalid.append(str(key))



    return {"missing": missing, "invalid": invalid}











def _game_child_source_map(



    league,



    away_clean,



    home_clean,



    source_row_file="",



    raw_time="",



    raw_market_total="",



    home_match=None,



    away_match=None,



    espn_venue=None,



    weather=None,



    travel_rest=None,



    inj_data=None,



    mlb_ctx=None,



    stats_sos_signal=None,



    ref_result=None,



    lineup_result=None,



    cre_result=None,



):



    """Explain how each child output was married to this game."""



    league = str(league or "").upper().strip()



    out = []



    _odds_missing = []



    if not away_clean:



        _odds_missing.append("away_team")



    if not home_clean:



        _odds_missing.append("home_team")



    if not str(raw_time or "").strip():



        _odds_missing.append("time")



    if _parse_market_total(raw_market_total) is None:



        _odds_missing.append("market_total")



    _odds_contract_required = ["away_team", "home_team", "time", "market_total"]



    _odds_contract = _contract_probe(



        {



            "away_team": away_clean,



            "home_team": home_clean,



            "time": raw_time,



            "market_total": _parse_market_total(raw_market_total),



        },



        required_fields=_odds_contract_required,



        numeric_fields=["market_total"],



    )



    _odds_status = "READY" if not _odds_missing else ("PARTIAL" if len(_odds_missing) < 4 else "MISSING")



    out.append(_child_source_entry(



        "odds_scraper",



        source_row_file or "in_memory_grid",



        "odds row",



        _odds_status,



        detail=(



            f"{away_clean or 'missing away'} @ {home_clean or 'missing home'}; "



            f"missing={','.join(_odds_missing) if _odds_missing else 'none'}"



        ),



        contract_required=_odds_contract_required,



        contract_missing=_odds_contract.get("missing", []),



        contract_invalid=_odds_contract.get("invalid", []),



    ))







    for side, team_name, match in (



        ("away", away_clean, dict(away_match or {})),



        ("home", home_clean, dict(home_match or {})),



    ):



        _mid = str(match.get("team_id", "") or "").strip()



        _mth = str(match.get("method", "unknown") or "unknown")



        _venue_contract_required = ["resolved_team", "team_id", "method"]



        _venue_contract = _contract_probe(



            {



                "resolved_team": str(match.get("team") or ""),



                "team_id": _mid,



                "method": _mth,



            },



            required_fields=_venue_contract_required,



            numeric_fields=[],



        )



        if match.get("team") and not match.get("ambiguous"):



            st = "READY"



            detail = (



                f"matched {team_name} -> {match.get('team')} via {_mth} "



                f"score={match.get('score', '')} id={_mid or 'n/a'}"



            )



        elif match.get("ambiguous"):



            st = "AMBIGUOUS"



            detail = f"ambiguous venue/team match for {team_name} via {_mth}"



        else:



            st = "UNMATCHED"



            detail = f"no venue/team match for {team_name} via {_mth}"



        out.append(_child_source_entry(



            "venue_registry",



            "venue database",



            f"{side}.team_key",



            st,



            side,



            detail,



            contract_required=_venue_contract_required,



            contract_missing=_venue_contract.get("missing", []),



            contract_invalid=_venue_contract.get("invalid", []),



        ))







    if isinstance(espn_venue, dict) and espn_venue:



        out.append(_child_source_entry(



            "espn_scoreboard",



            "ESPN scoreboard",



            "game venue override",



            "READY",



            detail=str(espn_venue.get("venue_name") or espn_venue.get("name") or "venue resolved"),



        ))



    else:



        out.append(_child_source_entry(



            "espn_scoreboard",



            "ESPN scoreboard",



            "game venue override",



            "NEUTRAL",



            detail="no live venue override; using matched home venue when available",



        ))







    _wx_contract_required = ["temp", "humidity", "pressure", "wind_speed", "wind_dir"]



    _wx_contract = _contract_probe(



        dict(weather or {}) if isinstance(weather, dict) else {},



        required_fields=_wx_contract_required,



        numeric_fields=["temp", "humidity", "pressure", "wind_speed"],



    )



    if isinstance(weather, dict) and all(_to_float_or_none(weather.get(k)) is not None for k in ("temp", "humidity", "pressure")):



        out.append(_child_source_entry(



            "weather_feed",



            "gametime weather",



            "temp/humidity/pressure/wind",



            "READY",



            detail="required weather fields present",



            contract_required=_wx_contract_required,



            contract_missing=_wx_contract.get("missing", []),



            contract_invalid=_wx_contract.get("invalid", []),



        ))



    else:



        out.append(_child_source_entry(



            "weather_feed",



            "gametime weather",



            "temp/humidity/pressure/wind",



            "MISSING",



            detail="weather missing or incomplete",



            contract_required=_wx_contract_required,



            contract_missing=_wx_contract.get("missing", []),



            contract_invalid=_wx_contract.get("invalid", []),



        ))







    tr = dict(travel_rest or {}) if isinstance(travel_rest, dict) else {}



    _tr_required = [



        "away_rest_days",



        "home_rest_days",



        "away_games_last_5d",



        "home_games_last_5d",



        "away_travel_miles",



        "home_travel_miles",



    ]



    _tr_contract = _contract_probe(



        tr,



        required_fields=_tr_required,



        numeric_fields=_tr_required,



    )



    if tr.get("available") is False and tr.get("error"):



        tr_status = "FAILED"



    elif all(



        _to_float_or_none(_child_get(tr, k, k.replace("_", ""), default=None)) is not None



        for k in (



            "away_rest_days",



            "home_rest_days",



            "away_games_last_5d",



            "home_games_last_5d",



            "away_travel_miles",



            "home_travel_miles",



        )



    ):



        tr_status = "READY"



    elif tr:



        tr_status = "PARTIAL"



    else:



        tr_status = "MISSING"



    out.append(_child_source_entry(



        "travel_rest_scraper",



        str(SCRIPT_DIR / "stats_output"),



        "per-team travel/rest",



        tr_status,



        detail=str(tr.get("error") or "travel/rest keys merged into team context"),



        contract_required=_tr_required,



        contract_missing=_tr_contract.get("missing", []),



        contract_invalid=_tr_contract.get("invalid", []),



    ))







    inj = dict(inj_data or {}) if isinstance(inj_data, dict) else {}



    inj_file = inj.get("source_file") or str(_injury_news_file_path(league))



    inj_flags = {str(x).strip().lower() for x in list(inj.get("match_issues", []) or [])}



    _inj_status_map = {"SOURCE_OK_WITH_ROWS": "HAS_INJURIES", "SOURCE_OK": "HAS_NEWS"}



    for side, team_name in (("away", away_clean), ("home", home_clean)):



        state = str(_child_get(inj, f"{side}_validity", f"{side}validity", f"validity_{side}", default=inj.get("status", "") or "UNKNOWN")).upper().strip()



        state = _inj_status_map.get(state, state)



        reason = str(_child_get(inj, f"{side}_reason", f"{side}reason", f"reason_{side}", default=inj.get("status", "") or "")).strip()



        if f"ambiguous_{side}_injury_news_team" in inj_flags and state in {"UNMATCHED_TEAM", "UNKNOWN"}:



            state = "AMBIGUOUS_TEAM"



        if f"injury_news_{side}_side_filter_fallback" in inj_flags:



            reason = (reason + "; side filter fallback used").strip("; ")



        _inj_contract_required = [f"{side}_validity", f"{side}_reason"]



        _inj_contract = _contract_probe(



            {



                f"{side}_validity": state,



                f"{side}_reason": reason,



            },



            required_fields=_inj_contract_required,



            numeric_fields=[],



        )



        out.append(_child_source_entry(



            "injury_news_gameday_builder",



            inj_file,



            f"VALIDITY.{side}",



            state or "UNKNOWN",



            side,



            reason or f"{team_name}: injury/news validity unavailable",



            contract_required=_inj_contract_required,



            contract_missing=_inj_contract.get("missing", []),



            contract_invalid=_inj_contract.get("invalid", []),



        ))







    ss = dict(stats_sos_signal or {}) if isinstance(stats_sos_signal, dict) else {}



    cov = _to_float_or_none(_child_get(ss, "coverage", "sos_coverage", default=None))



    _ss_required = ["coverage", "score"]



    _ss_contract = _contract_probe(



        ss,



        required_fields=_ss_required,



        numeric_fields=_ss_required,



    )



    ss_status = "READY" if cov is not None and cov >= float(_SPORT_MIN_STATS_SOS_COVERAGE.get(league, 0.20)) else "LOW_COVERAGE"



    out.append(_child_source_entry(



        "stats_sos_integration",



        str(SCRIPT_DIR / "stats_output"),



        "team stats + SOS signal",



        ss_status,



        detail=f"coverage={cov if cov is not None else 'missing'} score={_child_get(ss, 'score', 'sos_score', default='')}",



        contract_required=_ss_required,



        contract_missing=_ss_contract.get("missing", []),



        contract_invalid=_ss_contract.get("invalid", []),



    ))







    if league == "MLB":



        mlb = dict(mlb_ctx or {}) if isinstance(mlb_ctx, dict) else {}



        _mlb_required = ["available", "summary"]



        _mlb_contract = _contract_probe(



            {"available": _child_get(mlb, "available", "is_available", default=None), "summary": _child_get(mlb, "summary", "context_summary", default="")},



            required_fields=_mlb_required,



            numeric_fields=[],



        )



        out.append(_child_source_entry(



            "mlb_stats_daily",



            str(MLB_PREGAME_DB_PATH),



            "pregame_matchups/team_stats/starter_stats",



            "READY" if _child_get(mlb, "available", "is_available", default=False) else "MISSING",



            detail=str(_child_get(mlb, "summary", "context_summary", default="MLB pregame context unavailable")),



            contract_required=_mlb_required,



            contract_missing=_mlb_contract.get("missing", []),



            contract_invalid=_mlb_contract.get("invalid", []),



        ))







    rr = dict(ref_result or {}) if isinstance(ref_result, dict) else {}



    out.append(_child_source_entry(



        "referees_daily_unified",



        "officials assignment/signal",



        "officials/umpire signal",



        "READY" if (_child_get(rr, "ref_names", "refnames", default=None) or _child_get(rr, "ump_name", "umpname", default=None)) else "NEUTRAL",



        detail=str(rr.get("detail") or "officials neutral/unavailable"),



    ))







    if lineup_result:



        try:



            away_la = _child_get(lineup_result if isinstance(lineup_result, dict) else {}, "away_la", "awayla", "away_lineup", default=None)



            home_la = _child_get(lineup_result if isinstance(lineup_result, dict) else {}, "home_la", "homela", "home_lineup", default=None)



            for side, la in (("away", away_la), ("home", home_la)):



                status = str(getattr(la, "lineup_status", "") or "UNKNOWN").upper()



                found = getattr(la, "found_count", "")



                expected = getattr(la, "expected_count", "")



                _ln_required = ["lineup_status", "found_count", "expected_count"]



                _ln_contract = _contract_probe(



                    {



                        "lineup_status": status,



                        "found_count": found,



                        "expected_count": expected,



                    },



                    required_fields=_ln_required,



                    numeric_fields=["found_count", "expected_count"],



                )



                out.append(_child_source_entry(



                    "nea_lineup_assessor",



                    "lineup feed/player stats cache",



                    f"{side}.lineup",



                    status,



                    side,



                    f"matched_stats={found}/{expected}",



                    contract_required=_ln_required,



                    contract_missing=_ln_contract.get("missing", []),



                    contract_invalid=_ln_contract.get("invalid", []),



                ))



        except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as exc:



            out.append(_child_source_entry(



                "nea_lineup_assessor",



                "lineup feed/player stats cache",



                "lineup",



                "CHECK_FAILED",



                detail=str(exc),



                contract_required=["lineup_status", "found_count", "expected_count"],



                contract_missing=["lineup_status", "found_count", "expected_count"],



                contract_invalid=[],



            ))



    else:



        out.append(_child_source_entry(



            "nea_lineup_assessor",



            "lineup feed/player stats cache",



            "lineup",



            "NOT_POSTED_OR_UNAVAILABLE",



            detail="lineup result not available",



            contract_required=["lineup_status", "found_count", "expected_count"],



            contract_missing=["lineup_status", "found_count", "expected_count"],



            contract_invalid=[],



        ))







    cr = dict(cre_result or {}) if isinstance(cre_result, dict) else {}



    out.append(_child_source_entry(



        "cre_integration",



        "circadian/travel context",



        "CRE overlay",



        "READY" if cr else "NEUTRAL",



        detail=str(_child_get(cr, "notes", "cre_notes", "cre_ou_lean", "creoulean", default="no CRE adjustment")),



    ))



    return out











def _write_missing_data_report(records, report_name="todays_picks"):



    """Write per-game missing-data integrity breakdown (JSON + CSV + TXT)."""



    records = list(records or [])



    out_dir = SCRIPT_DIR / "diagnostics"



    out_dir.mkdir(parents=True, exist_ok=True)



    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")



    base = f"{report_name}_missing_data_{stamp}"



    json_path = out_dir / f"{base}.json"



    csv_path = out_dir / f"{base}.csv"



    txt_path = out_dir / f"{base}.txt"



    tmp_json = json_path.with_suffix(".json.tmp")



    tmp_csv = csv_path.with_suffix(".csv.tmp")



    tmp_txt = txt_path.with_suffix(".txt.tmp")







    flat_rows = []







    def _clean_txt(v):



        try:



            return _clean_display_text(v).strip()



        except GUI_ERRORS:



            return str(v or "").strip()







    def _game_key_for(sport, game_date, game_time, away, home):



        _s = _clean_txt(sport) or "UNK"



        _d = _clean_txt(game_date) or "UNK_DATE"



        _t = _clean_txt(game_time) or "UNK_TIME"



        _a = _clean_txt(away) or "UNK_AWAY"



        _h = _clean_txt(home) or "UNK_HOME"



        return f"{_s}|{_d}|{_t}|{_a}@{_h}"







    for rec in records:



        sport = _clean_txt(rec.get("sport", "") or "")



        game_date = _clean_txt(rec.get("game_date", "") or "")



        game_time = _clean_txt(rec.get("time", "") or rec.get("game_time", "") or "")



        away = _clean_txt(rec.get("away", "") or "")



        home = _clean_txt(rec.get("home", "") or "")



        status = _clean_txt(rec.get("status", "") or "")



        source = _clean_txt(rec.get("source", "") or "")



        run_ts = _clean_txt(rec.get("run_timestamp", "") or datetime.now().astimezone().isoformat())



        start_et = _clean_txt(rec.get("start_et", "") or "")



        if not start_et and game_time:



            try:



                _start_dt = _game_start_et(game_time)



                if _start_dt is not None:



                    start_et = _start_dt.isoformat()



            except GUI_ERRORS:



                start_et = ""



        _pc = dict(rec.get("parse_context") or {}) if isinstance(rec, dict) else {}



        _pc_stage = _clean_txt(_pc.get("stage", "") or "")



        _pc_row_idx = _clean_txt(_pc.get("source_row_index", "") or "")



        _pc_raw_away = _clean_txt(_pc.get("raw_away", "") or "")



        _pc_raw_home = _clean_txt(_pc.get("raw_home", "") or "")



        _pc_raw_time = _clean_txt(_pc.get("raw_time", "") or "")



        _pc_raw_total = _clean_txt(_pc.get("raw_total", "") or "")



        _pc_can_away = _clean_txt(_pc.get("canonical_away", "") or "")



        _pc_can_home = _clean_txt(_pc.get("canonical_home", "") or "")



        _pc_notes = _clean_txt(_pc.get("notes", "") or "")



        _tm_common = {



            "team_match_home_method": _clean_txt(rec.get("team_match_home_method", "") or ""),



            "team_match_away_method": _clean_txt(rec.get("team_match_away_method", "") or ""),



            "team_match_home_id": _clean_txt(rec.get("team_match_home_id", "") or ""),



            "team_match_away_id": _clean_txt(rec.get("team_match_away_id", "") or ""),



            "team_match_home_score": _to_float_or_none(rec.get("team_match_home_score")),



            "team_match_away_score": _to_float_or_none(rec.get("team_match_away_score")),



        }



        game_key = _game_key_for(sport, game_date, game_time, away, home)







        _had_row = False



        for sev, bucket in (("ISSUE", rec.get("issues", [])), ("WARNING", rec.get("warnings", [])), ("MATCH_ISSUE", rec.get("match_issues", []))):



            for code in list(bucket or []):



                where, why = _issue_where_why(code)



                flat_rows.append({



                    "game_key": game_key,



                    "run_timestamp": run_ts,



                    "when_detected": run_ts,



                    "game_start_et": start_et,



                    "status": status,



                    "severity": sev,



                    "sport": sport,



                    "game_date": game_date,



                    "game_time": game_time,



                    "away_team": away,



                    "home_team": home,



                    "issue_code": str(code),



                    "what": str(code),



                    "where": where,



                    "why": why,



                    "source": source,



                    "source_child": "",



                    "source_artifact": "",



                    "source_location": "",



                    "source_status": "",



                    "team_side": "",



                    "source_detail": "",



                    "source_contract_required": "",



                    "source_contract_missing": "",



                    "source_contract_invalid": "",



                    **_tm_common,



                    "parse_stage": _pc_stage,



                    "source_row_index": _pc_row_idx,



                    "raw_away_team": _pc_raw_away,



                    "raw_home_team": _pc_raw_home,



                    "raw_time": _pc_raw_time,



                    "raw_total": _pc_raw_total,



                    "canonical_away": _pc_can_away,



                    "canonical_home": _pc_can_home,



                    "parse_notes": _pc_notes,



                })



                _had_row = True



        for sm in list(rec.get("child_source_map", []) or []):



            if not isinstance(sm, dict):



                continue



            sm_status = _clean_txt(sm.get("status", "") or "UNKNOWN").upper()



            sm_child = _clean_txt(sm.get("child", "") or "")



            sm_artifact = _clean_txt(sm.get("artifact", "") or "")



            sm_location = _clean_txt(sm.get("location", "") or "")



            sm_side = _clean_txt(sm.get("team_side", "") or "")



            sm_detail = _clean_txt(sm.get("detail", "") or "")



            sm_contract_req = ",".join([_clean_txt(x) for x in list(sm.get("contract_required", []) or []) if _clean_txt(x)])



            sm_contract_missing = ",".join([_clean_txt(x) for x in list(sm.get("contract_missing", []) or []) if _clean_txt(x)])



            sm_contract_invalid = ",".join([_clean_txt(x) for x in list(sm.get("contract_invalid", []) or []) if _clean_txt(x)])



            sm_norm = sm_status



            if sm_norm.startswith("READ_ERROR"):



                sm_norm = "FAILED"



            elif sm_norm in {"NO_FILE", "NO_STRUCTURED_SHEETS"}:



                sm_norm = "MISSING"



            _ok_statuses = {



                "READY", "NEUTRAL", "CONFIRMED_NO_INJURIES", "HAS_INJURIES",



                "HAS_NEWS", "CONFIRMED", "SOURCE_OK_WITH_ROWS",



            }



            _warn_statuses = {



                "EXPECTED", "PROJECTED", "NOT_POSTED", "UNKNOWN",



                "PARTIAL", "LOW_COVERAGE", "NOT_POSTED_OR_UNAVAILABLE",



                "CONFIRMED_NO_INJURIES_PARTIAL_SOURCE", "NOT_FOUND",



            }



            if sm_norm in _ok_statuses:



                sm_sev = "SOURCE_OK"



            elif sm_norm in _warn_statuses:



                sm_sev = "SOURCE_WARNING"



            else:



                sm_sev = "SOURCE_ISSUE"



            flat_rows.append({



                "game_key": game_key,



                "run_timestamp": run_ts,



                "when_detected": run_ts,



                "game_start_et": start_et,



                "status": status,



                "severity": sm_sev,



                "sport": sport,



                "game_date": game_date,



                "game_time": game_time,



                "away_team": away,



                "home_team": home,



                "issue_code": f"source_status:{sm_child}:{sm_status}",



                "what": f"{sm_child} => {sm_status}",



                "where": sm_location or sm_child,



                "why": sm_detail or "child source status recorded for this game",



                "source": sm_artifact or source,



                "source_child": sm_child,



                "source_artifact": sm_artifact,



                "source_location": sm_location,



                "source_status": sm_status,



                "team_side": sm_side,



                "source_detail": sm_detail,



                "source_contract_required": sm_contract_req,



                "source_contract_missing": sm_contract_missing,



                "source_contract_invalid": sm_contract_invalid,



                **_tm_common,



                "parse_stage": _pc_stage,



                "source_row_index": _pc_row_idx,



                "raw_away_team": _pc_raw_away,



                "raw_home_team": _pc_raw_home,



                "raw_time": _pc_raw_time,



                "raw_total": _pc_raw_total,



                "canonical_away": _pc_can_away,



                "canonical_home": _pc_can_home,



                "parse_notes": _pc_notes,



            })



            _had_row = True



        if not _had_row:



            flat_rows.append({



                "game_key": game_key,



                "run_timestamp": run_ts,



                "when_detected": run_ts,



                "game_start_et": start_et,



                "status": status or "READY_CLEAN",



                "severity": "INFO",



                "sport": sport,



                "game_date": game_date,



                "game_time": game_time,



                "away_team": away,



                "home_team": home,



                "issue_code": "NO_MISSING_FIELDS",



                "what": "NO_MISSING_FIELDS",



                "where": "integrity_gate",



                "why": "No missing-data or integrity issues were detected for this entry.",



                "source": source,



                "source_child": "",



                "source_artifact": "",



                "source_location": "",



                "source_status": "",



                "team_side": "",



                "source_detail": "",



                "source_contract_required": "",



                "source_contract_missing": "",



                "source_contract_invalid": "",



                **_tm_common,



                "parse_stage": _pc_stage,



                "source_row_index": _pc_row_idx,



                "raw_away_team": _pc_raw_away,



                "raw_home_team": _pc_raw_home,



                "raw_time": _pc_raw_time,



                "raw_total": _pc_raw_total,



                "canonical_away": _pc_can_away,



                "canonical_home": _pc_can_home,



                "parse_notes": _pc_notes,



            })







    payload = {



        "generated_at": datetime.now().astimezone().isoformat(),



        "report_name": report_name,



        "games": records,



        "issue_rows": flat_rows,



        "summary": {



            "games_with_records": len(records),



            "issue_rows": len(flat_rows),



            "games_with_issues": sum(1 for r in records if list(r.get("issues", []) or [])),



            "games_with_warnings": sum(1 for r in records if list(r.get("warnings", []) or [])),



            "games_with_match_issues": sum(1 for r in records if list(r.get("match_issues", []) or [])),



        },



    }







    _lock = globals().get("_MISSING_DATA_FILE_LOCK")



    if _lock is None:



        _lock = threading.Lock()



        globals()["_MISSING_DATA_FILE_LOCK"] = _lock



    with _lock:



        try:



            with open(tmp_json, "w", encoding="utf-8") as f:



                json.dump(payload, f, indent=2)



            os.replace(str(tmp_json), str(json_path))



        finally:



            try:



                if tmp_json.exists():



                    tmp_json.unlink()



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

        try:



            import csv as _csv



            _fields = [



                "game_key", "run_timestamp", "when_detected", "game_start_et",



                "status", "severity", "sport", "game_date", "game_time",



                "away_team", "home_team", "issue_code", "what", "where", "why", "source",



                "source_child", "source_artifact", "source_location", "source_status",



                "team_side", "source_detail",



                "source_contract_required", "source_contract_missing", "source_contract_invalid",



                "team_match_home_method", "team_match_away_method",



                "team_match_home_id", "team_match_away_id",



                "team_match_home_score", "team_match_away_score",



                "parse_stage", "source_row_index", "raw_away_team", "raw_home_team",



                "raw_time", "raw_total", "canonical_away", "canonical_home", "parse_notes",



            ]



            with open(tmp_csv, "w", newline="", encoding="utf-8") as f:



                _w = _csv.DictWriter(f, fieldnames=_fields)



                _w.writeheader()



                for row in flat_rows:



                    _w.writerow(row)



            os.replace(str(tmp_csv), str(csv_path))



        finally:



            try:



                if tmp_csv.exists():



                    tmp_csv.unlink()



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

        try:



            _by_game = {}



            for row in flat_rows:



                _gk = _clean_txt(row.get("game_key"))



                _by_game.setdefault(_gk, []).append(row)



            with open(tmp_txt, "w", encoding="utf-8") as f:



                f.write(f"MISSING DATA REPORT :: {report_name}\n")



                f.write(f"Generated: {payload.get('generated_at')}\n")



                f.write(f"Games/entries: {len(records)}\n")



                f.write(f"Issue rows: {len(flat_rows)}\n")



                f.write("=" * 100 + "\n\n")



                for gk in sorted(_by_game.keys()):



                    rows = _by_game.get(gk, [])



                    if not rows:



                        continue



                    head = rows[0]



                    f.write(f"GAME_KEY: {gk}\n")



                    f.write(f"Sport: {head.get('sport','')}  Date: {head.get('game_date','')}  Time: {head.get('game_time','')}\n")



                    f.write(f"Matchup: {head.get('away_team','')} @ {head.get('home_team','')}\n")



                    f.write(f"Start(ET): {head.get('game_start_et','') or 'unknown'}\n")



                    f.write(f"Source: {head.get('source','') or 'unknown'}\n")



                    if any(str(head.get(k, "")).strip() for k in ("parse_stage", "source_row_index", "raw_away_team", "raw_home_team", "raw_time", "raw_total", "canonical_away", "canonical_home")):



                        f.write(



                            f"Parse: stage={head.get('parse_stage','') or 'n/a'} row={head.get('source_row_index','') or 'n/a'} "



                            f"raw=({head.get('raw_away_team','')} @ {head.get('raw_home_team','')}; time={head.get('raw_time','')}; total={head.get('raw_total','')}) "



                            f"canon=({head.get('canonical_away','')} @ {head.get('canonical_home','')})\n"



                        )



                    f.write(f"Detected at: {head.get('when_detected','')}\n")



                    f.write("-" * 100 + "\n")



                    for idx, row in enumerate(rows, start=1):



                        if str(row.get("severity", "")).startswith("SOURCE_"):



                            f.write(



                                f"{idx}. [{row.get('severity','')}] child={row.get('source_child','')} "



                                f"status={row.get('source_status','')} side={row.get('team_side','') or 'game'} "



                                f"artifact={row.get('source_artifact','') or row.get('source','')} "



                                f"where={row.get('source_location','') or row.get('where','')} "



                                f"detail={row.get('source_detail','') or row.get('why','')} "



                                f"contract_required=[{row.get('source_contract_required','')}] "



                                f"contract_missing=[{row.get('source_contract_missing','')}] "



                                f"contract_invalid=[{row.get('source_contract_invalid','')}]\n"



                            )



                        else:



                            f.write(



                                f"{idx}. [{row.get('severity','')}] status={row.get('status','')} "



                                f"what={row.get('what','')} where={row.get('where','')} why={row.get('why','')}\n"



                            )



                    f.write("\n")



            os.replace(str(tmp_txt), str(txt_path))



        finally:



            try:



                if tmp_txt.exists():



                    tmp_txt.unlink()



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

    latest_json = out_dir / f"{report_name}_missing_data_latest.json"



    latest_csv = out_dir / f"{report_name}_missing_data_latest.csv"



    latest_txt = out_dir / f"{report_name}_missing_data_latest.txt"



    for _src, _dst in ((json_path, latest_json), (csv_path, latest_csv), (txt_path, latest_txt)):



        _tmp_latest = _dst.with_suffix(_dst.suffix + ".tmp")



        try:



            with open(_src, "rb") as _in, open(_tmp_latest, "wb") as _out:



                _out.write(_in.read())



            os.replace(str(_tmp_latest), str(_dst))



        finally:



            try:



                if _tmp_latest.exists():



                    _tmp_latest.unlink()



            except GUI_ERRORS as _e:



                _warn_exception("silent_except", _e)

    return {



        "json": str(json_path),



        "csv": str(csv_path),



        "txt": str(txt_path),



        "latest_json": str(latest_json),



        "latest_csv": str(latest_csv),



        "latest_txt": str(latest_txt),



        "rows": len(flat_rows),



    }











def _rpt_build_game_block(row, sport=None) -> dict:



    """Return a dict with every computed field for one game row.



    Uses the same physics functions as the popup ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â no duplication of logic."""



    league = str(



        sport



        or row.get("League", "")



        or row.get("Sport", "")



        or row.get("_sport_hint", "")



        or rpt_league_var.get()



    ).upper().strip()



    away_raw  = str(row.get("Away_Team","") or "")



    home_raw  = str(row.get("Home_Team","") or "")



    away_clean = _strip_pitcher(away_raw)



    home_clean = _strip_pitcher(home_raw)



    game_time  = str(row.get("Time","") or "")



    _market_total_raw = row.get("Total", "") or row.get("OU_Line", "") or row.get("ou_line", "")



    _market_over_odds = None



    _market_under_odds = None



    for _k in (



        "Over_Odds", "over_odds", "Total_Over_Odds", "total_over_odds",



        "OU_Over_Odds", "ou_over_odds", "O_U_Over_Odds",



    ):



        _v = _parse_american_odds(row.get(_k))



        if _v is not None:



            _market_over_odds = _v



            break



    for _k in (



        "Under_Odds", "under_odds", "Total_Under_Odds", "total_under_odds",



        "OU_Under_Odds", "ou_under_odds", "O_U_Under_Odds",



    ):



        _v = _parse_american_odds(row.get(_k))



        if _v is not None:



            _market_under_odds = _v



            break







    # Venue lookup (deterministic team-key matching)



    _home_match = _safe_resolve_team_match(home_clean, df, preferred_league=league)



    _away_match = _safe_resolve_team_match(away_clean, df, preferred_league=league)



    home_db = _home_match.get("team")



    away_db = _away_match.get("team")



    if home_db and league and not _same_league_tag(_home_match.get("league", ""), league):



        _home_match["league_mismatch"] = True



        _home_match["league_expected"] = _normalize_league_tag(league)



        _home_match["league_found"] = _normalize_league_tag(_home_match.get("league", ""))



        _home_match["method"] = f"{_home_match.get('method','none')}_league_mismatch_blocked"



        home_db = None



    if away_db and league and not _same_league_tag(_away_match.get("league", ""), league):



        _away_match["league_mismatch"] = True



        _away_match["league_expected"] = _normalize_league_tag(league)



        _away_match["league_found"] = _normalize_league_tag(_away_match.get("league", ""))



        _away_match["method"] = f"{_away_match.get('method','none')}_league_mismatch_blocked"



        away_db = None



    _team_match_issues = []



    if not home_db:



        _team_match_issues.append("unmatched_home_team_venue_db")



    if not away_db:



        _team_match_issues.append("unmatched_away_team_venue_db")



    if _home_match.get("ambiguous"):



        _team_match_issues.append("ambiguous_home_team_venue_db")



    if _away_match.get("ambiguous"):



        _team_match_issues.append("ambiguous_away_team_venue_db")



    if bool(_home_match.get("league_mismatch")) or "league_mismatch_blocked" in str(_home_match.get("method", "") or ""):



        _team_match_issues.append("league_mismatch_home_team_venue_db")



    if bool(_away_match.get("league_mismatch")) or "league_mismatch_blocked" in str(_away_match.get("method", "") or ""):



        _team_match_issues.append("league_mismatch_away_team_venue_db")



    if str(_home_match.get("method", "") or "").startswith("token_weighted"):



        _team_match_issues.append("fuzzy_home_team_match")



    if str(_away_match.get("method", "") or "").startswith("token_weighted"):



        _team_match_issues.append("fuzzy_away_team_match")



    if home_db and away_db and _canonical_team_key(home_db, league=league) == _canonical_team_key(away_db, league=league):



        _team_match_issues.append("home_away_canonical_collision")



    _home_row = get_row(home_db, preferred_league=league) if home_db else None



    _away_row = get_row(away_db, preferred_league=league) if away_db else None



    home_venue = _home_row.to_dict() if _home_row is not None else {}



    away_venue = _away_row.to_dict() if _away_row is not None else {}







    # ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ ESPN Live Venue Override (actual venue, not team home) ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬



    _gdate_str = _explicit_game_date_str(game_time) or ""



    _espn_v = None



    if _gdate_str and league:



        try:



            _espn_v = _resolve_game_venue(league, away_clean, home_clean, _gdate_str)



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

    elif league:



        log(



            f"[DATA] report build missing parseable game date for {away_clean} @ {home_clean} ({game_time}).",



            "warning",



        )



    if _espn_v:



        if _espn_v.get("lat")       is not None: home_venue["lat"]        = _espn_v["lat"]



        if _espn_v.get("lon")       is not None: home_venue["lon"]        = _espn_v["lon"]



        if _espn_v.get("elevation") is not None: home_venue["elevation"]  = _espn_v["elevation"]



        if _espn_v.get("venue_name"):             home_venue["venue"]      = _espn_v["venue_name"]



        if _espn_v.get("indoor"):                 home_venue["roof_type"]  = "closed"



        elif _espn_v.get("neutral_site"):         home_venue["roof_type"]  = "open"







    h_elev_f  = safe_float(home_venue.get("elevation"), None, "elev") if home_venue.get("elevation") not in (None, "", "N/A") else None



    a_elev_f  = safe_float(away_venue.get("elevation"), None, "a_elev") if away_venue.get("elevation") not in (None, "", "N/A") else None



    h_orient  = home_venue.get("orientation_deg", "")



    h_roof    = str(home_venue.get("roof_type", "")).lower()



    h_lat     = safe_float(home_venue.get("lat"),  None, "lat") if home_venue.get("lat") not in (None, "", "N/A") else None



    h_lon     = safe_float(home_venue.get("lon"), None, "lon") if home_venue.get("lon") not in (None, "", "N/A") else None







    # Weather (sync fetch using gametime hint)



    wx = None



    if h_lat is not None and h_lon is not None:



        wx = get_weather_at_gametime(h_lat, h_lon, game_time)







    # Physics



    rho = da = hw = cw = None



    if wx and wx != "error" and h_elev_f is not None:



        try:



            h_elev_use = h_elev_f



            h_orient_f = safe_float(h_orient, 0.0, "orient") if (h_orient is not None and h_orient != "") else 0.0



            wind_eff   = wx["wind_speed"]



            if h_roof in ("closed","dome"):



                wind_eff = 0.0



            rho = air_density(wx["temp"], wx["pressure"], wx["humidity"])



            da  = density_altitude(wx["temp"], h_elev_use, wx["pressure"], wx["humidity"])



            hw, cw = wind_components(wind_eff, wx.get("wind_dir"), h_orient_f)

            if hw is None or cw is None:

                hw, cw = 0.0, 0.0



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

    # Elevation delta



    elev_delta = None



    if h_elev_f is not None and a_elev_f is not None:



        elev_delta = h_elev_f - a_elev_f







    # Air density % vs home baseline



    def _std_rho(h):



        import math



        m = max(0.0,h)*0.3048



        T = 288.15 - 0.0065*m



        P = 101325*(T/288.15)**5.2561



        return P*0.0289644/(8.31446*T)*0.0624279606



    rho_pct_home = rho_pct_away = None



    if rho and h_elev_f is not None:



        base_h = _std_rho(h_elev_f)



        rho_pct_home = (rho - base_h)/base_h*100 if base_h else None



    if rho and a_elev_f is not None:



        base_a = _std_rho(a_elev_f)



        rho_pct_away = (rho - base_a)/base_a*100 if base_a else None







    try:



        _circ = _circ_analysis(



            game_time, home_venue, away_venue, league,



            away_team=away_clean, home_team=home_clean,



            game_date=_gdate_str



        )



    except GUI_ERRORS:



        _circ = {"available": False}



    _travel_rest = {}



    if _TRAVEL_REST_OK and _load_travel_rest_for_game and _gdate_str:



        try:



            _travel_rest = _load_travel_rest_for_game(



                league,



                away_clean,



                home_clean,



                _gdate_str,



                str(SCRIPT_DIR / "stats_output"),



                home_venue.get("venue") or home_venue.get("venue_name") or "",



            ) or {}



        except GUI_ERRORS as _tr_err:



            log(f"[context] travel/rest lookup failed for {league} {away_clean} @ {home_clean}: {_tr_err}", "warning")



            _travel_rest = {"available": False, "error": str(_tr_err)}


    else:



        if not _TRAVEL_REST_OK:



            _travel_rest = {"available": False, "module_unavailable": True,



                            "reason": "TRAVEL/REST MODULE UNAVAILABLE - travel_rest_scraper.py not loaded."}







    def _merge_travel_rest_state(base_state, side):



        out = dict(base_state or {})



        for src_key, dst_key in [



            (f"{side}_rest_days", "days_rest"),



            (f"{side}_games_last_5d", "games_last_5d"),



            (f"{side}_travel_miles", "travel_miles_last_5d"),



        ]:



            val = _to_float_or_none((_travel_rest or {}).get(src_key))



            if val is not None:



                out[dst_key] = val



        return out



    _home_circ_state = _merge_travel_rest_state(((_circ or {}).get("home_state") or {}), "home")



    _away_circ_state = _merge_travel_rest_state(((_circ or {}).get("away_state") or {}), "away")







    # Over/under lean (air density physics)



    ou_lean = "NEUTRAL"



    _roof_for_gate = str((home_venue or {}).get("roof_type", "")).strip().lower()

    _indoor_roof = _roof_for_gate in {"closed", "dome", "dome_fixed", "retractable closed", "indoor"}

    _indoor_sport_gate = str(league or "").upper().strip() in {"NBA", "NHL"}

    if _indoor_sport_gate and (_indoor_roof or rho is None):

        # Explicit policy: indoor leagues do not derive baseline OU direction from air density/wind.

        ou_lean = "NEUTRAL"



    if (not _indoor_sport_gate) and rho and hw is not None:



        pitcher_score = 0



        if rho > 0.0765:  pitcher_score += 1



        if hw and hw < -4: pitcher_score += 1



        if pitcher_score >= 2:



            ou_lean = "UNDER"



        elif pitcher_score == 0 and (rho < 0.0755 or (hw and hw > 4)):



            ou_lean = "OVER"







