ttk.Combobox(pk_ctrl, textvariable=pk_pick_var, values=["OVER","UNDER"],



             width=10, state="readonly").grid(row=1, column=1, sticky="w", **pad)







ttk.Label(pk_ctrl, text="  O/U Line:").grid(row=1, column=2, sticky="e", **pad)



