ttk.Entry(pk_ctrl, textvariable=pk_line_var, width=8).grid(row=1, column=3, sticky="w", **pad)







ttk.Label(pk_ctrl, text="  Confidence (1-5):").grid(row=1, column=4, sticky="e", **pad)



