ttk.Label(



    pk_ctrl,



    textvariable=pk_record_strip_var,



    style="SubtleCard.TLabel",



).grid(row=4, column=0, columnspan=6, sticky="w", **pad)







def _pk_set_status(msg):



    root.after(0, lambda m=str(msg): pk_log_status.set(_clean_display_text(m)))







