def _margin_str(result, actual, line):

    try:

        m = round(float(actual) - float(line), 1)

        if result in ("WIN","LOSS","PUSH"):

            sign = "+" if m >= 0 else ""

            return f"{sign}{m}"

    except GUI_ERRORS as _margin_err:

        log(f"[pick_history] margin parse failed: {_margin_err}", "warning")

    return "--"





def _yh_load():



    _yh_tree.delete(*_yh_tree.get_children())



    try:



        con = _pk_connect()



        rows = con.execute("""SELECT game_date,game_time,league,away_team,home_team,



                               ou_line,pick,confidence,pick_result,actual_total,notes



                               FROM picks ORDER BY id DESC LIMIT 300""").fetchall()



        con.close()



    except (_sqlite3.Error, OSError, ValueError, TypeError) as _e:
        _warn_exception("picks_history_load", _e)
        return


    for r in rows:



        gdate,gtime,lg,away,home,line,pick,conf,result,actual,notes = r



        result = result or "PENDING"



        tag    = {"WIN":"win","LOSS":"loss","PUSH":"push"}.get(result,"pend")



        margin = _margin_str(result,actual,line) if result in ("WIN","LOSS","PUSH") else "--"



        try:



            line_txt = f"{float(line):.1f}" if line is not None and str(line).strip() != "" else "--"



        except (TypeError, ValueError):



            line_txt = "--"



        try:



            actual_txt = f"{float(actual):.1f}" if actual is not None and str(actual).strip() != "" else "--"



        except (TypeError, ValueError):



            actual_txt = "--"



        _yh_tree.insert("","end",tags=(tag,),values=(



            _clean_display_text(gdate or ""),



            _clean_display_text(gtime or ""),



            _clean_display_text(lg or ""),



            _clean_display_text(away or ""),



            _clean_display_text(home or ""),



            line_txt,



            _clean_display_text(pick or "--"),



            _clean_display_text(str(conf) if conf not in (None, "") else "--"),



            _clean_display_text(result),



            actual_txt,



            _clean_display_text(margin),



            _clean_display_text(notes or ""),



        ))







