def _refresh_pick_views():



    try:



        _pk_load_history()



    except (RuntimeError, tk.TclError, AttributeError) as _hist_err:

        log(f"[picks.refresh] history refresh failed: {_hist_err}", "warning")



    try:



        _all_history_load()



    except (RuntimeError, tk.TclError, AttributeError) as _all_hist_err:

        log(f"[picks.refresh] aggregate history refresh failed: {_all_hist_err}", "warning")



    try:



        _pk_update_dual_accuracy()



    except (RuntimeError, tk.TclError, AttributeError) as _acc_err:

        log(f"[picks.refresh] dual accuracy refresh failed: {_acc_err}", "warning")



    try:



        _refresh_tpk_record_summary()



    except (RuntimeError, tk.TclError, AttributeError) as _sum_err:

        log(f"[picks.refresh] summary refresh failed: {_sum_err}", "warning")



    try:



        _rpt_refresh_history_dropdown()



    except (RuntimeError, tk.TclError, AttributeError) as _rpt_err:

        log(f"[picks.refresh] report history dropdown refresh failed: {_rpt_err}", "warning")











def _on_execution_tab_changed(event=None):



    try:



        _sel = execution_nb.select()



        _tab_name = str(execution_nb.tab(_sel, "text") or "").strip()



    except (RuntimeError, tk.TclError, AttributeError, TypeError, ValueError):



        _tab_name = ""



    if _tab_name in {"My Picks", "Model Picks"}:



        _refresh_pick_views()











def _on_main_tab_changed_pick_refresh(event=None):



    try:



        _sel = main_tabs.select()



        _tab_name = str(main_tabs.tab(_sel, "text") or "").strip()



    except (RuntimeError, tk.TclError, AttributeError, TypeError, ValueError):



        _tab_name = ""



    if _tab_name == "Picks":



        _refresh_pick_views()











try:



    execution_nb.bind("<<NotebookTabChanged>>", _on_execution_tab_changed, add="+")



except (RuntimeError, tk.TclError, AttributeError) as _e:



    _warn_exception("silent_except", _e)

try:



    main_tabs.bind("<<NotebookTabChanged>>", _on_main_tab_changed_pick_refresh, add="+")



except (RuntimeError, tk.TclError, AttributeError) as _e:



    _warn_exception("silent_except", _e)

def _reset_picks(which):



    import tkinter.messagebox as _mb



    import tkinter.simpledialog as _sd



    label = "YOUR" if which == "yours" else "MODEL"



    table = "picks" if which == "yours" else "model_picks"



    if not _mb.askyesno("Reset W/L Ticker",



        f"PERMANENTLY delete ALL {label} picks->\n\n"



        f"Table: {table}\nThis cannot be undone.\n"



        f"Type of reset: {which.upper()}", icon="warning"): return



    _confirm_phrase = f"RESET {label}"



    _typed = _sd.askstring(



        "Confirm Reset",



        f"Type '{_confirm_phrase}' to continue:",



    )



    if str(_typed or "").strip().upper() != _confirm_phrase:



        _pk_set_status(f"[reset] Cancelled ({label}) - confirmation phrase mismatch.")



        return



    _rows_before = None



    try:



        try:



            _cnt_con = _pk_connect(timeout=8)



            try:



                _rows_before = int(_cnt_con.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0] or 0)



            finally:



                _cnt_con.close()



        except (_sqlite3.Error, OSError, ValueError, TypeError) as _e:

            _warn_exception("rows_before_count", _e)
            _rows_before = None


        if PICKS_DB != ":memory:" and os.path.exists(PICKS_DB):



            _ts = datetime.now().strftime("%Y%m%d_%H%M%S")



            _backup = str(Path(PICKS_DB).with_name(f"{Path(PICKS_DB).stem}.backup_{_ts}.db"))



            _src = _pk_connect(timeout=8)



            try:



                _dst = _pk_connect(_backup, timeout=8)



                try:



                    _src.backup(_dst)



                finally:



                    _dst.close()



            finally:



                _src.close()



            log(f"[reset] backup created: {_backup}", "info")



        _delete_sql = "DELETE FROM picks" if table == "picks" else "DELETE FROM model_picks"



        _pk_write_transaction(lambda _con: _con.execute(_delete_sql), retries=4)



        _cleared_txt = (



            f"{_rows_before} row(s)"



            if isinstance(_rows_before, int) and _rows_before >= 0



            else "all rows"



        )



        log(f"[reset] {label} picks cleared ({_cleared_txt}).", "info")



        _pk_set_status(f"[reset] {label} picks cleared ({_cleared_txt}).")



    except (_sqlite3.Error, OSError, ValueError, TypeError, RuntimeError) as _re:

        log(f"[reset] {_re}", "warning")

        return



    root.after(0, _pk_load_history)



    root.after(0, _all_history_load)



    root.after(0, _pk_update_dual_accuracy)



    try:



        _refresh_tpk_record_summary()



    except (RuntimeError, tk.TclError, AttributeError) as _sum_err:

        log(f"[reset] tpk summary refresh failed: {_sum_err}", "warning")



    try:



        _rpt_refresh_history_dropdown()



    except (RuntimeError, tk.TclError, AttributeError) as _rpt_err:

        log(f"[reset] report history dropdown refresh failed: {_rpt_err}", "warning")











def _clear_model_pending_picks():



    import tkinter.messagebox as _mb



    import tkinter.simpledialog as _sd



    _pending_clause = "UPPER(TRIM(COALESCE(pick_result,'PENDING')))='PENDING'"



    try:



        con = _pk_connect(timeout=8)



        try:



            _pending_count = int(con.execute(



                f"SELECT COUNT(*) FROM model_picks WHERE {_pending_clause}"



            ).fetchone()[0] or 0)



        finally:



            con.close()



    except (OSError, ValueError, TypeError) as _e:



        _pk_set_status(f"[reset] Pending-count check failed: {_e}")



        return







    if _pending_count <= 0:



        _pk_set_status("[reset] No pending model picks to clear.")



        return







    if not _mb.askyesno(



        "Clear Pending Model Picks",



        f"Delete {_pending_count} pending model pick row(s)\n\n"



        "This removes only ungraded model rows and keeps graded history.",



        icon="warning",



    ):



        return







    _confirm_phrase = "CLEAR MODEL PENDING"



    _typed = _sd.askstring(



        "Confirm Pending Clear",



        f"Type '{_confirm_phrase}' to continue:",



    )



    if str(_typed or "").strip().upper() != _confirm_phrase:



        _pk_set_status("[reset] Pending clear cancelled - confirmation phrase mismatch.")



        return







    try:



        if PICKS_DB != ":memory:" and os.path.exists(PICKS_DB):



            _ts = datetime.now().strftime("%Y%m%d_%H%M%S")



            _backup = str(Path(PICKS_DB).with_name(f"{Path(PICKS_DB).stem}.backup_{_ts}.db"))



            _src = _pk_connect(timeout=8)



            try:



                _dst = _pk_connect(_backup, timeout=8)



                try:



                    _src.backup(_dst)



                finally:



                    _dst.close()



            finally:



                _src.close()



            log(f"[reset] backup created: {_backup}", "info")







        _pk_write_transaction(



            lambda _con: _con.execute(



                f"DELETE FROM model_picks WHERE {_pending_clause}"



            ),



            retries=4,



        )



        log(f"[reset] Cleared pending model picks: {_pending_count}", "info")



        _pk_set_status(f"[reset] Cleared {_pending_count} pending model pick row(s).")



    except (OSError, ValueError, TypeError) as _e:



        log(f"[reset] pending clear failed: {_e}", "warning")



        _pk_set_status(f"[reset] Pending clear failed: {_e}")



        return







    root.after(0, _pk_load_history)



    root.after(0, _all_history_load)



    root.after(0, _pk_update_dual_accuracy)



    try:



        _refresh_tpk_record_summary()



    except (RuntimeError, tk.TclError) as _e:



        _warn_exception("silent_except", _e)

    try:



        _rpt_refresh_history_dropdown()



    except (RuntimeError, tk.TclError) as _e:



        _warn_exception("silent_except", _e)

def _clear_stale_model_pending(days=7):



    import tkinter.messagebox as _mb



    _days = max(1, int(_to_float_or_none(days) or 7))



    _pending_clause = "UPPER(TRIM(COALESCE(pick_result,'PENDING')))='PENDING'"



    _cutoff = (datetime.now().date() - timedelta(days=_days)).isoformat()



    try:



        con = _pk_connect(timeout=8)



        try:



            _stale_count = int(con.execute(



                f"SELECT COUNT(*) FROM model_picks WHERE {_pending_clause} "



                "AND TRIM(COALESCE(game_date,'')) <> '' "



                "AND date(game_date) <= date()",



                (_cutoff,),



            ).fetchone()[0] or 0)



        finally:



            con.close()



    except (OSError, ValueError, TypeError) as _e:



        _pk_set_status(f"[reset] stale-pending count failed: {_e}")



        return



    if _stale_count <= 0:



        _pk_set_status(f"[reset] No stale pending model picks older than {_days} day(s).")



        return



    if not _mb.askyesno(



        "Clear Stale Pending Model Picks",



        f"Delete {_stale_count} pending model pick row(s) older than {_days} day(s)\n\n"



        "This removes only stale ungraded rows and keeps graded history.",



        icon="warning",



    ):



        return



    try:



        _pk_write_transaction(



            lambda _con: _con.execute(



                f"DELETE FROM model_picks WHERE {_pending_clause} "



                "AND TRIM(COALESCE(game_date,'')) <> '' "



                "AND date(game_date) <= date()",



                (_cutoff,),



            ),



            retries=4,



        )



        log(f"[reset] Cleared stale pending model picks: {_stale_count} (cutoff={_cutoff})", "info")



        _pk_set_status(f"[reset] Cleared {_stale_count} stale pending model pick row(s).")



    except (OSError, ValueError, TypeError) as _e:



        log(f"[reset] stale pending clear failed: {_e}", "warning")



        _pk_set_status(f"[reset] Stale pending clear failed: {_e}")



        return



    root.after(0, _pk_load_history)



    root.after(0, _all_history_load)



    root.after(0, _pk_update_dual_accuracy)



    try:



        _refresh_tpk_record_summary()



    except (RuntimeError, tk.TclError) as _e:



        _warn_exception("silent_except", _e)

    try:



        _rpt_refresh_history_dropdown()



    except (RuntimeError, tk.TclError) as _e:



        _warn_exception("silent_except", _e)

_MLB_NICKNAMES = {"yankees","red sox","cubs","mets","dodgers","giants","astros","braves",



    "nationals","cardinals","padres","phillies","brewers","athletics","tigers","guardians",



    "mariners","angels","rangers","royals","twins","white sox","orioles","rays","blue jays",



    "rockies","diamondbacks","marlins","pirates","reds"}



_NBA_NICKNAMES = {"lakers","celtics","bulls","heat","knicks","warriors","nets","bucks",



    "suns","clippers","nuggets","jazz","pelicans","hawks","76ers","raptors","hornets",



    "pacers","pistons","cavaliers","magic","wizards","spurs","thunder","blazers",



    "timberwolves","grizzlies","rockets","mavericks"}



def _repair_leagues():



    try:



        con = _pk_connect()



        rows = con.execute("SELECT id,away_team,home_team,league FROM picks").fetchall()



        try:



            model_rows = con.execute("SELECT id,away_team,home_team,league FROM model_picks").fetchall()



        except _sqlite3.Error:



            model_rows = []



        con.close()







        _league_teams = {}



        try:



            if isinstance(df, pd.DataFrame) and not df.empty and {"team", "league"}.issubset(set(df.columns)):



                for _lg in _TPK_SPORTS:



                    _scoped = df[df["league"].apply(lambda x: _same_league_tag(x, _lg))]



                    _teams = [



                        str(t).strip()



                        for t in _scoped["team"].dropna().astype(str).unique().tolist()



                        if str(t).strip()



                    ]



                    if _teams:



                        _league_teams[_lg] = _teams



        except (TypeError, ValueError, AttributeError, KeyError):



            _league_teams = {}







        _fallback_hints = {



            "MLB": _MLB_NICKNAMES,



            "NBA": _NBA_NICKNAMES,



        }







        def _detect_league_from_matchup(away, home):



            away = str(away or "").strip()



            home = str(home or "").strip()



            if not away or not home:



                return None



            best_lg = None



            best_score = 0.0



            for _lg, _teams in _league_teams.items():



                try:



                    _am = _best_team_match(away, _teams, league=_lg, min_score=TEAM_MATCH_MIN_SCORE, ambiguity_gap=0.03)

                    _hm = _best_team_match(home, _teams, league=_lg, min_score=TEAM_MATCH_MIN_SCORE, ambiguity_gap=0.03)

                    if not _am.get("matched") or not _hm.get("matched"):



                        continue



                    if _am.get("ambiguous") or _hm.get("ambiguous"):



                        continue



                    _sc = min(float(_am.get("score", 0.0)), float(_hm.get("score", 0.0)))



                    if _sc > best_score:



                        best_score = _sc



                        best_lg = _lg



                except (TypeError, ValueError, KeyError):



                    continue



            if best_lg:



                return best_lg



            teams_lower = f"{away} {home}".lower()



            for _lg, _hints in _fallback_hints.items():



                try:



                    if any(t in teams_lower for t in _hints):



                        return _lg



                except (TypeError, ValueError):



                    continue



            return None







        fixed = 0



        model_fixed = 0



        updates = []



        model_updates = []



        for rid, away, home, lg in rows:



            detected = _detect_league_from_matchup(away, home)



            if detected and detected != str(lg or "").upper().strip():



                updates.append((detected, rid))



                fixed += 1



        for rid, away, home, lg in model_rows:



            detected = _detect_league_from_matchup(away, home)



            if detected and detected != str(lg or "").upper().strip():



                model_updates.append((detected, rid))



                model_fixed += 1



        if updates:



            _pk_write_transaction(



                lambda _con, _updates=updates: _con.executemany(



                    "UPDATE picks SET league= WHERE id=",



                    _updates,



                ),



                retries=4,



            )



        if model_updates:



            _pk_write_transaction(



                lambda _con, _updates=model_updates: _con.executemany(



                    "UPDATE model_picks SET league= WHERE id=",



                    _updates,



                ),



                retries=4,



            )



        log(f"[repair] Fixed league on picks={fixed}, model_picks={model_fixed}.", "info")



        root.after(0, _pk_load_history)



        root.after(0, _all_history_load)



        root.after(0, _pk_update_dual_accuracy)



        _pk_set_status(f"[repair] Done - fixed picks={fixed}, model_picks={model_fixed} league tag(s).")



    except (OSError, ValueError, TypeError) as _e:

        log(f"[repair] {_e}", "warning")











