def _norm_team_key(name):



    return _canonical_team_key(name, league=None)











def _teams_equivalent_strict(left, right):



    a = _norm_team_key(left)



    b = _norm_team_key(right)



    if not a or not b:



        return False



    if a == b:



        return True



    ac = a.replace(" ", "")



    bc = b.replace(" ", "")



    if ac == bc or ac in bc or bc in ac:



        return True



    at = a.split()



    bt = b.split()



    if len(at) == 1 and len(bt) >= 2 and at[0] in bt:



        return True



    if len(bt) == 1 and len(at) >= 2 and bt[0] in at:



        return True



    return False











def _pk_load_games_for_sport():



    """Load games for the Pick Tracker league dropdown.



    Priority: today's odds file ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ ESPN scoreboard API live.



    Never silently falls back to stale local files.



    """



    sport = pk_sport_var.get().upper()



    _pk_set_status(f"Loading {sport} games...")



    today_str = datetime.now().strftime("%Y%m%d")



    found_df  = None







    # 1. Today's odds file



    _today_file = os.path.join(ODDS_DIR, f"Odds_{sport}_{today_str}.xlsx")



    if os.path.exists(_today_file):



        try:



            found_df = _normalize_game_dataframe_columns(pd.read_excel(_today_file))



            _pk_set_status(f"Loaded from {os.path.basename(_today_file)}")



        except _sqlite3.Error:



            found_df = None







    # 2. ESPN scoreboard API fallback (covers NCAAB tournament + any sport)



    if found_df is None or found_df.empty:



        try:



            import urllib.request as _ur, json as _j



            sp_map = {"MLB":("baseball","mlb","limit=300"),



                      "NBA":("basketball","nba","limit=200"),



                      "NHL":("hockey","nhl","limit=200"),



                      "NFL":("football","nfl","limit=200"),



                      "NCAAB":("basketball","mens-college-basketball","limit=500&groups=50"),



                      "NCAAF":("football","college-football","limit=500")}



            if sport in sp_map:



                sp,lg,params = sp_map[sport]



                url = (f"https://site.api.espn.com/apis/site/v2/sports/{sp}/{lg}/scoreboard"



                       f"dates={today_str}&{params}")



                with _ur.urlopen(url, timeout=10) as r:



                    data = _j.loads(r.read())



                rows = []



                for ev in data.get("events",[]):



                    comp = (ev.get("competitions") or [{}])[0]



                    ea=eh=""



                    for c in comp.get("competitors",[]):



                        nm=c.get("team",{}).get("displayName","")



                        if c.get("homeAway")=="away": ea=nm



                        else: eh=nm



                    gt = ev.get("date","")

                    try:

                        from datetime import datetime as _dt3

                        gt = _dt3.strptime(gt, "%Y-%m-%dT%H:%MZ").strftime("%-m/%-d %-I:%M%p")

                    except (TypeError, ValueError, AttributeError) as _espn_time_err:

                        log(f"[espn_fallback] time parse failed for raw='{ev.get('date','')}': {_espn_time_err}", "warning")

                    # Try to get O/U from odds



                    ou = ""



                    for odd in comp.get("odds",[]):



                        if odd.get("overUnder"): ou = str(odd["overUnder"]); break



                    rows.append({"Time":gt,"Away_Team":ea,"Home_Team":eh,



                                 "Total":ou,"Away_Spread":"","Home_Spread":"",



                                 "Away_ML":"","Home_ML":""})



                if rows:



                    found_df = pd.DataFrame(rows)



                    _pk_set_status(f"[OK] {len(rows)} {sport} games from ESPN API")



        except (TypeError, ValueError, AttributeError, RuntimeError, OSError) as ex:



            log(f"ESPN game load failed for {sport}: {ex}", "warning")







    if found_df is None or found_df.empty:



        _pk_set_status(f"No {sport} games found. Fetch matchups first.")



        return







    games = []



    for _, row in found_df.iterrows():



        t = str(row.get("Time","") or "")



        a = _strip_pitcher(str(row.get("Away_Team","") or ""))



        h = _strip_pitcher(str(row.get("Home_Team","") or ""))



        if a and h:



            games.append(f"{t}  {a} @ {h}")







    if games:



        _pk_autofill._last_df = found_df



        root.after(0, lambda: pk_game_cb.configure(values=games))



        root.after(0, lambda: pk_game_cb.current(0))



        root.after(0, _pk_autofill)



        _pk_set_status(f"[OK] {len(games)} {sport} games loaded.")



    else:



        _pk_set_status(f"No valid games found for {sport}.")











def _pk_refresh_games():



    """Populate the game selector from today's loaded matchup data."""



    if data_df is None or data_df.empty:



        _pk_set_status("[WARN] No matchup data - fetch matchups first.")



        return



    games = []



    for _, row in data_df.iterrows():



        t = str(row.get("Time","") or "")



        a = _strip_pitcher(str(row.get("Away_Team","") or ""))



        h = _strip_pitcher(str(row.get("Home_Team","") or ""))



        games.append(f"{t}  {a} @ {h}")



    pk_game_cb["values"] = games



    if games:



        pk_game_cb.current(0)



        _pk_autofill()



    _pk_set_status(f"[OK] {len(games)} games loaded.")







def _pk_autofill(event=None):



    """Auto-fill O/U line and pick lean from selected game."""



    sel = pk_game_var.get()



    if not sel or sel == "-- select game --": return



    _df = getattr(_pk_autofill, "_last_df", None)



    if _df is None or _df.empty: _df = _current_matchups_df



    if _df is None or _df.empty:



        try:



            _sp = pk_sport_var.get().upper()



            _today = datetime.now().strftime("%Y%m%d")



            _today_file = os.path.join(ODDS_DIR, f"Odds_{_sp}_{_today}.xlsx")



            if os.path.exists(_today_file):



                _df = _normalize_game_dataframe_columns(pd.read_excel(_today_file))



                _pk_autofill._last_df = _df



        except (OSError, ValueError, TypeError, RuntimeError, AttributeError) as _pick_autofill_err:



            log(f"[picktracker] autofill source load failed: {_pick_autofill_err}", "warning")



    if _df is None or _df.empty: return



    for _, row in _df.iterrows():



        try:



            t=str(row.get("Time","") or ""); a=_strip_pitcher(str(row.get("Away_Team","") or "")); h=_strip_pitcher(str(row.get("Home_Team","") or ""))



            if f"{t}  {a} @ {h}".strip() != sel.strip(): continue



            for col in ["Total","OU_Line","ou_line","total","O/U","ou","OU"]:



                val=str(row.get(col,"") or "").replace("o","").replace("u","").replace("O","").replace("U","").strip()



                if val and val.lower() not in ("","nan","none"):



                    pk_line_var.set(val)



                    break



            try:

                g = _rpt_build_game_block(row, pk_sport_var.get().upper())

                lean = g.get("ou_lean","NEUTRAL").upper()

                if lean in ("OVER","UNDER","NEUTRAL"):

                    pk_pick_var.set(lean)

            except (TypeError, ValueError, RuntimeError, AttributeError) as _pick_preview_err:

                log(f"[pick_preview] lean recompute failed: {_pick_preview_err}", "warning")

            break



        except (TypeError, ValueError, AttributeError):

            continue











def _pk_log_pick():



    if str(_PICKTRACKER_PERSISTENCE_MODE or "").upper() == "MEMORY_FALLBACK":



        _pk_set_status("[BLOCKED] Pick logging disabled while DB is in MEMORY_FALLBACK mode.")



        try:



            messagebox.showerror(



                "Pick Logging Blocked",



                "Pick DB persistence is unavailable (MEMORY_FALLBACK).\n"



                "Fix runtime DB path and restart before logging picks.",



            )



        except (RuntimeError, tk.TclError, AttributeError) as _pk_modal_err:



            log(f"[picktracker] blocked modal display failed: {_pk_modal_err}", "warning")



        return



    sel = pk_game_var.get()



    if not sel or sel == "-- select game --":



        _pk_set_status("[WARN] Select a game first.")



        return



    # Parse game identifier from selection string



    parts = sel.strip().split("  ", 1)



    game_time_str = parts[0] if parts else ""



    matchup_str   = parts[1] if len(parts)>1 else sel



    teams = matchup_str.split(" @ ")



    away = teams[0].strip() if teams else ""



    home = teams[1].strip() if len(teams)>1 else ""







    # Fetch physics context for the row



    row_data = {}



    if data_df is not None:



        for _, row in data_df.iterrows():



            t = str(row.get("Time","") or "")



            a = _strip_pitcher(str(row.get("Away_Team","") or ""))



            h = _strip_pitcher(str(row.get("Home_Team","") or ""))



            if f"{t}  {a} @ {h}" == sel:



                row_data = _rpt_build_game_block(row, pk_sport_var.get().upper())



                break







    try:



        line_val = float(pk_line_var.get()) if pk_line_var.get() else None



    except ValueError:



        line_val = None



    _pick_game_date = str(



        row_data.get("game_date")



        or _explicit_game_date_str(game_time_str)



        or ""



    ).strip()



    if not _pick_game_date:



        log(f"[picktracker] pick logged without explicit game date: {away} @ {home} ({game_time_str})", "warning")







    _payload = (



        datetime.now().isoformat(),



        _pick_game_date,



        game_time_str,



        pk_sport_var.get(),   # fixed: was rpt_league_var (wrong tab variable)



        away, home,



        line_val,



        pk_pick_var.get(),



        int(pk_conf_var.get()),



        row_data.get("home_starter",""),



        row_data.get("away_starter",""),



        row_data.get("rho_pct_home"),



        row_data.get("headwind"),



        row_data.get("elev_delta"),



        str({"ou_lean": row_data.get("ou_lean"), "rho":row_data.get("air_density"),



             "hw":row_data.get("headwind"), "dalt":row_data.get("density_alt")}),



        None, "PENDING",



        pk_notes_var.get(),



    )



    _pk_write_transaction(



        lambda _con: _con.execute(



            """INSERT INTO picks



               (logged_at,game_date,game_time,league,away_team,home_team,



                ou_line,pick,confidence,home_starter,away_starter,



                air_dens_pct,headwind_mph,elev_delta_ft,ou_lean_factors,



                actual_total,pick_result,notes)



               VALUES (,,,,,,,,,,,,,,,,,)""",



            _payload,



        )



    )



    pk_notes_var.set("")



    _pk_set_status(f"[OK] Logged: {away} @ {home}  {pk_pick_var.get()}  {line_val}")



    _pk_load_history()











def _pk_auto_grade():



    """Auto-grade PENDING picks by querying ESPN API directly for final scores."""



    import urllib.request as _ur, json as _j







    _proxyless = _ur.build_opener(_ur.ProxyHandler({}))



    _pk_set_status("[PENDING] Fetching final scores from ESPN API...")







    SPORT_MAP = {



        "MLB":   ("baseball",  "mlb",                        "limit=300"),



        "NBA":   ("basketball","nba",                        "limit=300"),



        "NHL":   ("hockey",    "nhl",                        "limit=300"),



        "NFL":   ("football",  "nfl",                        "limit=300"),



        "NCAAB": ("basketball","mens-college-basketball",    "limit=500&groups=50"),



        "NCAAF": ("football",  "college-football",           "limit=500"),



    }







    def _norm_name(name, league=None):



        _rr = _registry_resolve_team_name(name, league=league, frame=globals().get("df"))



        if isinstance(_rr, dict):



            _ck = str(_rr.get("canon") or "").strip()



            if _ck:



                return _ck



        return _canonical_team_key(name, league=league)







    def _name_variants(name, league=None):



        """



        Canonical + alias variants for robust historical identity matching.



        """



        out = []



        seen = set()



        raw = str(name or "").strip()



        if not raw:



            return []



        _raw_stripped = ""



        try:



            _raw_stripped = _strip_pitcher(raw)



        except (TypeError, ValueError, AttributeError):



            _raw_stripped = raw



        for cand in (raw, _raw_stripped, _canonical_team_key(raw, league=league), _norm_name(raw, league=league)):



            c = str(cand or "").strip().lower()



            if c and c not in seen:



                seen.add(c)



                out.append(c)



        # Alias map fallback for historical city-only / short-form rows.



        key = re.sub(r"[^a-z0-9 ]+", " ", raw.lower()).strip()



        key = re.sub(r"\s+", " ", key)



        alias_map = globals().get("_TEAM_ALIAS_CANON") or {}



        if isinstance(alias_map, dict):



            mapped = str(alias_map.get(key) or "").strip().lower()



            if mapped:



                mapped_ck = _canonical_team_key(mapped, league=league)



                for cand in (mapped, mapped_ck):



                    c = str(cand or "").strip().lower()



                    if c and c not in seen:



                        seen.add(c)



                        out.append(c)



        # Token tail/head variants.



        toks = [t for t in re.split(r"[^a-z0-9]+", key) if t]



        if toks:



            token_forms = [toks[-1], " ".join(toks[-2:]) if len(toks) >= 2 else ""]



            for cand in token_forms:



                c = str(cand or "").strip().lower()



                if c and c not in seen:



                    seen.add(c)



                    out.append(c)



        return out







    def _match_name(left, right, league=None):



        ls = str(left or "").strip().lower()



        rs = str(right or "").strip().lower()



        if not ls or not rs:



            return False



        if ls == rs:



            return True



        thr = 0.78 if str(league or "").upper().strip() == "MLB" else 0.82



        try:



            score = _team_match_score(left, right, league=league)



        except GUI_ERRORS:



            score = 0.0



        if score >= thr:



            return True



        ltok = [t for t in re.split(r"[^a-z0-9]+", ls) if t]



        rtok = [t for t in re.split(r"[^a-z0-9]+", rs) if t]



        if not ltok or not rtok:



            return False



        # Token-overlap fallback for historical aliases (e.g., city-only logs).



        inter = set(ltok).intersection(set(rtok))



        return len(inter) >= min(len(set(ltok)), len(set(rtok)), 2)







    def _parse_espn_start_et(_raw_dt):



        try:



            _txt = str(_raw_dt or "").strip()



            if not _txt:



                return None



            return datetime.fromisoformat(_txt.replace("Z", "+00:00")).astimezone(ZoneInfo("America/New_York"))



        except GUI_ERRORS:



            return None







    def _pick_closest_score(_cand_rows, _game_time):



        _rows = list(_cand_rows or [])



        if not _rows:



            return None



        if len(_rows) == 1:



            return _rows[0]



        _target = _game_start_et(_game_time)



        if _target is None:



            return _rows[0]



        _best = None



        _best_delta = None



        for _row in _rows:



            _evt = _row.get("event_start_et")



            if _evt is None:



                continue



            try:



                _delta = abs((_evt - _target).total_seconds())



            except GUI_ERRORS:



                continue



            if (_best is None) or (_best_delta is None) or (_delta < _best_delta):



                _best = _row



                _best_delta = _delta



        return _best if _best is not None else _rows[0]







    def _parse_cached_event_start(_raw_dt):



        try:



            _txt = str(_raw_dt or "").strip()



            if not _txt:



                return None



            if _txt.lower().startswith("event:"):



                return None



            return datetime.fromisoformat(_txt).astimezone(ZoneInfo("America/New_York"))



        except GUI_ERRORS:



            return None







    def _shift_date_token(ds, day_delta):



        try:



            _d = datetime.strptime(str(ds or "").strip(), "%Y%m%d")



            return (_d + timedelta(days=int(day_delta))).strftime("%Y%m%d")



        except GUI_ERRORS:



            return ""







    def _lookup_score_for_ds(ds, lg, na, nh, gtime=None, raw_away=None, raw_home=None):



        _away_variants = _name_variants(na, lg) + _name_variants(raw_away, lg)



        _home_variants = _name_variants(nh, lg) + _name_variants(raw_home, lg)



        if not _away_variants:



            _away_variants = [str(na or "").strip().lower()]



        if not _home_variants:



            _home_variants = [str(nh or "").strip().lower()]



        if ds and lg and na and nh:



            _exact_rows = list(score_lookup.get((ds, lg, na, nh)) or [])



            _exact_pick = _pick_closest_score(_exact_rows, gtime)



            if _exact_pick is not None:



                return _exact_pick



        _cands = []



        _swap_cands = []



        if ds and _away_variants and _home_variants:



            for (k_ds, k_lg, k_away, k_home), _rows in score_lookup.items():



                if ds != k_ds:



                    continue



                if lg and (k_lg != lg):



                    continue



                _rows = list(_rows or [])



                _away_ok = any(_match_name(_av, k_away, lg) for _av in _away_variants)



                _home_ok = any(_match_name(_hv, k_home, lg) for _hv in _home_variants)



                _swap_away_ok = any(_match_name(_av, k_home, lg) for _av in _away_variants)



                _swap_home_ok = any(_match_name(_hv, k_away, lg) for _hv in _home_variants)



                if _away_ok and _home_ok:



                    _cands.extend(_rows)



                elif _swap_away_ok and _swap_home_ok:



                    _swap_cands.extend(_rows)



        _cand_pick = _pick_closest_score(_cands, gtime)



        if _cand_pick is not None:



            return _cand_pick



        _swap_pick = _pick_closest_score(_swap_cands, gtime)



        if _swap_pick is not None:



            return _swap_pick



        return None







    def _lookup_score(ds, lg, na, nh, gtime=None, raw_away=None, raw_home=None):



        _lg = _normalize_league_tag(lg)



        _first = _lookup_score_for_ds(ds, _lg, na, nh, gtime, raw_away=raw_away, raw_home=raw_home)



        if _first is not None:



            _first["_date_shift_days"] = 0



            return _first



        # Midnight / timezone tolerance: allow one-day shift before failing identity.



        for _shift in (-1, 1):



            _ds2 = _shift_date_token(ds, _shift)



            if not _ds2:



                continue



            _cand = _lookup_score_for_ds(_ds2, _lg, na, nh, gtime, raw_away=raw_away, raw_home=raw_home)



            if _cand is not None:



                _cand["_date_shift_days"] = _shift



                return _cand



        return None







    def _detect_alt_league_match(ds, current_lg, away_raw, home_raw, gtime=None):



        _alts = []



        _current = _normalize_league_tag(current_lg)



        for _cand_lg in SPORT_MAP.keys():



            if _cand_lg == _current:



                continue



            _cand_away = _norm_name(_strip_pitcher(away_raw), _cand_lg)



            _cand_home = _norm_name(_strip_pitcher(home_raw), _cand_lg)



            if not _cand_away or not _cand_home:



                continue



            _m = _lookup_score(ds, _cand_lg, _cand_away, _cand_home, gtime, raw_away=away_raw, raw_home=home_raw)



            if _m is None:



                continue



            _alts.append((_cand_lg, _cand_away, _cand_home, _m))



        if len(_alts) == 1:



            return _alts[0]



        return None







    def _no_match_reason(ds, lg, na, nh):



        _lg = _normalize_league_tag(lg)



        if not str(ds or "").strip():



            return "missing game_date on pick row"



        if not str(_lg or "").strip():



            return "missing league on pick row"



        if _lg not in SPORT_MAP:



            return f"unsupported league for grader: {_lg}"



        _id_rows = list(score_identity_lookup.get((ds, _lg)) or [])



        if _id_rows:



            _pair_rows = [



                _r for _r in _id_rows



                if (



                    _match_name(na, _r.get("away_canon"), _lg)



                    and _match_name(nh, _r.get("home_canon"), _lg)



                ) or (



                    _match_name(na, _r.get("home_canon"), _lg)



                    and _match_name(nh, _r.get("away_canon"), _lg)



                )



            ]



            if _pair_rows and not any(bool(_r.get("is_final")) for _r in _pair_rows):



                return "game found on scoreboard but not final yet"



        _pool = [k for k in score_lookup.keys() if k[0] == ds and k[1] == _lg]



        if not _pool:



            if _id_rows:



                return "scoreboard events found but none final yet for this date/league"



            _prev_ds = _shift_date_token(ds, -1)



            _next_ds = _shift_date_token(ds, 1)



            _neighbor = any(



                (k[1] == _lg and k[0] in {_prev_ds, _next_ds})



                for k in score_lookup.keys()



            )



            if _neighbor:



                return "matched league events exist on ds+/-1 (timezone/date-shift mismatch)"



            _today_ds = datetime.now().strftime("%Y%m%d")



            _yday_ds = (datetime.now() - timedelta(days=1)).strftime("%Y%m%d")



            if ds in {_today_ds, _yday_ds}:



                return f"awaiting finals or scoreboard unavailable for {_lg} on {ds}"



            return f"no finalized score events available for {_lg} on {ds}"



        _away_any = any(_match_name(na, _k[2], _lg) for _k in _pool)



        _home_any = any(_match_name(nh, _k[3], _lg) for _k in _pool)



        _swap_any = any(_match_name(na, _k[3], _lg) and _match_name(nh, _k[2], _lg) for _k in _pool)



        if _swap_any:



            return "teams only matched when scoreboard orientation was swapped"



        if _away_any and (not _home_any):



            return "away matched but home did not match scoreboard names"



        if _home_any and (not _away_any):



            return "home matched but away did not match scoreboard names"



        return "no scoreboard matchup identity match"



    def _no_match_diagnostics(ds, lg, na, nh):

        _lg = _normalize_league_tag(lg)

        try:

            _pool = [k for k in score_lookup.keys() if k[0] == ds and k[1] == _lg]

            _away_any = any(_match_name(na, _k[2], _lg) for _k in _pool)

            _home_any = any(_match_name(nh, _k[3], _lg) for _k in _pool)

            _swap_any = any(_match_name(na, _k[3], _lg) and _match_name(nh, _k[2], _lg) for _k in _pool)

            _sample = ", ".join(f"{_k[2]}@{_k[3]}" for _k in _pool[:4]) if _pool else "none"

            return (

                f"pool={len(_pool)} away_any={int(bool(_away_any))} "

                f"home_any={int(bool(_home_any))} swap_any={int(bool(_swap_any))} "

                f"samples={_sample}"

            )

        except (TypeError, ValueError, RuntimeError, AttributeError) as _diag_err:

            return f"diag_error:{_diag_err}"







    def _write_unmatched_grading_report(rows):



        rows = list(rows or [])



        if not rows:



            return None



        out_dir = SCRIPT_DIR / "diagnostics"



        out_dir.mkdir(parents=True, exist_ok=True)



        stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")



        out_csv = out_dir / f"grading_unmatched_{stamp}.csv"



        out_txt = out_dir / f"grading_unmatched_{stamp}.txt"



        tmp_csv = out_csv.with_suffix(".csv.tmp")



        tmp_txt = out_txt.with_suffix(".txt.tmp")



        try:



            import csv as _csv



            fields = [



                "table", "row_id", "league", "game_date_ds", "game_time",



                "away_raw", "home_raw", "away_canon", "home_canon",



                "reason", "diagnostics", "generated_at",



            ]



            with open(tmp_csv, "w", newline="", encoding="utf-8") as f:



                w = _csv.DictWriter(f, fieldnames=fields)



                w.writeheader()



                for r in rows:



                    w.writerow({k: r.get(k, "") for k in fields})



            os.replace(str(tmp_csv), str(out_csv))



            with open(tmp_txt, "w", encoding="utf-8") as f:



                f.write(f"UNMATCHED GRADING REPORT :: {datetime.now().astimezone().isoformat()}\n")



                f.write(f"rows={len(rows)}\n\n")



                for r in rows:



                    f.write(



                        f"[{r.get('table','')}] id={r.get('row_id','')} {r.get('league','')} {r.get('game_date_ds','')} {r.get('game_time','')}\n"



                        f"  raw:   {r.get('away_raw','')} @ {r.get('home_raw','')}\n"



                        f"  canon: {r.get('away_canon','')} @ {r.get('home_canon','')}\n"



                        f"  reason:{r.get('reason','')}\n"

                        f"  diag:  {r.get('diagnostics','')}\n\n"



                    )



            os.replace(str(tmp_txt), str(out_txt))



            return {"csv": str(out_csv), "txt": str(out_txt), "rows": len(rows)}



        finally:



            try:



                if tmp_csv.exists():



                    tmp_csv.unlink()



            except (OSError, ValueError, TypeError) as _e:



                _warn_exception("silent_except", _e)

            try:



                if tmp_txt.exists():



                    tmp_txt.unlink()



            except (OSError, ValueError, TypeError) as _e:



                _warn_exception("silent_except", _e)

    def _validate_score_event_row(_rec):



        """



        Structural validation only: reject missing/corrupt keys, not extreme-but-real scores.



        """



        if not isinstance(_rec, dict):



            return "invalid_record_type"



        _lg = str(_rec.get("league") or "").upper().strip()



        if _lg not in SPORT_MAP:



            return "invalid_league"



        _gd = str(_rec.get("game_date") or "").strip()



        if not re.match(r"^\d{4}-\d{2}-\d{2}$", _gd):



            return "invalid_game_date"



        _away = str(_rec.get("away_team") or "").strip()



        _home = str(_rec.get("home_team") or "").strip()



        if not _away:



            return "missing_away_team"



        if not _home:



            return "missing_home_team"



        _ac = str(_rec.get("away_canon") or "").strip()



        _hc = str(_rec.get("home_canon") or "").strip()



        if not _ac:



            return "missing_away_canon"



        if not _hc:



            return "missing_home_canon"



        if _ac == _hc:



            return "away_home_canon_collision"



        _as = _to_float_or_none(_rec.get("away_score"))



        _hs = _to_float_or_none(_rec.get("home_score"))



        _tt = _to_float_or_none(_rec.get("total"))



        if (_as is None) or (_hs is None) or (_tt is None):



            return "missing_score_values"



        if abs((_as + _hs) - _tt) > 0.25:



            return "score_total_mismatch"



        _start_iso = str(_rec.get("event_start_et") or "").strip()



        if not _start_iso:



            return "missing_event_start"



        return ""







    def _fetch_pending_rows(_con, _table):



        _pending_clause = "UPPER(TRIM(COALESCE(pick_result,'PENDING')))='PENDING'"



        if _table == "picks":



            return _con.execute(



                "SELECT id, game_date, game_time, league, away_team, home_team, ou_line, pick "



                f"FROM picks WHERE {_pending_clause}"



            ).fetchall()



        try:



            return _con.execute(



                "SELECT id, game_date, game_time, league, away_team, home_team, ou_line, pick "



                f"FROM model_picks WHERE {_pending_clause}"



            ).fetchall()



        except _sqlite3.Error:



            # Backward compatibility for very old model_picks schemas.



            return [



                (rid, "", "", "", away, home, ou_line, pick)



                for (rid, away, home, ou_line, pick) in _con.execute(



                    "SELECT id, away_team, home_team, ou_line, pick "



                    f"FROM model_picks WHERE {_pending_clause}"



                ).fetchall()



            ]







    con = _pk_connect()



    pending = _fetch_pending_rows(con, "picks")



    m_pending_seed = _fetch_pending_rows(con, "model_picks")



    con.close()







    if (not pending) and (not m_pending_seed):



        _pk_set_status("[OK] No pending picks to grade (analyst or model).")



        return







    from datetime import timedelta as _td



    needed = set()



    dates_seen = set()







    def _seed_needed(_rows):



        for _, gdate, gtime, league, *_ in _rows:



            _ds = str(gdate).replace("-", "")[:8] if gdate else ""



            if (not _ds) and gtime:



                _ds = str(_explicit_game_date_str(gtime) or "").replace("-", "")[:8]



            if _ds:



                dates_seen.add(_ds)



                _lg = _normalize_league_tag(league)



                if _lg in SPORT_MAP:



                    needed.add((_ds, _lg))



                else:



                    for _all_lg in SPORT_MAP:



                        needed.add((_ds, _all_lg))







    _seed_needed(pending)



    _seed_needed(m_pending_seed)







    if not dates_seen:



        for _d in [datetime.now(), datetime.now() - _td(1)]:



            for _lg in SPORT_MAP:



                needed.add((_d.strftime("%Y%m%d"), _lg))







    score_lookup = {}  # key=(ds, lg, away_norm, home_norm) -> [final events]



    score_identity_lookup = {}  # key=(ds, lg) -> [{away_canon, home_canon, is_final, status, source}]



    score_event_rows = {}  # key -> canonical finalized score event payload



    fetched_api = 0



    loaded_from_cache = 0







    # Seed lookup from cached score_events first (covers historical rows ESPN scoreboard may no longer return).



    try:



        _cache_con = _pk_connect(timeout=8)



        try:



            _pk_ensure_score_events_schema(_cache_con)



            _cache_rows = _cache_con.execute(



                "SELECT league, game_date, away_team, home_team, away_canon, home_canon, "



                "away_score, home_score, total, event_start_et, event_uid "



                "FROM score_events ORDER BY id DESC LIMIT 25000"



            ).fetchall()



        finally:



            _cache_con.close()



    except (_sqlite3.Error, OSError, ValueError, TypeError) as _cache_err:



        _cache_rows = []



        log(f"[grade:score_events] cache preload unavailable: {_cache_err}", "warning")







    if _cache_rows:



        _needed_pairs = set(needed)



        _cache_drop = {}



        for _r in _cache_rows:



            (



                _c_lg, _c_gd, _c_away, _c_home, _c_ac, _c_hc,



                _c_as, _c_hs, _c_tt, _c_start, _c_uid



            ) = _r



            _lg = _normalize_league_tag(_c_lg)



            _gd = str(_c_gd or "").strip()



            if (not _lg) or (not _gd):



                _cache_drop["missing_keys"] = int(_cache_drop.get("missing_keys", 0) or 0) + 1



                continue



            _ds = _gd.replace("-", "")[:8]



            if _needed_pairs and ((_ds, _lg) not in _needed_pairs):



                continue



            _ac = str(_c_ac or "").strip() or _norm_name(_c_away, _lg)



            _hc = str(_c_hc or "").strip() or _norm_name(_c_home, _lg)



            _evt_start = _parse_cached_event_start(_c_start)



            _evt_iso = str(_c_start or "").strip() if str(_c_start or "").strip() else (f"event:{_c_uid}" if _c_uid else "")



            _row = {



                "away_score": _to_float_or_none(_c_as),



                "home_score": _to_float_or_none(_c_hs),



                "total": _to_float_or_none(_c_tt),



                "away": str(_c_away or "").strip(),



                "home": str(_c_home or "").strip(),



                "league": _lg,



                "date_token": _ds,



                "event_id": str(_c_uid or "").strip(),



                "away_canon": _ac,



                "home_canon": _hc,



                "event_start_et": _evt_start,



                "event_start_iso": _evt_iso,



                "source": "score_events_cache",



            }



            if _row["away_score"] is None or _row["home_score"] is None or _row["total"] is None:



                _cache_drop["missing_scores"] = int(_cache_drop.get("missing_scores", 0) or 0) + 1



                continue



            if not _ac or not _hc or _ac == _hc:



                _cache_drop["bad_canon"] = int(_cache_drop.get("bad_canon", 0) or 0) + 1



                continue



            score_identity_lookup.setdefault((_ds, _lg), []).append({



                "away_canon": _ac,



                "home_canon": _hc,



                "is_final": True,



                "status": "Final",



                "source": "score_events_cache",



            })



            score_lookup.setdefault((_ds, _lg, _ac, _hc), []).append(_row)



            loaded_from_cache += 1



        if _cache_drop:



            _top = ", ".join(f"{k}:{v}" for k, v in sorted(_cache_drop.items(), key=lambda kv: (-kv[1], kv[0]))[:6])



            log(f"[grade:score_events] cache rows dropped={sum(_cache_drop.values())} reasons={_top}", "warning")



        log(f"[grade:score_events] cache preload rows={loaded_from_cache}", "info")







    for (ds, lg) in needed:



        if lg not in SPORT_MAP:



            continue



        sp, league_slug, params = SPORT_MAP[lg]



        url = (f"https://site.api.espn.com/apis/site/v2/sports/{sp}/{league_slug}/scoreboard"



               f"dates={ds}&{params}")



        try:



            import time as _t



            _t.sleep(0.3)



            try:



                with _proxyless.open(url, timeout=12) as _r:



                    data = _j.loads(_r.read())



            except (OSError, ValueError, TypeError):



                with _ur.urlopen(url, timeout=12) as _r:



                    data = _j.loads(_r.read())



            for ev in data.get("events", []):



                status = ev.get("status", {}).get("type", {}).get("description", "")



                comp = (ev.get("competitions") or [{}])[0]



                ea = eh = ""



                as_ = hs = 0.0



                for c in comp.get("competitors", []):



                    nm = c.get("team", {}).get("displayName", "")



                    try:



                        sc = float(c.get("score", 0) or 0)



                    except (TypeError, ValueError):



                        sc = 0.0



                    if c.get("homeAway") == "away":



                        ea = nm



                        as_ = sc



                    else:



                        eh = nm



                        hs = sc



                if ea and eh:



                    _na = _norm_name(_strip_pitcher(ea), lg)



                    _nh = _norm_name(_strip_pitcher(eh), lg)



                    if not _na or not _nh:



                        continue



                    score_identity_lookup.setdefault((ds, lg), []).append({



                        "away_canon": _na,



                        "home_canon": _nh,



                        "is_final": ("Final" in str(status or "")),



                        "status": str(status or ""),



                        "source": "espn_api",



                    })



                    if "Final" not in status:



                        continue



                    _key = (ds, lg, _na, _nh)



                    _evt_uid = str(ev.get("id") or "").strip()



                    _evt_start_et = _parse_espn_start_et(ev.get("date"))



                    _evt_start_iso = _evt_start_et.isoformat() if _evt_start_et is not None else ""



                    if (not _evt_start_iso) and _evt_uid:



                        _evt_start_iso = f"event:{_evt_uid}"



                    _row = {



                        "away_score": as_,



                        "home_score": hs,



                        "total": as_ + hs,



                        "away": ea,



                        "home": eh,



                        "league": lg,



                        "date_token": ds,



                        "event_id": _evt_uid,



                        "away_canon": _na,



                        "home_canon": _nh,



                        "event_start_et": _evt_start_et,



                        "event_start_iso": _evt_start_iso,



                        "source": "espn_api",



                    }



                    score_lookup.setdefault(_key, []).append(_row)



                    _score_key = (



                        lg,



                        ds,



                        _na,



                        _nh,



                        _evt_start_iso,



                    )



                    if _score_key not in score_event_rows:



                        score_event_rows[_score_key] = {



                            "event_uid": f"{lg}:{_evt_uid}" if _evt_uid else None,



                            "league": lg,



                            "game_date": f"{ds[:4]}-{ds[4:6]}-{ds[6:8]}",



                            "away_team": ea,



                            "home_team": eh,



                            "away_canon": _na,



                            "home_canon": _nh,



                            "away_score": as_,



                            "home_score": hs,



                            "total": as_ + hs,



                            "event_start_et": _evt_start_iso,



                            "source": "espn_api",



                            "fetched_at": datetime.now().astimezone().isoformat(),



                        }



                    fetched_api += 1



        except (requests.RequestException, OSError, ValueError, TypeError) as ex:



            log(f"ESPN score fetch failed {lg} {ds}: {ex}", "warning")







    if score_event_rows:



        _se_payload = []



        _se_drop_reasons = {}



        for _rec in score_event_rows.values():



            _v_issue = _validate_score_event_row(_rec)



            if _v_issue:



                _se_drop_reasons[_v_issue] = int(_se_drop_reasons.get(_v_issue, 0) or 0) + 1



                continue



            _uid = _rec.get("event_uid")

            _uid = str(_uid).strip() if _uid is not None else None

            if not _uid:

                _uid = None

            _se_payload.append((



                _uid,



                _rec.get("league", ""),



                _rec.get("game_date", ""),



                _rec.get("away_team", ""),



                _rec.get("home_team", ""),



                _rec.get("away_canon", ""),



                _rec.get("home_canon", ""),



                _rec.get("away_score"),



                _rec.get("home_score"),



                _rec.get("total"),



                _rec.get("event_start_et", ""),



                _rec.get("source", "espn_api"),



                _rec.get("fetched_at", datetime.now().astimezone().isoformat()),



            ))



        if _se_drop_reasons:



            _top = ", ".join(f"{k}:{v}" for k, v in sorted(_se_drop_reasons.items(), key=lambda kv: (-kv[1], kv[0]))[:8])



            log(f"[grade:score_events] dropped_invalid_rows={sum(_se_drop_reasons.values())} reasons={_top}", "warning")



        _sql_score_upsert = (



            "INSERT INTO score_events "



            "(event_uid, league, game_date, away_team, home_team, away_canon, home_canon, "



            " away_score, home_score, total, event_start_et, source, fetched_at) "



            "VALUES (,,,,,,,,,,,,) "



            "ON CONFLICT(league, game_date, away_canon, home_canon, event_start_et) DO UPDATE SET "



            "event_uid=COALESCE(excluded.event_uid, score_events.event_uid), "



            "away_team=excluded.away_team, home_team=excluded.home_team, "



            "away_score=excluded.away_score, home_score=excluded.home_score, total=excluded.total, "



            "source=excluded.source, fetched_at=excluded.fetched_at"



        )



        try:



            def _write_score_events(_con):



                _pk_ensure_score_events_schema(_con)



                _con.executemany(_sql_score_upsert, _se_payload)



            _pk_write_transaction(_write_score_events, retries=4)



            log(f"[grade:score_events] upserted {len(_se_payload)} finalized event rows.", "info")



        except (_sqlite3.Error, OSError, ValueError, TypeError, RuntimeError) as _se_err:



            log(f"[grade:score_events] upsert failed: {_se_err}", "warning")







    if not score_lookup:



        _pk_set_status("[WARN] No final scores found yet - games may still be in progress.")



        return







    def _grade_result(_actual, _ou_line, _pick):



        try:



            _line = float(_ou_line)



        except (TypeError, ValueError):



            return "PENDING"



        _pick_u = str(_pick or "").upper().strip()



        if abs(float(_actual) - _line) < 0.05:



            return "PUSH"



        if _pick_u == "OVER":



            return "WIN" if float(_actual) > _line else "LOSS"



        if _pick_u == "UNDER":



            return "WIN" if float(_actual) < _line else "LOSS"



        return "PENDING"







    graded = 0



    no_match = 0



    date_shift_hits = 0



    _no_match_samples = []



    _unmatched_rows = []



    _pick_updates = []



    _pick_league_repairs = []



    for (row_id, gdate, gtime, league, away, home, ou_line, pick) in pending:



        _ds = str(gdate or "").replace("-", "")[:8]



        if (not _ds) and gtime:



            _ds = str(_explicit_game_date_str(gtime) or "").replace("-", "")[:8]



        _lg = _normalize_league_tag(league)



        _na = _norm_name(_strip_pitcher(away), _lg)



        _nh = _norm_name(_strip_pitcher(home), _lg)



        matched = _lookup_score(_ds, _lg, _na, _nh, gtime, raw_away=away, raw_home=home)



        if matched is None:



            _alt = _detect_alt_league_match(_ds, _lg, away, home, gtime=gtime)



            if _alt is not None:



                _alt_lg, _alt_na, _alt_nh, _alt_match = _alt



                _pick_league_repairs.append((_alt_lg, row_id))



                _lg, _na, _nh, matched = _alt_lg, _alt_na, _alt_nh, _alt_match



                log(



                    f"[grade] league repair candidate id={row_id}: {_normalize_league_tag(league)} -> {_alt_lg} "



                    f"for {str(away or '').strip()} @ {str(home or '').strip()}",



                    "warning",



                )



        if matched is None:



            no_match += 1



            _reason = _no_match_reason(_ds, _lg, _na, _nh)



            _unmatched_rows.append({



                "table": "picks",



                "row_id": row_id,



                "league": _lg,



                "game_date_ds": _ds,



                "game_time": str(gtime or "").strip(),



                "away_raw": str(away or "").strip(),



                "home_raw": str(home or "").strip(),



                "away_canon": str(_na or "").strip(),



                "home_canon": str(_nh or "").strip(),



                "reason": _reason,

                "diagnostics": _no_match_diagnostics(_ds, _lg, _na, _nh),



                "generated_at": datetime.now().astimezone().isoformat(),



            })



            if len(_no_match_samples) < 12:



                _no_match_samples.append(



                    f"id={row_id} {str(away or '').strip()} @ {str(home or '').strip()} ({_lg} {_ds}): "



                    f"{_reason}"



                )



            continue







        actual = matched["total"]



        if int(_to_float_or_none(matched.get("_date_shift_days")) or 0) != 0:



            date_shift_hits += 1



        result = _grade_result(actual, ou_line, pick)







        if result != "PENDING":



            _pick_updates.append((actual, result, row_id))



            graded += 1



    if _pick_updates:



        _pk_write_transaction(



            lambda _con: _con.executemany(



                "UPDATE picks SET actual_total=, pick_result= "



                "WHERE id= AND (pick_result IS NULL OR UPPER(TRIM(COALESCE(pick_result,'')))='PENDING')",



                _pick_updates,



            )



        )



    if _pick_league_repairs:



        _pk_write_transaction(



            lambda _con: _con.executemany(



                "UPDATE picks SET league= "



                "WHERE id= AND (pick_result IS NULL OR UPPER(TRIM(COALESCE(pick_result,'')))='PENDING')",



                _pick_league_repairs,



            )



        )







    _score_rows_available = int(fetched_api + loaded_from_cache)



    msg = (



        f"[OK] Auto-graded {graded}/{len(pending)} pick(s). "



        f"Score rows available={_score_rows_available} "



        f"(api_finals={fetched_api}, cached={loaded_from_cache})."



    )



    if no_match:



        msg += f" {no_match} pick(s) not matched."



    if date_shift_hits:



        msg += f" ds+/-1_matches={date_shift_hits}."



    if _no_match_samples:



        for _s in _no_match_samples[:5]:



            log(f"[grade] unmatched -> {_s}", "warning")



        msg += f" unmatched diagnostics logged={len(_no_match_samples)}."



    _pk_set_status(msg)



    log(msg, "info")



    try:



        _tune_model_weights()



    except (_sqlite3.Error, OSError, ValueError, TypeError, RuntimeError) as _re:

        log(f"[repair_leagues] failed: {_re}", "warning")

        return



        pass







    # Also grade model_picks with the same scores



    m_graded = 0



    m_no_match = 0



    m_date_shift_hits = 0



    _m_no_match_samples = []



    try:



        _model_updates = []



        _model_league_repairs = []



        for (rid, gdate, gtime, league, away, home, ou_line, pick) in m_pending_seed:



            _ds = str(gdate or "").replace("-", "")[:8]



            if (not _ds) and gtime:



                _ds = str(_explicit_game_date_str(gtime) or "").replace("-", "")[:8]



            _lg = _normalize_league_tag(league)



            _na = _norm_name(_strip_pitcher(away), _lg)



            _nh = _norm_name(_strip_pitcher(home), _lg)



            matched = _lookup_score(_ds, _lg, _na, _nh, gtime, raw_away=away, raw_home=home)



            if not matched:



                _alt = _detect_alt_league_match(_ds, _lg, away, home, gtime=gtime)



                if _alt is not None:



                    _alt_lg, _alt_na, _alt_nh, _alt_match = _alt



                    _model_league_repairs.append((_alt_lg, rid))



                    _lg, _na, _nh, matched = _alt_lg, _alt_na, _alt_nh, _alt_match



                    log(



                        f"[grade:model] league repair candidate id={rid}: {_normalize_league_tag(league)} -> {_alt_lg} "



                        f"for {str(away or '').strip()} @ {str(home or '').strip()}",



                        "warning",



                    )



            if not matched:



                m_no_match += 1



                _reason = _no_match_reason(_ds, _lg, _na, _nh)



                _unmatched_rows.append({



                    "table": "model_picks",



                    "row_id": rid,



                    "league": _lg,



                    "game_date_ds": _ds,



                    "game_time": str(gtime or "").strip(),



                    "away_raw": str(away or "").strip(),



                    "home_raw": str(home or "").strip(),



                    "away_canon": str(_na or "").strip(),



                    "home_canon": str(_nh or "").strip(),



                    "reason": _reason,

                    "diagnostics": _no_match_diagnostics(_ds, _lg, _na, _nh),



                    "generated_at": datetime.now().astimezone().isoformat(),



                })



                if len(_m_no_match_samples) < 12:



                    _m_no_match_samples.append(



                        f"id={rid} {str(away or '').strip()} @ {str(home or '').strip()} ({_lg} {_ds}): "



                        f"{_reason}"



                    )



                continue



            actual = matched["total"]



            if int(_to_float_or_none(matched.get("_date_shift_days")) or 0) != 0:



                m_date_shift_hits += 1



            result = _grade_result(actual, ou_line, pick)



            if result == "PENDING":



                continue



            _model_updates.append((actual, result, rid))



            m_graded += 1



        if _model_updates:



            _pk_write_transaction(



                lambda _con: _con.executemany(



                    "UPDATE model_picks SET actual_total=, pick_result= "



                    "WHERE id= AND (pick_result IS NULL OR UPPER(TRIM(COALESCE(pick_result,'')))='PENDING')",



                    _model_updates,



                )



            )



    except (OSError, ValueError, TypeError, RuntimeError) as _em:



        log(f"model_picks grading: {_em}", "warning")







    if _m_no_match_samples:



        for _s in _m_no_match_samples[:5]:



            log(f"[grade:model] unmatched -> {_s}", "warning")



    _unmatched_report = None



    try:



        _unmatched_report = _write_unmatched_grading_report(_unmatched_rows)



        if isinstance(_unmatched_report, dict):



            log(f"[grade:unmatched_report] CSV: {_unmatched_report.get('csv','')}", "info")



            log(f"[grade:unmatched_report] TXT: {_unmatched_report.get('txt','')}", "info")



    except (OSError, ValueError, TypeError) as _urpt_err:



        log(f"[grade:unmatched_report] write failed: {_urpt_err}", "warning")



    # Auto-retire stale unmatched pending rows so historical scoreboard gaps do not

    # generate the same warnings forever on every startup.

    try:

        _stale_cutoff = (datetime.now(ZoneInfo("America/New_York")) - timedelta(days=2)).strftime("%Y%m%d")

        _stale_pick_ids = []

        _stale_model_ids = []

        for _r in _unmatched_rows:

            _reason = str(_r.get("reason", "") or "").lower()

            _ds = str(_r.get("game_date_ds", "") or "").strip()

            if ("not final yet" not in _reason) and ("scoreboard unavailable" not in _reason):

                continue

            if not _ds or _ds > _stale_cutoff:

                continue

            if str(_r.get("table", "")).strip().lower() == "model_picks":

                _stale_model_ids.append(int(_r.get("row_id")))

            else:

                _stale_pick_ids.append(int(_r.get("row_id")))

        if _stale_pick_ids or _stale_model_ids:

            def _mark_stale(_con):

                if _stale_pick_ids:

                    _con.executemany(

                        "UPDATE picks SET pick_result='STALE_UNGRADED' "

                        "WHERE id= AND (pick_result IS NULL OR UPPER(TRIM(COALESCE(pick_result,'')))='PENDING')",

                        [(_i,) for _i in _stale_pick_ids],

                    )

                if _stale_model_ids:

                    _con.executemany(

                        "UPDATE model_picks SET pick_result='STALE_UNGRADED' "

                        "WHERE id= AND (pick_result IS NULL OR UPPER(TRIM(COALESCE(pick_result,'')))='PENDING')",

                        [(_i,) for _i in _stale_model_ids],

                    )

            _pk_write_transaction(_mark_stale, retries=3)

            log(

                f"[grade] retired stale pending rows: picks={len(_stale_pick_ids)} "

                f"model_picks={len(_stale_model_ids)} cutoff={_stale_cutoff}",

                "warning",

            )

    except (OSError, ValueError, TypeError) as _stale_mark_err:

        log(f"[grade] stale pending retirement failed: {_stale_mark_err}", "warning")



    log(



        f"[grade:model] auto-graded {m_graded}/{len(m_pending_seed)} pending model pick(s); "

        f"unmatched={m_no_match}; ds+/-1_matches={m_date_shift_hits}.",



        "info",



    )



    _pk_set_status(



        f"[OK] Auto-graded picks={graded}/{len(pending)} model={m_graded}/{len(m_pending_seed)}; "



        f"score_rows={_score_rows_available} (api={fetched_api}, cache={loaded_from_cache})."



        + (



            f" Unmatched report: {os.path.basename(str(_unmatched_report.get('txt','')))}"



            if isinstance(_unmatched_report, dict)



            else ""



        )



    )







    try:



        _context_cal = _context_calibration_runner(



            reason="after_grading",



            force=False,



            min_interval_minutes=180,



        )



        if isinstance(_context_cal, dict):



            _ctx_upd = int(_context_cal.get("updated_sports", 0) or 0)



            _ctx_msg = str(_context_cal.get("status", "") or "").strip()



            if _ctx_upd > 0:



                log(



                    f"[context-calibration] updated={_ctx_upd} "



                    f"file={_context_cal.get('params_file','')} status={_ctx_msg}",



                    "info",



                )



                try:



                    _sports = dict(_context_cal.get("sports") or {})



                    for _lg, _meta in sorted(_sports.items()):



                        if str((_meta or {}).get("status", "")).upper() != "UPDATED":



                            continue



                        _ovr = _context_get_sport_params(_lg)



                        _w1 = _to_float_or_none(_ovr.get("weather_rho_off_divisor"))



                        _w2 = _to_float_or_none(_ovr.get("weather_rho_def_divisor"))



                        _w3 = _to_float_or_none(_ovr.get("weather_headwind_divisor"))



                        _c1 = _to_float_or_none(_ovr.get("circadian_off_divisor"))



                        _c2 = _to_float_or_none(_ovr.get("circadian_def_divisor"))



                        log(



                            f"[context-calibration] {_lg} coeffs "



                            f"rho_off={_w1 if _w1 is not None else 'n/a'} "



                            f"rho_def={_w2 if _w2 is not None else 'n/a'} "



                            f"headwind={_w3 if _w3 is not None else 'n/a'} "



                            f"circ_off={_c1 if _c1 is not None else 'n/a'} "



                            f"circ_def={_c2 if _c2 is not None else 'n/a'}",



                            "info",



                        )



                except (ValueError, TypeError, KeyError) as _e:



                    _warn_exception("silent_except", _e)

            else:



                log(f"[context-calibration] status={_ctx_msg}", "info")



    except (OSError, ValueError, TypeError, RuntimeError) as _ctx_cal_err:



        log(f"[context-calibration] failed: {_ctx_cal_err}", "warning")







    root.after(0, _pk_load_history)



    root.after(0, _pk_update_dual_accuracy)



    root.after(0, _rpt_refresh_history_dropdown)











def _pk_update_dual_accuracy():



    """Update both accuracy panels ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â YOUR picks and MODEL picks."""



    def _stats(rows):



        w=l=p=0



        for r in rows:



            if r=="WIN": w+=1



            elif r=="LOSS": l+=1



            elif r=="PUSH": p+=1



        tot = w+l+p



        pct = round(w/max(tot-p,1)*100,1) if tot>0 else 0.0



        return w, l, p, tot, pct



    try:



        con = _pk_connect()



        # Your picks



        your_results = [r[0] for r in con.execute(



            "SELECT UPPER(TRIM(COALESCE(pick_result,''))) FROM picks "



            "WHERE UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')").fetchall()]



        yw,yl,yp,yt,ypct = _stats(your_results)



        # Model picks



        mod_results = [r[0] for r in con.execute(



            "SELECT UPPER(TRIM(COALESCE(pick_result,''))) FROM model_picks "



            "WHERE UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')").fetchall()]



        mw,ml,mp,mt,mpct = _stats(mod_results)



        con.close()



    except (OSError, ValueError, TypeError) as _e:



        pk_acc_var.set(f"DB error: {_e}"); return



    # ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ YOUR PICKS panel ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬



    if yt == 0:



        pk_acc_var.set("No completed picks yet.")



    else:



        # Sport-by-sport



        try:



            con2 = _pk_connect()



            by_lg = {}



            for lg, res in con2.execute(



                "SELECT league, UPPER(TRIM(COALESCE(pick_result,''))) FROM picks "



                "WHERE UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')").fetchall():



                by_lg.setdefault(lg,[]).append(res)



            con2.close()



        except (OSError, json.JSONDecodeError, ValueError, TypeError) as _e:



            by_lg = {}



            log(f"[records] analyst by-league query failed: {_e}", "warning")



        lines = [f"Overall: {yw}-{yl}-{yp}  ({ypct}% win rate)"]



        for lg in sorted(by_lg):



            lr = by_lg[lg]; lw=lr.count("WIN"); ll=lr.count("LOSS"); lp=lr.count("PUSH")



            lt = lw+ll+lp; lpct = round(lw/max(lt-lp,1)*100,1)



            be = "ABOVE" if lpct > 52.4 else "BELOW"



            lines.append(f"  {lg:7s} {lw}-{ll}-{lp}  ({lpct}%) {be}")



        pk_acc_var.set("\n".join(lines))



    # ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ MODEL PICKS panel ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬



    if mt == 0:



        pk_macc_var.set("No model picks graded yet.")



    else:



        try:



            con3 = _pk_connect()



            by_mlg = {}



            for lg, res in con3.execute(



                "SELECT league, UPPER(TRIM(COALESCE(pick_result,''))) FROM model_picks "



                "WHERE UPPER(TRIM(COALESCE(pick_result,''))) IN ('WIN','LOSS','PUSH')").fetchall():



                by_mlg.setdefault(lg,[]).append(res)



            con3.close()



        except (OSError, ValueError, TypeError, RuntimeError) as _e:



            by_mlg = {}



            log(f"[records] model by-league query failed: {_e}", "warning")



        be_overall = "ABOVE" if mpct > 52.4 else "BELOW"



        mlines = [f"Overall: {mw}-{ml}-{mp}  ({mpct}%)  {be_overall} break-even"]



        for lg in sorted(by_mlg):



            mr = by_mlg[lg]; mwl=mr.count("WIN"); mll=mr.count("LOSS"); mpl=mr.count("PUSH")



            mtl = mwl+mll+mpl; mpctlg = round(mwl/max(mtl-mpl,1)*100,1)



            be2 = "ABOVE" if mpctlg > 52.4 else "BELOW"



            mlines.append(f"  {lg:7s} {mwl}-{mll}-{mpl}  ({mpctlg}%) {be2}")



        pk_macc_var.set("\n".join(mlines))



    _refresh_tpk_record_summary()











def _refresh_tpk_record_summary():



    """Mirror analyst/model record status into both pick sections."""



    try:



        con = _pk_connect()



        model_rows = con.execute("SELECT pick_result FROM model_picks").fetchall()



        analyst_rows = con.execute("SELECT pick_result FROM picks").fetchall()



        _today_iso = datetime.now().strftime("%Y-%m-%d")



        model_rows_today = con.execute(



            "SELECT pick_result FROM model_picks WHERE date(COALESCE(game_date,'')) = date()",



            (_today_iso,),



        ).fetchall()



        analyst_rows_today = con.execute(



            "SELECT pick_result FROM picks WHERE date(COALESCE(game_date,'')) = date()",



            (_today_iso,),



        ).fetchall()



        con.close()



    except (OSError, ValueError, TypeError) as _e:



        _model_msg = f"Model Record unavailable: {_e}"



        _strip_msg = f"Analyst Record unavailable | {_model_msg} | {_picktracker_persistence_summary()}"



    else:



        _stale_model_pending = 0



        try:



            _cutoff_7d = (datetime.now().date() - timedelta(days=7)).isoformat()



            _con_stale = _pk_connect()



            try:



                _stale_model_pending = int(_con_stale.execute(



                    "SELECT COUNT(*) FROM model_picks "



                    "WHERE UPPER(TRIM(COALESCE(pick_result,'PENDING')))='PENDING' "



                    "AND TRIM(COALESCE(game_date,'')) <> '' "



                    "AND date(game_date) <= date()",



                    (_cutoff_7d,),



                ).fetchone()[0] or 0)



            finally:



                _con_stale.close()



        except GUI_ERRORS:



            _stale_model_pending = 0



        def _norm_result(_rv):



            _txt = str(_rv or "").strip().upper()



            return _txt if _txt else "PENDING"



        def _fmt_record(label, rows, stale_pending=0, rows_today=None):



            wins = sum(1 for (r,) in rows if _norm_result(r) == "WIN")



            loss = sum(1 for (r,) in rows if _norm_result(r) == "LOSS")



            push = sum(1 for (r,) in rows if _norm_result(r) == "PUSH")



            pending = sum(1 for (r,) in rows if _norm_result(r) not in {"WIN", "LOSS", "PUSH", "VOID", "NO_PLAY"})



            graded = wins + loss + push



            pct = round((wins / max(wins + loss, 1)) * 100.0, 1) if (wins + loss) > 0 else 0.0



            _msg = f"{label} {wins}-{loss}-{push} ({pct}%) | all_time graded={graded} pending={pending}"



            if rows_today is not None:



                tw = sum(1 for (r,) in rows_today if _norm_result(r) == "WIN")



                tl = sum(1 for (r,) in rows_today if _norm_result(r) == "LOSS")



                tp = sum(1 for (r,) in rows_today if _norm_result(r) == "PUSH")



                tpend = sum(1 for (r,) in rows_today if _norm_result(r) not in {"WIN", "LOSS", "PUSH", "VOID", "NO_PLAY"})



                _msg += f" | today graded={tw+tl+tp} pending={tpend}"



            if int(stale_pending or 0) > 0:



                _msg += f" stale_pending_7d={int(stale_pending)}"



            return _msg



        _analyst_msg = _fmt_record("Analyst Record", analyst_rows, rows_today=analyst_rows_today)



        _model_msg = _fmt_record(



            "Model Record",



            model_rows,



            stale_pending=_stale_model_pending,



            rows_today=model_rows_today,



        )



        _db_mode = _picktracker_persistence_summary()



        _strip_msg = f"{_analyst_msg}    |    {_model_msg}    |    {_db_mode}"



    _model_msg = _clean_display_text(_model_msg)



    _strip_msg = _clean_display_text(_strip_msg)







    def _apply_records():



        try:



            if "_tpk_record_var" in globals():



                _tpk_record_var.set(_model_msg)



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

        try:



            if "_tpk_record_strip_var" in globals():



                _tpk_record_strip_var.set(_strip_msg)



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

        try:



            if "pk_record_strip_var" in globals():



                pk_record_strip_var.set(_strip_msg)



        except _sqlite3.Error as _e:



            _warn_exception("silent_except", _e)

    try:



        if threading.current_thread() is threading.main_thread():



            _apply_records()



        else:



            root.after(0, _apply_records)



    except GUI_ERRORS as _e:



        _warn_exception("silent_except", _e)

def _pk_load_history():



    """Reload pick history from DB into the treeview."""



    pk_tree.delete(*pk_tree.get_children())



    try:



        con = _pk_connect()



        rows = con.execute("""SELECT id, game_date, game_time, away_team, home_team,



                               ou_line, pick, confidence, pick_result, actual_total, notes



                               FROM picks ORDER BY id DESC LIMIT 200""").fetchall()



        con.close()



    except (_sqlite3.Error, OSError, ValueError, TypeError):



        return



    for r in rows:



        row_id, gdate, gtime, away, home, line, pick, conf, result, actual, notes = r



        result = result or "PENDING"



        tag = {"WIN":"win","LOSS":"loss","PUSH":"push"}.get(result,"pend")



        try:



            line_txt = f"{float(line):.1f}" if line is not None and str(line).strip() != "" else "--"



        except (TypeError, ValueError):



            line_txt = "--"



        try:



            actual_txt = f"{float(actual):.1f}" if actual is not None and str(actual).strip() != "" else "--"



        except (TypeError, ValueError):



            actual_txt = "--"



        pk_tree.insert("","end", iid=str(row_id), tags=(tag,), values=(



            _clean_display_text(gdate or ""),



            _clean_display_text(gtime or ""),



            _clean_display_text(away or ""),



            _clean_display_text(home or ""),



            line_txt,



            _clean_display_text(pick or "--"),



            _clean_display_text(str(conf) if conf not in (None, "") else "--"),



            _clean_display_text(result),



            actual_txt,



            _clean_display_text(notes or ""),



        ))



    _pk_update_dual_accuracy()

    try:

        root.after(0, _all_history_load)

    except (RuntimeError, tk.TclError, AttributeError) as _hist_refresh_err:

        log(f"[pick_history] async refresh schedule failed: {_hist_refresh_err}", "warning")





def _pk_save_result():



    sel = pk_tree.focus()



    if not sel:



        _pk_set_status("[WARN] Select a pick in the history grid first.")



        return



    try:



        actual_val = float(pk_actual_var.get()) if pk_actual_var.get() else None



    except ValueError:



        actual_val = None



    result_val = pk_result_var.get()



    _pk_write_transaction(



        lambda _con: _con.execute(



            "UPDATE picks SET actual_total=, pick_result= WHERE id=",



            (actual_val, result_val, int(sel)),



        )



    )



    _pk_set_status(f"[OK] Result saved: {result_val}  (actual {actual_val})")



    _pk_load_history()







def _pk_update_accuracy():



    """Backward-compatible alias: dual-panel updater is authoritative."""



    _pk_update_dual_accuracy()



    return







    """Compute rolling accuracy and factor breakdown, show in summary bar."""



    try:



        con = _pk_connect()



        rows = con.execute("""SELECT pick, pick_result, air_dens_pct, headwind_mph,



                               elev_delta_ft, confidence



                               FROM picks WHERE pick_result IN ('WIN','LOSS','PUSH')""").fetchall()



        con.close()



    except (_sqlite3.Error, OSError, ValueError, TypeError):



        return



    if not rows:



        pk_acc_var.set("No completed picks yet.")



        return







    total = len(rows)



    wins  = sum(1 for r in rows if r[1]=="WIN")



    losses= sum(1 for r in rows if r[1]=="LOSS")



    pushes= sum(1 for r in rows if r[1]=="PUSH")



    pct   = wins/(wins+losses)*100 if (wins+losses)>0 else 0







    # Factor breakdown: when dense air was a factor (rho_pct > 1.5), did UNDER win->



    dense_under = [r for r in rows if r[0]=="UNDER" and r[2] and r[2]>1.5]



    dense_under_w = sum(1 for r in dense_under if r[1]=="WIN")



    dense_pct = dense_under_w/len(dense_under)*100 if dense_under else None







    hw_under = [r for r in rows if r[0]=="UNDER" and r[3] and r[3]<-4]



    hw_under_w = sum(1 for r in hw_under if r[1]=="WIN")



    hw_pct = hw_under_w/len(hw_under)*100 if hw_under else None







    # Per-sport breakdown



    try:



        sport_con = _pk_connect()



        sport_rows = sport_con.execute(



            "SELECT league, pick_result FROM picks WHERE pick_result IN ('WIN','LOSS','PUSH')"



        ).fetchall()



        sport_con.close()



    except GUI_ERRORS:



        sport_rows = []







    sport_records = {}



    for lg, res in sport_rows:



        if not lg: lg = "->"  



        r = sport_records.setdefault(lg, {"W":0,"L":0,"P":0})



        if res=="WIN": r["W"]+=1



        elif res=="LOSS": r["L"]+=1



        elif res=="PUSH": r["P"]+=1







    parts = [f"YOUR PICKS ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â Overall: {wins}W-{losses}L-{pushes}P  ({pct:.1f}%)"]



    if dense_pct is not None:



        parts.append(f"  Dense airÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢UNDER: {dense_under_w}/{len(dense_under)} ({dense_pct:.0f}%)")



    if hw_pct is not None:



        parts.append(f"  HeadwindÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢UNDER: {hw_under_w}/{len(hw_under)} ({hw_pct:.0f}%)")



    if sport_records:



        sport_str = "  |  By Sport: " + "  ".join(



            f"{lg}: {r['W']}W-{r['L']}L" for lg,r in sorted(sport_records.items()))



        parts.append(sport_str)







    pk_acc_var.set("  ".join(parts))











# Load history on startup + auto-repair leagues + repopulate model picks



root.after(500, _pk_load_history)



root.after(1200, _repair_leagues)



root.after(1600, _refresh_tpk_record_summary)







def _pk_autograde_startup():



    """Grade any pending picks automatically on startup."""



    def _runner():



        try:



            _pk_auto_grade()



        except (RuntimeError, ValueError, TypeError, OSError, _sqlite3.Error) as _e:



            log(f"[grade:auto-startup] {_e}", "warning")



    threading.Thread(target=_runner, daemon=True).start()







root.after(3500, _pk_autograde_startup)











def _context_calibration_tick():

    """



    Periodic context calibration pass so sport coefficients stay fresh even



    when grading cadence is uneven.



    """



    def _runner():



        try:



            _ctx = _context_calibration_runner(



                reason="scheduled_tick",



                force=False,



                min_interval_minutes=360,  # ~6h



            )



            if isinstance(_ctx, dict):



                _st = str(_ctx.get("status", "") or "").strip()



                _upd = int(_ctx.get("updated_sports", 0) or 0)



                if _st not in {"SKIPPED_FRESH", "SKIPPED_BUSY"} or _upd > 0:



                    log(f"[context-calibration] tick status={_st} updated={_upd}", "info")



        except (RuntimeError, ValueError, TypeError, OSError) as _e:



            log(f"[context-calibration] tick failed: {_e}", "warning")



    threading.Thread(target=_runner, daemon=True).start()

    try:

        root.after(6 * 60 * 60 * 1000, _context_calibration_tick)

    except (RuntimeError, tk.TclError) as _sched_err:

        _code = _startup_error_code(_sched_err, prefix="context_calibration_schedule")

        log(f"[context-calibration] reschedule failed: {_code}: {_sched_err}", "warning")









root.after(90000, _context_calibration_tick)











