import json as _mw_json







_MW_FILE      = str(_resolve_runtime_data_file("model_weights.json"))



_FACTOR_KEYS  = ["air_density", "headwind", "elevation", "temperature", "pressure"]



_SPORTS_LIST  = ["MLB", "NBA", "NHL", "NFL", "NCAAB", "NCAAF"]







def _load_model_weights():

    try:

        with open(_MW_FILE, encoding="utf-8") as f:

            return _mw_json.load(f)

    except (FileNotFoundError, OSError, ValueError, TypeError, json.JSONDecodeError) as _mw_load_err:

        log(f"[model_weights] load failed -> defaults in use: {_mw_load_err}", "warning")

        return {}





def _save_model_weights(w):



    os.makedirs(os.path.dirname(_MW_FILE) or ODDS_DIR, exist_ok=True)



    _tmp = _MW_FILE + ".tmp"



    try:



        with open(_tmp, "w", encoding="utf-8") as f:



            _mw_json.dump(w, f, indent=2)



        os.replace(_tmp, _MW_FILE)



    finally:

        try:

            if os.path.exists(_tmp):

                os.unlink(_tmp)

        except OSError as _mw_tmp_err:

            log(f"[model_weights] temp cleanup failed for {_tmp}: {_mw_tmp_err}", "warning")





def _tune_model_weights():

    """



    Real calibration ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â delegates to model_calibration.run_calibration().



    Reads game_context.db, runs per-league logistic regression,



    updates model_weights.json. Respects MIN_SAMPLES_TO_RETRAIN guard.



    """



    try:

        _mcd = os.path.join(ODDS_DIR, "model_calibration.py")

        reports = _core_run_model_calibration_from_file(Path(_mcd))

        _meta = dict(reports.get("__meta__", {}) or {}) if isinstance(reports, dict) else {}

        _meta_status = str(_meta.get("status", "") or "").strip().lower()

        if _meta_status and _meta_status != "ok":

            log(

                f"[model_weights] calibration metadata status={_meta_status} "

                f"type={_meta.get('error_type', '')} detail={_meta.get('error', '')}",

                "warning",

            )

        if reports:

            summary = ", ".join(

                f"{lg}: {r.get('status','->')} "

                f"({r.get('acc_before',0):.0%}->{r.get('acc_after',0):.0%})"

                for lg, r in reports.items()

                if isinstance(r, dict) and lg != "__meta__" and r.get("status") == "updated"

            )

            if summary:

                log(f"Weights recalibrated -> {summary}", "info")

            try:

                _updated = [

                    lg for lg, r in (reports or {}).items()

                    if lg != "__meta__" and isinstance(r, dict) and str(r.get("status", "")).lower() == "updated"

                ]

                _updated_txt = ",".join(_updated) if _updated else "none"

                _note = (

                    f"Calibration run complete. updated_leagues={_updated_txt}; "

                    f"meta_status={_meta.get('status', 'n/a')}; summary={summary or 'no_updates'}"

                )

                _audit_write_note(_note, trigger="auto_calibration")

            except (OSError, ValueError, TypeError, RuntimeError) as _audit_err:

                log(f"[audit] calibration note write failed: {_audit_err}", "warning")

    except (OSError, ValueError, TypeError, RuntimeError, ImportError, AttributeError) as _e:



        log(f"_tune_model_weights: {_e}", "warning")











def _on_matchup_league_change(event=None):



    matchup_tree.delete(*matchup_tree.get_children())



    _slate_set_detail_empty("No matchup selected")



    m_status_var.set("League changed - click Refresh Slate.")



    _set_matchup_load_progress(0.0, "waiting for fetch")



m_league_cb.bind("<<ComboboxSelected>>", _on_matchup_league_change)







