ttk.Label(_tpk_ctrl, textvariable=_tpk_record_var, style="Subtle.TLabel").pack(side=tk.RIGHT, padx=8)



_tpk_auto_refresh_var = tk.BooleanVar(value=bool(_tpk_settings.get("auto_interval_enabled")))



_tpk_interval_var = tk.StringVar(value=str(_tpk_settings.get("auto_interval_min", "15") or "15"))



ttk.Label(_tpk_ctrl, text="Interval (min):").pack(side=tk.RIGHT, padx=(8,2))



_tpk_interval_cb = ttk.Combobox(



    _tpk_ctrl,



    textvariable=_tpk_interval_var,



    values=["5", "10", "15", "30", "60"],



    width=4,



    state="readonly",



)



_tpk_interval_cb.pack(side=tk.RIGHT, padx=(0,4))



_tpk_auto_chk = ttk.Checkbutton(_tpk_ctrl, text="Auto-Run", variable=_tpk_auto_refresh_var)



_tpk_auto_chk.pack(side=tk.RIGHT, padx=4)



_tpk_auto_job = None



_tpk_scheduler_job = None



_tpk_scheduler_boot_state = {"checked": False}







_tpk_status_row = ttk.Frame(picks_tab_frame)



_tpk_status_row.pack(fill=tk.X, padx=10, pady=(2, 0))



_tpk_status_label = ttk.Label(



    _tpk_status_row,



    textvariable=_tpk_status,



    style="Subtle.TLabel",



    anchor="w",



    justify="left",



)



_tpk_status_label.pack(fill=tk.X, expand=True)







_tpk_sport_btn_row = ttk.Frame(picks_tab_frame)



_tpk_sport_btn_row.pack(fill=tk.X, padx=10, pady=(0, 2))



ttk.Label(_tpk_sport_btn_row, text="Run League:", style="Subtle.TLabel").pack(side=tk.LEFT, padx=(0, 4))



for _sp in _TPK_SPORTS:



    ttk.Button(



        _tpk_sport_btn_row,



        text=_sp,



        width=6,



        command=lambda _sport=_sp: _launch_tpk_refresh_async(target_sports=[_sport], reason=f"manual:{_sport}"),



    ).pack(side=tk.LEFT, padx=2)



ttk.Button(



    _tpk_sport_btn_row,



    text="Run Enabled",



    command=lambda: _launch_tpk_refresh_async(target_sports=_tpk_enabled_sports(), reason="manual:enabled"),



).pack(side=tk.LEFT, padx=6)



_tpk_record_strip_var = tk.StringVar(value="Analyst Record -- | Model Record --")



ttk.Label(



    picks_tab_frame,



    textvariable=_tpk_record_strip_var,



    style="Subtle.TLabel",



).pack(fill=tk.X, padx=12, pady=(0, 2))



_tpk_scheduler_strip_var = tk.StringVar(value="Scheduler: startup=OFF auto-interval=OFF")



ttk.Label(



    picks_tab_frame,



    textvariable=_tpk_scheduler_strip_var,



    style="Subtle.TLabel",



).pack(fill=tk.X, padx=12, pady=(0, 2))



_refresh_tpk_scheduler_strip()







def _tpk_set_status(msg):



    root.after(0, lambda m=str(msg): _tpk_status.set(_clean_display_text(m)))







def _tpk_status_on_resize(_evt=None):



    try:



        _w = int(_tpk_status_row.winfo_width() or 0)



        if _w > 40:



            _tpk_status_label.configure(wraplength=max(200, _w - 24))



    except GUI_ERRORS as _e:



        _warn_exception("silent_except", _e)

try:

    _tpk_status_row.bind("<Configure>", _tpk_status_on_resize)

    root.after(0, _tpk_status_on_resize)

except (RuntimeError, tk.TclError, AttributeError) as _tpk_status_bind_err:

    log(f"[tpk_ui] status row bind failed: {_tpk_status_bind_err}", "warning")





def _gate_reason_code_from_issues(issues, default_code="unknown_gate_block"):

    return _core_gate_reason_code_from_issues(issues, default_code=str(default_code or "unknown_gate_block"))









def _classify_pick_pipeline_exception(exc):

    return _core_classify_pick_pipeline_exception(exc)





def _startup_error_code(exc, prefix="startup"):

    return _core_startup_error_code(exc, prefix=str(prefix or "startup"))





