def _mlb_db_health_report():



    """Return a completeness report for today's MLB pregame DB."""



    import sqlite3 as _sq







    today = datetime.now().strftime("%Y-%m-%d")



    REQUIRED_MLB_DB_SCHEMA_VERSION = 2



    db = MLB_PREGAME_DB_PATH



    report = {



        "ok": False,



        "today": today,



        "db_path": db,



        "reason": "DB missing.",



        "games": 0,



        "expected_team_rows": 0,



        "expected_starter_rows": 0,



        "starter_rows": 0,



        "starter_blank_throws": 0,



        "team_rows": 0,



        "team_missing_xwoba": 0,



        "team_missing_vs_rhp": 0,



        "team_missing_vs_lhp": 0,



        "matchups_missing_summary": 0,



        "schema_missing": [],



        "required_null_fields": [],



        "optional_null_fields": [],



        "partial": False,



        "needs_refresh": True,



        "warnings": [],



    }



    if not os.path.exists(db):



        return report







    con = None



    try:



        con = _sq.connect(db)







        required_schema = {



            "pregame_matchups": ["game_date", "away_team", "home_team", "matchup_summary"],



            "team_stats": [



                "team_name", "fetched_date", "ops_vs_rhp", "ops_vs_lhp", "bullpen_era",



                "runs_per_game", "xwoba", "hard_hit_pct", "ops", "ops_last14",



                "runs_last14", "bullpen_era_7d", "bullpen_ip_3d",



            ],



            "starter_stats": [



                "player_name", "team_name", "fetched_date", "throws", "era", "whip",



                "k_pct", "bb_pct", "gb_pct", "fb_pct", "density_sensitivity",



                "era_last3", "avg_pc_last3", "avg_ip_last3",



            ],



        }



        schema_missing = []



        for table, cols in required_schema.items():

            try:

                have = {

                    str(r[1] or "").strip()

                    for r in con.execute(f"PRAGMA table_info({table})").fetchall()

                }

            except _sq.Error as _tbl_info_err:

                have = set()

                report["warnings"].append(f"table_info_failed:{table}:{type(_tbl_info_err).__name__}")

            if not have:



                schema_missing.append(f"{table}:table_missing")



                continue



            for col in cols:



                if col not in have:



                    schema_missing.append(f"{table}.{col}")



        if schema_missing:



            report["schema_missing"] = schema_missing



            report["reason"] = "MLB DB schema missing required projection fields: " + ", ".join(schema_missing[:12])



            if len(schema_missing) > 12:



                report["reason"] += f" (+{len(schema_missing) - 12} more)"



            return report



        try:

            _schema_row = con.execute(

                "SELECT value FROM schema_meta WHERE key='mlb_pregame_schema_version'"

            ).fetchone()

            _schema_ver = int(str((_schema_row[0] if _schema_row else "")).strip()) if _schema_row else 0

        except (_sqlite3.Error, ValueError, TypeError) as _schema_ver_err:

            _schema_ver = 0

            report["warnings"].append(f"schema_version_read_failed:{type(_schema_ver_err).__name__}")

        if _schema_ver < REQUIRED_MLB_DB_SCHEMA_VERSION:



            report["schema_missing"] = [f"schema_meta.mlb_pregame_schema_version<{REQUIRED_MLB_DB_SCHEMA_VERSION}"]



            report["reason"] = (



                f"MLB DB schema version missing/stale (found={_schema_ver}, "



                f"required>={REQUIRED_MLB_DB_SCHEMA_VERSION}); rebuild required."



            )



            return report







        def _scalar(sql, params=(today,)):

            try:

                return int(con.execute(sql, params).fetchone()[0] or 0)

            except (_sqlite3.Error, ValueError, TypeError) as _scalar_err:

                report["warnings"].append(f"scalar_query_failed:{type(_scalar_err).__name__}")

                return 0





        report["games"] = _scalar(



            "SELECT COUNT(*) FROM pregame_matchups WHERE game_date="



        )



        try:

            _meta_row = con.execute(

                "SELECT data_date, build_state, model_safe FROM build_meta ORDER BY completed_at DESC, started_at DESC LIMIT 1"

            ).fetchone()

        except _sqlite3.Error as _meta_err:

            _meta_row = None

            report["warnings"].append(f"build_meta_query_failed:{type(_meta_err).__name__}")

        _meta_date = ""



        _meta_state = ""



        _meta_safe = 0



        if _meta_row:



            _meta_date = str(_meta_row[0] or "").strip()



            _meta_state = str(_meta_row[1] or "").upper().strip()



            _meta_safe = int(_meta_row[2] or 0)



            if _meta_state not in {"READY", "DEGRADED"}:



                report["warnings"].append(f"build_meta_state:{_meta_state or 'UNKNOWN'}")



            if _meta_safe not in {0, 1}:



                report["warnings"].append(f"build_meta_model_safe_invalid:{_meta_safe}")



        else:



            report["warnings"].append("build_meta_missing")



        report["expected_team_rows"] = report["games"] * 2



        report["expected_starter_rows"] = report["games"] * 2



        report["starter_rows"] = _scalar(



            "SELECT COUNT(*) FROM starter_stats WHERE fetched_date="



        )



        report["starter_blank_throws"] = _scalar(



            "SELECT COUNT(*) FROM starter_stats "



            "WHERE fetched_date= AND (throws IS NULL OR TRIM(throws)='')"



        )



        report["team_rows"] = _scalar(



            "SELECT COUNT(*) FROM team_stats WHERE fetched_date="



        )



        report["team_missing_xwoba"] = _scalar(



            "SELECT COUNT(*) FROM team_stats WHERE fetched_date= AND xwoba IS NULL"



        )



        report["team_missing_vs_rhp"] = _scalar(



            "SELECT COUNT(*) FROM team_stats WHERE fetched_date= AND ops_vs_rhp IS NULL"



        )



        report["team_missing_vs_lhp"] = _scalar(



            "SELECT COUNT(*) FROM team_stats WHERE fetched_date= AND ops_vs_lhp IS NULL"



        )



        report["matchups_missing_summary"] = _scalar(



            "SELECT COUNT(*) FROM pregame_matchups "



            "WHERE game_date= AND (matchup_summary IS NULL OR TRIM(matchup_summary)='')"



        )







        reasons = []



        health_warnings = []



        games = report["games"]



        expected_team_rows = report["expected_team_rows"]



        expected_starter_rows = report["expected_starter_rows"]



        team_missing_limit = max(1, expected_team_rows // 4) if expected_team_rows else 0



        starter_missing_limit = max(1, expected_starter_rows // 6) if expected_starter_rows else 0



        summary_missing_limit = max(1, games // 3) if games else 0







        if games <= 0:



            reasons.append("no pregame_matchups rows for today")



        if not _meta_date:



            reasons.append("build_meta missing latest build metadata")



        elif _meta_date != today:



            reasons.append(f"build_meta stale date {_meta_date} (expected {today})")



        if _meta_state and _meta_state not in {"READY", "DEGRADED"}:



            reasons.append(f"build_meta invalid state {_meta_state}")



        if _meta_state == "READY" and _meta_safe == 0:



            reasons.append("build_meta inconsistent READY state with model_safe=0")



        if report["starter_rows"] < expected_starter_rows:



            health_warnings.append(



                f"starter rows {report['starter_rows']}/{expected_starter_rows}"



            )



        if report["team_rows"] < expected_team_rows:



            health_warnings.append(



                f"team rows {report['team_rows']}/{expected_team_rows}"



            )



        if report["starter_blank_throws"] > starter_missing_limit:



            health_warnings.append(



                f"blank starter throws {report['starter_blank_throws']}/{report['starter_rows'] or expected_starter_rows}"



            )



        if report["team_missing_vs_rhp"] > team_missing_limit:



            health_warnings.append(



                f"missing ops_vs_rhp {report['team_missing_vs_rhp']}/{report['team_rows'] or expected_team_rows}"



            )



        if report["team_missing_vs_lhp"] > team_missing_limit:



            health_warnings.append(



                f"missing ops_vs_lhp {report['team_missing_vs_lhp']}/{report['team_rows'] or expected_team_rows}"



            )



        if report["matchups_missing_summary"] > summary_missing_limit:



            health_warnings.append(



                f"missing matchup summaries {report['matchups_missing_summary']}/{games}"



            )



        required_null_fields = []



        team_required_value_cols = [



            "ops_vs_rhp", "ops_vs_lhp", "runs_per_game", "ops",



        ]



        starter_required_value_cols = [



            "throws", "era", "whip", "k_pct", "bb_pct", "gb_pct", "fb_pct",



            "era_last3", "avg_ip_last3",



        ]



        for col in team_required_value_cols:



            missing = _scalar(



                f"SELECT COUNT(*) FROM team_stats WHERE fetched_date= AND ({col} IS NULL OR TRIM(CAST({col} AS TEXT))='')"



            )



            if missing > team_missing_limit:



                required_null_fields.append(f"team_stats.{col}:{missing}/{report['team_rows'] or expected_team_rows}")



        for col in starter_required_value_cols:



            missing = _scalar(



                f"SELECT COUNT(*) FROM starter_stats WHERE fetched_date= AND ({col} IS NULL OR TRIM(CAST({col} AS TEXT))='')"



            )



            if missing > starter_missing_limit:



                required_null_fields.append(f"starter_stats.{col}:{missing}/{report['starter_rows'] or expected_starter_rows}")



        if required_null_fields:



            report["required_null_fields"] = required_null_fields



            health_warnings.append("MLB DB required projection fields blank: " + ", ".join(required_null_fields[:10]))



        optional_null_fields = []



        team_optional_value_cols = [



            "bullpen_era", "xwoba", "hard_hit_pct", "ops_last14",



            "runs_last14", "bullpen_era_7d", "bullpen_ip_3d",



        ]



        starter_optional_value_cols = ["density_sensitivity", "avg_pc_last3"]



        for col in team_optional_value_cols:



            missing = _scalar(



                f"SELECT COUNT(*) FROM team_stats WHERE fetched_date= AND ({col} IS NULL OR TRIM(CAST({col} AS TEXT))='')"



            )



            if missing:



                optional_null_fields.append(f"team_stats.{col}:{missing}/{report['team_rows'] or expected_team_rows}")



        for col in starter_optional_value_cols:



            missing = _scalar(



                f"SELECT COUNT(*) FROM starter_stats WHERE fetched_date= AND ({col} IS NULL OR TRIM(CAST({col} AS TEXT))='')"



            )



            if missing:



                optional_null_fields.append(f"starter_stats.{col}:{missing}/{report['starter_rows'] or expected_starter_rows}")



        report["optional_null_fields"] = optional_null_fields



        if health_warnings or optional_null_fields:



            report["partial"] = True



            report["warnings"] = (



                health_warnings + [



                    "MLB DB optional projection fields blank: " + ", ".join(optional_null_fields[:10])



                ]



            ) if optional_null_fields else health_warnings



            # Re-run only when required/core fields are incomplete.



            # Optional-field gaps are still reported per game but do not force a startup rebuild loop.



            report["needs_refresh"] = bool(health_warnings)



        else:



            report["needs_refresh"] = False







        report["ok"] = not reasons



        report["reason"] = (



            (



                "Today's MLB DB is usable but partial; incomplete games are blocked per game. "



                + "; ".join((report.get("warnings") or [])[:4])



            )



            if report["ok"] and report.get("partial")



            else "Today's MLB DB passed completeness checks."



            if report["ok"]



            else "; ".join(reasons)



        )



        return report



    except (OSError, ValueError, TypeError) as e:

        _code = _startup_error_code(e, prefix="mlb_db_health")

        report["reason"] = f"DB health check failed: {_code}: {e}"

        report["warnings"].append(f"health_exception:{_code}")

        return report

    finally:

        try:

            if con is not None:

                con.close()

        except _sq.Error as _close_err:

            report["warnings"].append(f"db_close_failed:{type(_close_err).__name__}")









def _mlb_db_is_fresh():



    """Backward-compatible bool check used by startup logic."""



    return _mlb_db_health_report().get("ok", False)











def _autoboot_mlb_stats():



    """



    Called once at startup in a daemon thread.



    If DB is missing or stale, runs mlb_stats_daily.py as a subprocess



    and streams its output to the Run Log. UI stays responsive throughout.



    """



    _task_name = "mlb_stats_daily"



    _should_run, _last = _startup_task_should_run(_task_name)



    _db_health = _mlb_db_health_report()



    if (not _should_run) and _db_health.get("ok") and not _db_health.get("needs_refresh"):



        _when = str(_last.get("updated_at", "") or "earlier today")



        log(



            f"[mlb_stats] Skipping mlb_stats_daily.py (already completed today at {_when}).",



            "info",



        )



        return



    if (not _should_run) and _db_health.get("ok") and _db_health.get("needs_refresh"):



        log("[mlb_stats] MLB pregame DB is usable but partial; refreshing to try to fill missing live fields.", "warning")



    elif (not _should_run) and (not _db_health.get("ok")):



        log("[mlb_stats] DB is stale/incomplete despite prior success marker ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â retrying build.", "warning")



    elif _should_run and _db_health.get("ok"):



        log(



            "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢  First-open daily policy: refreshing MLB pre-game stats even though DB is already healthy.",



            "info",



        )



    _startup_task_mark(



        _task_name,



        "running",



        started_at=datetime.now().astimezone().isoformat(),



        progress_pct=0.0,



        detail="starting",



    )







    log(



        "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢  Running mlb_stats_daily.py for daily startup policy ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â "



        f"auto-running mlb_stats_daily.py for {_db_health.get('today')} "



        f"because {_db_health.get('reason')}.",



        "info",



    )







    # Show a banner in the status bar of the Matchups tab



    root.after(0, lambda: m_status_var.set(



        "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢  Refreshing today's MLB pre-game stats for today's scheduled games only ..."))







    _script_candidates = [



        os.path.join(ODDS_DIR, "mlb_stats_daily.py"),   # relay shim



        str(SCRIPT_DIR / "mlb_stats_daily.py"),         # canonical builder



    ]



    script = next((p for p in _script_candidates if os.path.exists(p)), _script_candidates[0])



    if not os.path.exists(script):



        log(f"[WARN] mlb_stats_daily.py not found at {script}; skipping auto-boot.", "warning")



        root.after(0, lambda: m_status_var.set(



            "[WARN] mlb_stats_daily.py not found; pre-game stats unavailable."))



        _startup_task_mark(_task_name, "failed", error="script missing", progress_pct=100.0, detail="script missing")



        return







    import subprocess, sys



    try:



        proc = subprocess.Popen(



            [



                sys.executable,



                script,



                "--base-dir",



                str(RUNTIME_DB_DIR),



                "--date",



                _db_health.get("today") or datetime.now().strftime("%Y-%m-%d"),



            ],



            stdout=subprocess.PIPE,



            stderr=subprocess.STDOUT,



            text=True,



            encoding="utf-8",



            errors="replace",



            cwd=ODDS_DIR,



            env={**_runtime_env_copy(), "PYTHONIOENCODING": "utf-8", "PYTHONUTF8": "1"},



        )



        _mlb_progress_last = -1



        for line in proc.stdout:



            line = line.rstrip()



            if line:



                _prog_m = re.search(r"(\d{1,3})%\|", line)



                if _prog_m:

                    try:

                        _pct = int(_prog_m.group(1))

                    except (TypeError, ValueError) as _mlb_pct_err:

                        log(f"[mlb_stats] progress parse failed for line='{line[:80]}': {_mlb_pct_err}", "warning")

                        _pct = -1

                    if _pct >= 0:



                        if (_pct != 100) and (_pct % 5 != 0):



                            continue



                        if _pct == _mlb_progress_last:



                            continue



                        _mlb_progress_last = _pct



                        _startup_task_mark(



                            _task_name,



                            "running",



                            progress_pct=float(_pct),



                            detail=f"statcast pull {_pct}%",



                        )



                        line = f"progress {_pct}%"



                lvl = "warning" if any(x in line for x in ("ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ","WARN","ERROR","error")) else "info"



                log(f"[mlb_stats] {line}", lvl)



        proc.wait()



        if proc.returncode == 0:



            log("[OK] mlb_stats_daily.py auto-boot complete; DB populated.", "info")



            _startup_task_mark(_task_name, "success", progress_pct=100.0, detail="mlb pre-game stats loaded")



            root.after(0, lambda: m_status_var.set(



                "[OK] MLB pre-game stats loaded; double-click any game for full breakdown."))



        else:



            _health = _mlb_db_health_report()



            if _health.get("ok"):



                log(



                    f"[WARN] mlb_stats_daily.py exited with code {proc.returncode}, "



                    "but DB health checks passed; treating as usable build.",



                    "warning",



                )



                _startup_task_mark(



                    _task_name,



                    "success",



                    progress_pct=100.0,



                    detail=f"usable build (exit code {proc.returncode})",



                )



                root.after(0, lambda: m_status_var.set(



                    "MLB pre-game stats loaded with non-fatal warnings; see Run Log for details."



                ))



            else:



                log(f"[WARN] mlb_stats_daily.py exited with code {proc.returncode}.", "warning")



                _startup_task_mark(



                    _task_name,



                    "failed",



                    error=f"exit code {proc.returncode}",



                    progress_pct=100.0,



                    detail=f"exit code {proc.returncode}",



                )



                root.after(0, lambda: m_status_var.set(



                    f"[WARN] MLB stats auto-boot finished with errors (code {proc.returncode})."))



    except (AttributeError, OSError, RuntimeError, TypeError, ValueError) as e:



        _code = _startup_error_code(e, prefix="mlb_stats_autoboot")



        log(f"[mlb_stats] auto-boot failed: {_code}: {e}", "warning")



        _startup_task_mark(



            _task_name,



            "failed",



            error=str(e),



            error_code=_code,



            progress_pct=100.0,



            detail="exception",



        )



        _msg = str(e)



        root.after(0, lambda _m=_msg: m_status_var.set(f"[WARN] MLB stats auto-boot failed: {_m}"))











# Fire auto-boot in background ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â non-blocking, UI launches immediately



_start_daemon_after(1250, _autoboot_mlb_stats)







def _enforce_main_tab_order():



    try:



        _desired = [



            (matchups_frame, "Dashboard"),



            (console_frame, "System Console"),



            (games_frame, "Today's Slate"),



            (physics_frame, "Model"),



            (arsenal_frame, "Arsenal"),



            (execution_frame, "Picks"),



            (reports_frame, "Reports"),



        ]



        for _idx, (_frame, _label) in enumerate(_desired):



            if str(_frame) in main_tabs.tabs():



                main_tabs.insert(_idx, _frame)



                main_tabs.tab(_frame, text=_label)



        main_tabs.select(matchups_frame)



    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _ord_e:



        log(f"[ui] tab order enforcement failed: {_ord_e}", "warning")







def _finalize_startup_ui():

    _sanitize_fail_counts = {"configure": 0, "node": 0, "walk": 0}



    def _sanitize_widget_tree(_w):

        try:

            # Normalize static text labels/buttons/tabs that may carry legacy mojibake.

            if "text" in _w.keys():

                _raw = str(_w.cget("text") or "")

                _clean = _clean_display_text(_raw)

                if _clean != _raw:

                    try:

                        _w.configure(text=_clean)

                    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _cfg_err:

                        _sanitize_fail_counts["configure"] += 1

                        if _sanitize_fail_counts["configure"] <= 3:

                            log(f"[startup_ui] sanitize configure failed: {_cfg_err}", "warning")

        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _node_err:

            _sanitize_fail_counts["node"] += 1

            if _sanitize_fail_counts["node"] <= 3:

                log(f"[startup_ui] sanitize node failed: {_node_err}", "warning")

        try:

            for _ch in _w.winfo_children():

                _sanitize_widget_tree(_ch)

        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _walk_err:

            _sanitize_fail_counts["walk"] += 1

            if _sanitize_fail_counts["walk"] <= 3:

                log(f"[startup_ui] sanitize tree walk failed: {_walk_err}", "warning")





    try:

        _enforce_main_tab_order()

        _rpt_refresh_history_dropdown()

    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _final_tabs_err:

        log(f"[startup_ui] tab/dropdown finalize failed: {_final_tabs_err}", "warning")

    try:

        _apply_visual_profile(_shell_visual_var.get())

    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _final_theme_err:

        log(f"[startup_ui] visual profile apply failed: {_final_theme_err}", "warning")

    try:

        _sanitize_widget_tree(root)

    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _final_sanitize_err:

        log(f"[startup_ui] widget sanitize failed: {_final_sanitize_err}", "warning")

    try:

        if "_STARTUP_SPLASH" in globals() and _STARTUP_SPLASH is not None:

            _STARTUP_SPLASH.destroy()

    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _final_splash_err:

        log(f"[startup_ui] splash destroy failed: {_final_splash_err}", "warning")

    try:

        root.deiconify()

        root.state("zoomed")

        root.lift()

        root.focus_force()

    except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError) as _final_focus_err:

        log(f"[startup_ui] final window focus/zoom failed: {_final_focus_err}", "warning")





root.after(200, _finalize_startup_ui)







root.mainloop()

